        --foreground: var(--surface-hero-fg);
        --muted-foreground: var(--surface-hero-muted);
        --border-strong: var(--surface-hero-border);
        --input: var(--surface-hero-border);
        --selected: var(--surface-hero-primary);
        --primary: var(--surface-hero-primary);
        --primary-foreground: var(--surface-hero-primary-foreground);
        --destructive: var(--surface-hero-danger);
        --destructive-foreground: var(--surface-hero-danger-foreground);
        --card: var(--surface-hero-card);
        --card-foreground: var(--surface-hero-card-foreground);
        --link: var(--surface-hero-fg-2);
        --focus-ring: var(--surface-hero-fg);
        --focus-ring-contrast: var(--surface-hero-bg);
