        letter-spacing: 0.04em;
    }

    [data-theme='synthwave'] .kp-timestamp,
    [data-theme='synthwave'] .kp-id {
        color: var(--accent);
    }

    [data-theme='synthwave'] .kp-copyable__button {
        border: 1px solid var(--kp-hairline);
        border-radius: var(--radius);
        color: var(--accent);
    }

