    /* ── Pickers and palettes ─────────────────────────────────────────── */

    [data-theme='synthwave'] .kp-combobox__input,
    [data-theme='synthwave'] .kp-palette__input,
    [data-theme='synthwave'] .kp-datatable__search {
        background: var(--sidebar-background);
        border: 2px solid hsl(from var(--kp-pink-text) h s l / 0.35);
        border-radius: var(--radius);
        caret-color: var(--accent);
    }

    [data-theme='synthwave'] .kp-datepicker__day[aria-selected='true'] {
        background: var(--primary);
        color: var(--primary-foreground);
        box-shadow: 0 0 10px hsl(from var(--primary) h s l / 0.6);
        border-radius: var(--radius);
    }

    [data-theme='synthwave'] .kp-datepicker__weekday,
    [data-theme='synthwave'] .kp-datepicker__title {
        font-family: var(--kp-osd);
        letter-spacing: 0.1em;
        text-transform: uppercase;
