        content: '';
        position: absolute;
        inset: 0.05em -0.15em;
        background: var(--foreground);
        border-radius: 2px;
        clip-path: inset(0 100% 0 0);
        pointer-events: none;
    }

    [data-theme='shade-light'][data-kp-effects] .kp-card[data-kp-reveal='emphasis'] mark:not(.is-cleared)::after {
        clip-path: inset(0 0 0 0);
    }

    [data-theme='shade-light'][data-kp-effects] .kp-card[data-kp-reveal='emphasis'] mark:not(.is-cleared) {
        color: transparent;
    }

