    [data-theme='shade-light'] .kp-timeline__marker {
        background: var(--primary);
        border-radius: 999px;
    }

    [data-theme='shade-light'] .kp-timeline__when {
        font-family: var(--theme-font-mono);
        font-size: 0.8rem;
        color: var(--muted-foreground);
