    }

    [data-theme='shade-light'] .kp-tabs__list {
        border-bottom: 1px solid var(--border);
    }

    [data-theme='shade-light'] .kp-breadcrumb,
    [data-theme='shade-light'] .kp-pagination {
        font-size: 0.9rem;
    }

    [data-theme='shade-light'] .kp-pagination a[aria-current],
    [data-theme='shade-light'] .kp-pagination [aria-current] {
