    }

    [data-theme='shade-light'] .kp-theme-menu__status,
    [data-theme='shade-light'] .kp-palette__status,
    [data-theme='shade-light'] .kp-combobox__status {
        font-family: var(--theme-font-mono);
        font-size: 0.8rem;
    }

    /* ── The demo's own pieces: platforms line, spec sheet, footer ────── */

    [data-theme='shade-light'] .kp-platforms {
        font-family: var(--theme-font-mono);
        font-size: 0.78rem;
        letter-spacing: 0.04em;
        color: var(--muted-foreground);
        border-block-start: 1px solid var(--border);
    }

    [data-theme='shade-light'] .kp-spec {
        border: 1px solid var(--border-strong);
        border-radius: var(--radius);
        background: var(--card);
    }

    [data-theme='shade-light'] .kp-spec__title {
        font-family: var(--theme-font-mono);
        font-size: 0.7rem;
        letter-spacing: 0.1em;
        text-transform: uppercase;
        color: var(--muted-foreground);
    }

    [data-theme='shade-light'] .kp-spec__swatch {
        font-family: var(--theme-font-mono);
        font-size: 0.68rem;
        color: var(--muted-foreground);
    }

    [data-theme='shade-light'] .kp-spec__swatch .chip,
    [data-theme='shade-light'] .kp-spec__swatch span {
        border: 1px solid var(--border-strong);
        border-radius: calc(var(--radius) - 4px);
    }

    [data-theme='shade-light'] .kp-spec__font {
