    /* ── Windows: dialog, popover, menu, toast, tooltip and the rest ────── */

    [data-theme='grotesk'] .kp-dialog,
    [data-theme='grotesk'] .kp-popover,
    [data-theme='grotesk'] .kp-menu,
    [data-theme='grotesk'] .kp-toast,
    [data-theme='grotesk'] .kp-tooltip,
    [data-theme='grotesk'] .kp-confirm,
