        font-weight: 700;
    }

    [data-theme='grotesk'] .kp-grid__tile,
    [data-theme='grotesk'] .kp-split__pane {
        background: var(--background);
        border: 2px solid var(--border);
        border-radius: 0;
    }

    [data-theme='grotesk'] .kp-split__separator {
        background: var(--foreground);
        inline-size: 2px;
    }

    [data-theme='grotesk'] .kp-footer {
        background: var(--background);
        color: var(--muted-foreground);
    }

    [data-theme='grotesk'] .kp-footer h4 {
        font-family: var(--theme-font-display);
        font-weight: 800;
        font-size: 0.95rem;
    }

    [data-theme='grotesk'] .kp-footer a {
        color: var(--muted-foreground);
        text-decoration: none;
        font-size: 0.88rem;
