    }

    [data-theme='grotesk'] .kp-spinner {
        border-color: var(--border);
        border-top-color: var(--primary);
        border-radius: 0;
    }

    [data-theme='grotesk'] .kp-empty {
        border: 2px dashed var(--border);
        border-radius: 0;
    }

    [data-theme='grotesk'] .kp-empty__title {
        font-family: var(--theme-font-display);
        font-weight: 800;
    }

    [data-theme='grotesk'] .kp-error {
        font-family: var(--kp-mono);
        color: var(--destructive);
    }

    /* ── Text shapes: identifiers in the mono face ────────────────────── */

    [data-theme='grotesk'] .kp-id,
    [data-theme='grotesk'] .kp-url,
    [data-theme='grotesk'] .kp-numeric,
    [data-theme='grotesk'] .kp-timestamp,
    [data-theme='grotesk'] .kp-masked,
    [data-theme='grotesk'] .kp-copyable,
    [data-theme='grotesk'] .kp-truncate,
    [data-theme='grotesk'] .kp-cell-break,
    [data-theme='grotesk'] .kp-cell-truncate {
