        font-weight: 800;
        font-size: 0.9rem;
        letter-spacing: 0.02em;
        border-block-end: 3px solid var(--foreground);
    }

    [data-theme='grotesk'] .kp-table td {
        border-block-end: 1px solid var(--border);
    }

    [data-theme='grotesk'] .kp-table tbody tr:hover {
        background: var(--muted);
    }

    [data-theme='grotesk'] .kp-datatable {
        border: 2px solid var(--border);
        border-radius: 0;
    }

    [data-theme='grotesk'] .kp-datatable__bar {
