    [data-theme='dark'] .kp-tag {
        border: 1px solid var(--border-strong);
    }

    [data-theme='dark'] .kp-skeleton {
        background: var(--accent);
    }

    [data-theme='dark'] .kp-progress {
        background: var(--card);
        border: 1px solid var(--border-strong);
    }

    [data-theme='dark'] .kp-progress__value {
        background: var(--primary);
    }

    [data-theme='dark'] .kp-spinner {
        border-color: var(--border);
        border-top-color: var(--primary);
    }

    [data-theme='dark'] .kp-empty {
        border: 1px dashed var(--border-strong);
    }

    [data-theme='dark'] .kp-error {
        color: var(--destructive);
    }

    /* ── Text shapes ──────────────────────────────────────────────────── */

    [data-theme='dark'] .kp-id,
    [data-theme='dark'] .kp-url,
    [data-theme='dark'] .kp-numeric,
    [data-theme='dark'] .kp-timestamp,
    [data-theme='dark'] .kp-masked,
    [data-theme='dark'] .kp-copyable,
    [data-theme='dark'] .kp-truncate,
    [data-theme='dark'] .kp-cell-break,
    [data-theme='dark'] .kp-cell-truncate {
        font-family: var(--theme-font-mono);
    }

    [data-theme='dark'] .kp-timestamp,
    [data-theme='dark'] .kp-id {
        color: var(--muted-foreground);
    }

    [data-theme='dark'] .kp-copyable__button {
        border: 1px solid var(--border-strong);
    }

    /* ── Data ─────────────────────────────────────────────────────────── */

    [data-theme='dark'] .kp-table th {
        color: var(--muted-foreground);
        border-bottom: 1px solid var(--border-strong);
        font-weight: 600;
    }

    [data-theme='dark'] .kp-table td {
        border-bottom: 1px solid var(--border);
    }

    [data-theme='dark'] .kp-table tbody tr:hover {
        background: var(--card);
    }

    [data-theme='dark'] .kp-datatable {
        border: 1px solid var(--border-strong);
        background: var(--card);
    }

    [data-theme='dark'] .kp-datatable__bar {
        border-bottom: 1px solid var(--border);
    }

    [data-theme='dark'] .kp-datatable__sort[aria-sort] {
        color: var(--primary);
    }

    [data-theme='dark'] .kp-datatable__status,
    [data-theme='dark'] .kp-datatable__page {
        color: var(--muted-foreground);
    }

    [data-theme='dark'] .kp-diff {
        background: var(--card);
        border: 1px solid var(--border-strong);
    }

    [data-theme='dark'] .kp-diff__line {
        font-family: var(--theme-font-mono);
    }

    [data-theme='dark'] .kp-timeline {
        border-inline-start: 1px solid var(--border-strong);
    }

    [data-theme='dark'] .kp-timeline__marker {
        background: var(--primary);
    }

    [data-theme='dark'] .kp-timeline__when {
        color: var(--muted-foreground);
    }

    [data-theme='dark'] .kp-tree {
        font-family: var(--theme-font-mono);
    }

    [data-theme='dark'] .kp-reorder {
        border: 1px solid var(--border-strong);
        background: var(--card);
    }

    /* ── Navigation and steps ───────────────────────────────────────────── */

    [data-theme='dark'] .kp-tab {
        color: var(--muted-foreground);
    }

    [data-theme='dark'] .kp-tab[aria-selected='true'] {
        color: var(--foreground);
        font-weight: 600;
        border-bottom: 2px solid var(--primary);
    }

    [data-theme='dark'] .kp-tabs__list {
        border-bottom: 1px solid var(--border-strong);
    }

    [data-theme='dark'] .kp-pagination a[aria-current],
    [data-theme='dark'] .kp-pagination [aria-current] {
        background: var(--primary);
        color: var(--primary-foreground);
    }

    [data-theme='dark'] .kp-wizard {
        border: 1px solid var(--border-strong);
        background: var(--card);
    }

    /* ── Pickers and palettes ─────────────────────────────────────────── */

    [data-theme='dark'] .kp-datepicker__day[aria-selected='true'] {
        background: var(--primary);
        color: var(--primary-foreground);
    }

    [data-theme='dark'] .kp-colorpicker__swatch {
        border: 1px solid var(--border-strong);
    }

    [data-theme='dark'] .kp-shortcuts__row kbd {
        border: 1px solid var(--border-strong);
        background: var(--card);
        display: inline-block;
        padding: 0 0.4em;
    }

    [data-theme='dark'] .kp-shortcuts__group-label,
    [data-theme='dark'] .kp-palette__group-label {
        font-weight: 700;
        color: var(--muted-foreground);
    }

    [data-theme='dark'] .kp-theme-menu__status,
    [data-theme='dark'] .kp-palette__status,
    [data-theme='dark'] .kp-combobox__status {
        color: var(--muted-foreground);
    }

    /* ── The roots the rules above reach only by their parts ───────────── */

    [data-theme='dark'] .kp-field {
        gap: 0.3rem;
    }

    [data-theme='dark'] .kp-form {
        gap: 1rem;
    }

    [data-theme='dark'] .kp-breadcrumb,
    [data-theme='dark'] .kp-pagination {
        font-size: 0.9rem;
        color: var(--muted-foreground);
    }

    [data-theme='dark'] .kp-combobox,
    [data-theme='dark'] .kp-datepicker,
    [data-theme='dark'] .kp-colorpicker,
    [data-theme='dark'] .kp-shortcuts {
        border-radius: var(--radius);
    }

    [data-theme='dark'] .kp-grid {
        gap: 0.75rem;
    }

    [data-theme='dark'] .kp-split {
        gap: 0;
    }

    [data-theme='dark'] .kp-toasts {
        gap: 0.6rem;
    }

    [data-theme='dark'] .kp-health {
        color: var(--muted-foreground);
    }

    [data-theme='dark'] .kp-table {
        border-collapse: separate;
        border-spacing: 0;
    }

    /* ── The scrollbar joins the theme ──────────────────────────────────── */

    [data-theme='dark'] {
        scrollbar-color: var(--border-strong) var(--background);
    }

    /* ── The demo's own pieces [S46] ───────────────────────────────────── */

    [data-theme='dark'] .kp-laurels {
        gap: 0.5rem;
        font-size: 0.75rem;
        color: var(--muted-foreground);
    }

    [data-theme='dark'] .kp-laurels li {
        flex: 1 1 12rem;
        padding: 0.5rem 0.7rem;
        background: var(--card);
        border: 1px solid var(--border-strong);
        border-radius: var(--radius);
    }

    [data-theme='dark'] .kp-laurels b {
        display: block;
        font-weight: 700;
        font-size: 1rem;
        color: var(--foreground);
        margin-block-end: 0.15rem;
    }

    [data-theme='dark'] .kp-lede {
        max-width: 38rem;
        font-size: 1.08rem;
    }

    [data-theme='dark'] .kp-platforms {
        margin-block-start: 1.6rem;
        gap: 0.2rem 1.3rem;
        font-family: var(--theme-font-mono);
        font-size: 0.7rem;
        letter-spacing: 0.14em;
        text-transform: uppercase;
        color: var(--muted-foreground);
    }

    [data-theme='dark'] .kp-platforms span::before {
        content: '· ';
        color: var(--primary);
    }

    [data-theme='dark'] .kp-spec {
        background: var(--card);
        color: var(--foreground);
        border: 1px solid var(--border-strong);
        border-radius: calc(var(--radius) * 1.5);
        padding: 1.2rem 1.4rem;
        font-size: 0.86rem;
        line-height: 1.75;
    }

    [data-theme='dark'] .kp-spec dt {
        color: var(--muted-foreground);
        letter-spacing: 0.08em;
        text-transform: uppercase;
        font-size: 0.72rem;
    }

    [data-theme='dark'] .kp-spec__swatch {
        border: 1px solid var(--border);
    }

    [data-theme='dark'] .kp-spec__font {
        font-family: var(--theme-font-display);
    }

    /* ── Motion, guarded [DI7] ────────────────────────────────────────── */

    /* Every animation and transition of this register lives here, inside
       the no-preference guard, so a reader who asked for reduced motion
       never receives one: the rest states above are what they get. */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='dark'] [data-kp-reveal='headline'].is-words [data-word] {
            animation: kp-resolve 640ms var(--kp-settle) both;
            animation-delay: calc(var(--kp-i, 0) * var(--kp-word-stagger));
        }

        [data-theme='dark'] .kp-nav__menu {
            transition: opacity var(--fx-duration) var(--fx-ease);
        }

        /* The redact bar: a size change, not a colour (KT8: no
           mid-transition colour can be read); the ink turns visible in
           the same instant the bar clears, staggered per redaction. */
        [data-theme='dark'] .kp-card[data-kp-reveal='emphasis'] mark::after {
            transition: transform 380ms var(--fx-ease);
        }

        [data-theme='dark'] .kp-card[data-kp-reveal='emphasis'] mark:nth-of-type(2)::after {
            transition-delay: var(--kp-redact-stagger);
        }

        [data-theme='dark'] .kp-card[data-kp-reveal='emphasis'] mark:nth-of-type(3)::after {
            transition-delay: calc(2 * var(--kp-redact-stagger));
        }

        [data-theme='dark'] .kp-card[data-kp-reveal='emphasis'] mark {
            transition: color 0s linear 0s;
        }
    }

    /* ── Motion [DI5, DI7] ────────────────────────────────────────────── */

    /* Every keyframe here has its row in TIMINGS (js/effects.js). The
       word resolve is one monotonic change (blur and translate settle
       alongside the opacity move) [S49]. */
    @keyframes kp-resolve {
        0% {
            opacity: 0;
            filter: blur(6px);
            transform: translateY(0.15em);
        }

        100% {
            opacity: 1;
            filter: blur(0);
            transform: none;
        }
    }

    /* Scroll-bound, not time-based: the browser scrubs this by the
       heading's own position, not a clock, so it cannot free-run and
       cannot loop — see gates/check-motion.mjs's OUT_OF_SCOPE entry. */
    @keyframes kp-ignite {
        100% {
            color: var(--primary);
            text-decoration-color: var(--border-strong);
        }
    }

    @keyframes kp-sweep-in {
        0% {
            background-position: 100% 0;
        }

        100% {
            background-position: 0 0;
        }
    }
    /* The band [M1, M4]: Kenny picked this theme's own version over the
       shared one on 2026-09-08 — the row a step lighter than the page it sits on. */
    [data-theme='dark'] .kp-marquee {
        border-block: 1px solid color-mix(in srgb, var(--foreground) 18%, transparent);
        background: color-mix(in srgb, var(--card) 60%, var(--background));
        --kp-marquee: 50000ms;
    }

    /* The menu's caption [M3]: the same choice, for the line a consumer
       may put above a dropdown's items. */
    [data-theme='dark'] .kp-nav__menu[data-kp-menu-label]::before {
        color: var(--primary);
        border-block-end: 1px solid color-mix(in srgb, var(--foreground) 20%, transparent);
    }
}

@layer kp.register {
    /* @kp-soft/themes — css/academia-register.css
   The academia register, 5.0.0 [S48, LIFT_PLAN row 10]: dark academia —
   the library, after hours. Scoped to [data-theme='academia'] and inert
   elsewhere; opt-in, imported after themes.css. The approved concept demo
   ("The Reading Room", 2026-09-08) is the reference for every value here,
   and docs/RESEARCH_2026-09.md §14 is where each mechanism was measured:
   Chris Lemke's "Dark Editorial" ribbon underline and duotone-over-image
   wash (measured, cited in the demo's own header), Mosby's Files folder
   stack (measured, §2.8).

   What this file does, in order: the knobs; the type; the hooks of S45 —
   the headline and the section rule both drawing as one gold bar, slower
   than the shared 900ms baseline (the "one gesture" DI5 names in
   themes/academia/anatomy.md), the mark as a redaction that clears on a
   trigger, the double hairline as divider; the navbar with its ribbon
   underline; the buttons; the fields; the folder-stack dossier with its
   stamp; the confirmation dialog and the other panels; the footer; and
   one answer per component root (TH124). The reveals have their rest
   state here and their motion in js/effects.js; without the script every
   one of them stands drawn and readable (AR34) — the demo's own inline
   script assumed itself as the only reader, so its rest-state-hidden
   rule is reproduced here the way cyberpunk and terminal already solve
   the same tension: drawn by default, hidden only while the module is
   attached and the heading has not yet entered the viewport. The
   rendered result is identical to the demo whenever the module runs.

   Colour discipline (DI9): nothing here names a colour. Every paint is a
   token or a relative colour of one (`color-mix(in srgb, var(--x) …,
   var(--y))`, `hsl(from var(--x) …)`) — the demo's own `color-mix(…,
   black)` / `color-mix(…, white)` hover deltas are reproduced as mixes
   toward `--background` / `--foreground` instead, which is the same
   direction (darker toward the dark ground, lighter toward the pale
   ink) without a colour of the register's own.

   The only loops in this register: none. Every gesture here runs once —
   the headline's and the rule's draw, the redactions clearing on their
   trigger, the dialog opening — and check-motion.mjs rates every one of
   them well under the flash threshold (reports/di5.md). */

    [data-theme='academia'] {
        /* The configuration surface [AR43], the demo's values as defaults. */
        --kp-reveal-threshold: 0.6;
        --kp-reveal-stagger: 260ms;
        --kp-redact-stagger: 260ms;
        --kp-classified-delay: 1200ms;
        --kp-headline-draw: 1100ms;
        --kp-rule-draw: 900ms;
        --kp-redact: 220ms;
        --kp-dialog-in: 180ms;
        /* The reveals this theme performs [S45]: js/effects.js reads these
           and leaves a theme that declares none at rest. `draw` is new —
           the demo's headline is not a decipher, a typing or a word
           reveal, it is the same "grows a bar underneath, once in view"
           mechanism the rule hook already performs, generalised to h1
           because the demo drives both off one IntersectionObserver and
           one class. `redact` is a free label: js/effects.js's emphasis
           routine does not branch on the string, only the register's own
           CSS decides what "covered" and "cleared" look like. */
        --kp-reveal-headline: draw;
        --kp-reveal-emphasis: redact;
        --kp-reveal-rule: draw;
        /* The duotone wash [Lemke duotone-over-image, generalised to a
           texture — the demo's own note: "the mechanism our theme lacks
           […] here it is a texture wash with no photograph"], a local
           texture layer scoped to the two surfaces, additional to the
           theme's own base grain in css/_rules.css. Held at the demo's
           4%, under DI9's ceiling. */
        --kp-wash: linear-gradient(135deg, var(--accent) 0%, transparent 45%, var(--primary) 85%);
    }

    /* ── Type: a lecture hall's serif ─────────────────────────────────── */

    [data-theme='academia'] h1,
    [data-theme='academia'] h2,
    [data-theme='academia'] h3,
    [data-theme='academia'] h4 {
        font-weight: 600;
        line-height: 1.15;
    }

    [data-theme='academia'] [data-kp-surface] h1 {
        font-size: var(--kp-text-display);
        line-height: 1.08;
        margin-block: 0 0.4em;
    }

    /* Microlabels: a running head, small and quiet. */
    [data-theme='academia'] .microlabel {
        font-family: var(--theme-font-mono);
        font-size: 0.7rem;
        letter-spacing: 0.14em;
        text-transform: uppercase;
        color: var(--muted-foreground);
    }

    /* ── The hooks [S45]: the headline and rule draw, the mark, the divider ── */

    /* The one gesture [anatomy.md, DI5]: a gold rule drawing under a
       heading, slower than the shared 900ms baseline other registers use
       for the same gesture — a library is not in a hurry. Drawn by
       default (AR34: a page without the module reads whole); hidden only
       while the module is attached and the heading has not yet entered
       the viewport, exactly the cyberpunk/terminal shape. */
    [data-theme='academia'] h1[data-kp-reveal='headline'],
    [data-theme='academia'] h2[data-kp-reveal='rule'] {
        position: relative;
        display: inline-block;
        padding-block-end: 0.35em;
    }

    [data-theme='academia'] h1[data-kp-reveal='headline']::after,
    [data-theme='academia'] h2[data-kp-reveal='rule']::after {
        content: '';
        position: absolute;
        inset-inline-start: 0;
        inset-block-end: 0;
        block-size: 2px;
        inline-size: 100%;
        background: var(--primary);
        transform-origin: left center;
    }

    /* The rule hook's own bail path (js/effects.js `rule()`) always adds
       `is-in`, reduced motion included, so `:not(.is-in)` alone is enough
       for h2. The headline dispatch it was generalised from bails through
       the shared top of `headline()` first when the module is quiet,
       reduced or has already run — the same path decipher, type and
       every other headline routine share — and that path adds
       `is-deciphered`, not `is-in`. Excluding both keeps the bar drawn
       whichever of the two the module reached. */
    [data-theme='academia'][data-kp-effects] h1[data-kp-reveal='headline']:not(.is-in):not(.is-deciphered)::after,
    [data-theme='academia'][data-kp-effects] h2[data-kp-reveal='rule']:not(.is-in)::after {
        transform: scaleX(0);
    }

    /* The mark, outside the dossier (the lede): a gold underline, always
       legible — the demo never covers it, so no reveal state changes how
       it looks. */
    [data-theme='academia'] mark {
        background: none;
        color: var(--primary);
        text-decoration: underline;
        text-decoration-color: color-mix(in srgb, var(--primary) 60%, transparent);
        text-underline-offset: 0.2em;
        padding: 0;
    }

    /* The divider: a double hairline, the ruled lines of a ledger's page —
       the demo's own idiom, whatever its section header comment called
       it. The second divider doubles the emphasis of the first. */
    [data-theme='academia'] [data-kp-divider] {
        position: relative;
        block-size: 1.4rem;
    }

    [data-theme='academia'] [data-kp-divider]::before,
    [data-theme='academia'] [data-kp-divider]::after {
        content: '';
        position: absolute;
        inset-inline: var(--kp-space-xl);
        block-size: 1px;
    }

    [data-theme='academia'] [data-kp-divider]::before {
        inset-block-start: 0.35rem;
        background: color-mix(in srgb, var(--primary) 55%, transparent);
    }

    [data-theme='academia'] [data-kp-divider]::after {
        inset-block-start: 0.75rem;
        background: var(--border-strong);
    }

    [data-theme='academia'] [data-kp-divider='alt']::before {
        background: var(--border-strong);
    }

    [data-theme='academia'] [data-kp-divider='alt']::after {
        background: color-mix(in srgb, var(--primary) 40%, transparent);
    }

    /* ── The hero and app surfaces: the duotone wash ──────────────────── */

    [data-theme='academia'] [data-kp-surface='hero'],
    [data-theme='academia'] [data-kp-surface='app'] {
        position: relative;
        isolation: isolate;
    }

    [data-theme='academia'] [data-kp-surface='hero']::before,
    [data-theme='academia'] [data-kp-surface='app']::before {
        content: '';
        position: absolute;
        inset: 0;
        z-index: -1;
        pointer-events: none;
        mix-blend-mode: overlay;
        --fx-texture: var(--kp-wash);
        --fx-texture-opacity: 0.04;
        background-image: var(--fx-texture);
        opacity: var(--fx-texture-opacity);
    }

    [data-theme='academia'] [data-kp-surface='app']::before {
        --fx-texture: linear-gradient(315deg, var(--accent) 0%, transparent 50%, var(--primary) 90%);
    }

    /* The side note: a volume/section mark in the margin, set vertically. */
    [data-theme='academia'] .kp-side-note {
        position: absolute;
        inset-inline-start: var(--kp-space-sm);
        inset-block-start: 6rem;
        writing-mode: vertical-rl;
        transform: rotate(180deg);
        font-family: var(--theme-font-mono);
        font-size: 0.68rem;
        letter-spacing: 0.18em;
        color: var(--muted-foreground);
    }

    /* The laurels: three measures the theme is held to. */
    [data-theme='academia'] .kp-laurels {
        gap: var(--kp-space-lg);
        font-size: 0.8rem;
        color: var(--muted-foreground);
    }

    [data-theme='academia'] .kp-laurels li {
        border-inline-start: 2px solid var(--border-strong);
        padding-inline-start: var(--kp-space-sm);
    }

    [data-theme='academia'] .kp-laurels b {
        font-weight: 600;
        display: block;
        font-size: 1rem;
        color: var(--foreground);
    }

    [data-theme='academia'] .kp-lede {
        max-inline-size: 42rem;
        font-size: 1.1rem;
    }

    [data-theme='academia'] .kp-platforms {
        font-family: var(--theme-font-mono);
        font-size: 0.72rem;
        letter-spacing: 0.08em;
        color: var(--muted-foreground);
    }

    /* The spec sheet: a card, set in the display face for its swatches' words. */
    [data-theme='academia'] .kp-spec {
        border: 1px solid var(--border-strong);
        background: var(--card);
    }

    [data-theme='academia'] .kp-spec dt {
        font-family: var(--theme-font-mono);
        font-size: 0.68rem;
        letter-spacing: 0.1em;
        text-transform: uppercase;
        color: var(--muted-foreground);
    }

    [data-theme='academia'] .kp-spec__swatch {
        border: 1px solid var(--border-strong);
    }

    [data-theme='academia'] .kp-spec__font {
        font-style: normal;
    }

    /* ── The navbar: the ribbon underline ──────────────────────────────── */

    [data-theme='academia'] .kp-nav-wrap {
        border-block-end: 1px solid var(--border);
        background: var(--background);
    }

    [data-theme='academia'] .kp-nav {
        padding-block: var(--kp-space-lg) var(--kp-space-sm);
    }

    [data-theme='academia'] .kp-nav__brand {
        font-family: var(--theme-font-display);
        font-weight: 600;
        font-size: 1.25rem;
        letter-spacing: 0.02em;
    }

    [data-theme='academia'] .kp-nav__brand-tag {
        color: var(--muted-foreground);
        font-family: var(--theme-font-mono);
        font-size: 0.72rem;
        letter-spacing: 0.14em;
    }

    [data-theme='academia'] .kp-nav__link {
        position: relative;
        color: var(--foreground);
        font-size: 0.72rem;
        letter-spacing: 0.12em;
        text-transform: uppercase;
        padding-block: var(--kp-space-xs);
    }

    /* The ribbon underline [Lemke, §14, measured]: width 0→40px on hover
       and focus, CSS-only. */
    [data-theme='academia'] .kp-nav__link::after {
        content: '';
        position: absolute;
        inset-inline-start: 0;
        inset-block-end: -2px;
        inline-size: 0;
        block-size: 1px;
        background: var(--primary);
    }

    [data-theme='academia'] .kp-nav__link:hover::after,
    [data-theme='academia'] .kp-nav__link:focus-visible::after,
    [data-theme='academia'] .kp-nav__links > li:focus-within > .kp-nav__link::after {
        inline-size: 40px;
    }

    [data-theme='academia'] .kp-nav__link--cta {
        color: var(--primary-foreground);
        background: var(--primary);
        padding: var(--kp-space-sm) var(--kp-space-lg);
    }

    [data-theme='academia'] .kp-nav__link--cta::after {
        display: none;
    }

    [data-theme='academia'] .kp-nav__link--lang {
        margin-inline-start: 0.3rem;
        border-inline-start: 1px solid var(--border);
        padding-inline-start: 0.7rem;
        text-transform: uppercase;
    }

    /* The dropdown [KT14]: a popover panel, opened and read before this
       register was called done. */
    [data-theme='academia'] .kp-nav__menu {
        background: var(--popover);
        border: 1px solid var(--border-strong);
        border-radius: 0;
        box-shadow: none;
    }

    [data-theme='academia'] .kp-nav__menu a {
        color: var(--popover-foreground);
        font-size: 0.9rem;
    }

    [data-theme='academia'] .kp-nav__menu a:hover,
    [data-theme='academia'] .kp-nav__menu a:focus-visible {
        background: color-mix(in srgb, var(--primary) 16%, transparent);
        color: var(--primary);
    }

    /* ── Buttons ───────────────────────────────────────────────────────── */

    [data-theme='academia'] .kp-button {
        font-family: var(--theme-font-body);
        border: 1px solid var(--border-strong);
        border-radius: 0;
        background: transparent;
        color: var(--foreground);
    }

    /* The demo's own size, on the medium button only [TH111]: sm and lg
       keep the base component's own scale (font size and padding both
       rising with size) rather than being flattened to the demo's one
       measurement, the same shape terminal and brutalism settled on. */
    [data-theme='academia'] .kp-button:not(.kp-button--sm):not(.kp-button--lg) {
        font-size: 0.92rem;
        padding-block: 0.65em;
        padding-inline: 1.3em;
    }

    [data-theme='academia'] .kp-button--primary {
        background: var(--primary);
        border-color: var(--primary);
        color: var(--primary-foreground);
    }

    [data-theme='academia'] .kp-button--primary:hover,
    [data-theme='academia'] .kp-button--primary:focus-visible {
        background: color-mix(in srgb, var(--primary) 88%, var(--background));
        border-color: color-mix(in srgb, var(--primary) 88%, var(--background));
    }

    [data-theme='academia'] .kp-button--secondary {
        background: var(--secondary);
        border-color: var(--secondary);
        color: var(--secondary-foreground);
    }

    [data-theme='academia'] .kp-button--secondary:hover,
    [data-theme='academia'] .kp-button--secondary:focus-visible {
        background: color-mix(in srgb, var(--secondary) 85%, var(--foreground));
        border-color: color-mix(in srgb, var(--secondary) 85%, var(--foreground));
    }

    [data-theme='academia'] .kp-button--ghost {
        background: transparent;
        border-color: transparent;
        color: var(--primary);
    }

    [data-theme='academia'] .kp-button--ghost:hover,
    [data-theme='academia'] .kp-button--ghost:focus-visible {
        background: color-mix(in srgb, var(--primary) 12%, transparent);
    }

    [data-theme='academia'] .kp-button--destructive {
        background: transparent;
        border-color: var(--destructive);
        color: var(--destructive);
    }

    [data-theme='academia'] .kp-button--destructive:hover,
    [data-theme='academia'] .kp-button--destructive:focus-visible {
        background: var(--destructive);
        color: var(--destructive-foreground);
    }

    [data-theme='academia'] .kp-button--destructive.kp-button--solid,
    [data-theme='academia'] .kp-button--destructive[data-kp-confirm-accept] {
        background: var(--destructive);
        color: var(--destructive-foreground);
    }

    [data-theme='academia'] .kp-button:disabled {
        color: var(--muted-foreground);
        border-color: var(--border);
        background: transparent;
    }

    [data-theme='academia'] .kp-icon-button {
        border: 1px solid var(--border-strong);
        border-radius: 0;
        background: transparent;
        color: var(--foreground);
    }

    [data-theme='academia'] .kp-icon-button:hover {
        color: var(--primary);
        border-color: var(--primary);
    }

    /* ── Fields ────────────────────────────────────────────────────────── */

    [data-theme='academia'] .kp-field__label {
        font-size: 0.82rem;
        font-weight: 600;
        color: var(--card-foreground);
    }

    [data-theme='academia'] .kp-field__required {
        font-family: var(--theme-font-mono);
        font-size: 0.62rem;
        letter-spacing: 0.08em;
        text-transform: uppercase;
        color: var(--muted-foreground);
        font-weight: 400;
    }

    [data-theme='academia'] .kp-field__input,
    [data-theme='academia'] .kp-datatable__search,
    [data-theme='academia'] .kp-combobox__input,
    [data-theme='academia'] .kp-palette__input {
        font-family: var(--theme-font-body);
        background: var(--background);
        color: var(--foreground);
        border: 1px solid var(--input);
        border-radius: 0;
    }

    [data-theme='academia'] .kp-field__input--multiline {
        font-family: var(--theme-font-body);
    }

    [data-theme='academia'] .kp-field__help {
        font-size: 0.75rem;
        color: var(--muted-foreground);
    }

    [data-theme='academia'] .kp-field--invalid .kp-field__input {
        border-color: var(--destructive);
    }

    [data-theme='academia'] .kp-field__check {
        accent-color: var(--primary);
    }

    [data-theme='academia'] .kp-fieldset {
        border: 1px solid var(--border-strong);
        border-radius: 0;
    }

    [data-theme='academia'] .kp-form {
        gap: var(--kp-space-lg);
    }

    [data-theme='academia'] .kp-form__summary {
        background: var(--card);
        border: 1px solid var(--border-strong);
        border-radius: 0;
    }

    /* ── Cards and the dossier: a folder stack, a stamp, redactions ───── */

    [data-theme='academia'] .kp-card {
        background: var(--popover);
        border: 1px solid var(--border-strong);
        border-radius: 0;
        box-shadow: none;
    }

    [data-theme='academia'] .kp-card__title {
        font-size: 1.3rem;
    }

    /* The folder stack [Mosby's Files, §14, measured, adopted]: a rotated
       plate behind the card, static — no animation, matching the demo.
       The demo's own markup wraps the card in a separate
       `.kp-folder-stack` element carrying two plates on its own
       `::before`/`::after`; the shared concept-page template that every
       lifted theme's generated page renders puts `data-kp-reveal`
       (this hook) and `data-kp-label` (the stamp, below) on the SAME
       `Card` element with no such wrapper, and a stamp already needs
       `::before` (the demo's own convention, shared with terminal, retro,
       phantom and brutalism). One pseudo-element is spoken for, so the
       stack uses only `::after` — one plate rather than the demo's two,
       a finding recorded in the anatomy and the lift report. */
    [data-theme='academia'] .kp-card[data-kp-reveal='emphasis'] {
        position: relative;
    }

    [data-theme='academia'] .kp-card[data-kp-reveal='emphasis']::after {
        content: '';
        position: absolute;
        inset: 0;
        z-index: -1;
        border: 1px solid var(--border);
        background: var(--card);
        transform: rotate(-2.4deg) translate(-4px, 6px);
    }

    /* The stamp: static, exactly as the demo shows it — its own script
       never swaps the word when the file opens, so this register does
       not either (a finding in the lift report). */
    [data-theme='academia'] .kp-card[data-kp-label]::before {
        content: attr(data-kp-label);
        position: absolute;
        inset-block-start: -0.6em;
        inset-inline-start: var(--kp-space-lg);
        background: var(--accent);
        color: var(--accent-foreground);
        font-family: var(--theme-font-mono);
        font-size: 0.62rem;
        letter-spacing: 0.1em;
        text-transform: uppercase;
        padding: 0.2em 0.6em;
    }

    /* The redactions: at rest — no module, AR34 — the words simply read
       (a page without the script is whole). Only once the module has
       armed the page and before the trigger opens the file does the
       mark's own background and text colour hide it (not a
       pseudo-element positioned by an inset box), so a redaction
       wrapping across lines gets one cover per line fragment via
       box-decoration-break: clone instead of one bounding-box rectangle
       smeared across the gap between lines — the demo's own reasoning. */
    [data-theme='academia'] .kp-card[data-kp-reveal='emphasis'] mark {
        background: transparent;
        color: var(--popover-foreground);
        padding: 0.02em 0.2em;
        border-radius: 1px;
        box-decoration-break: clone;
        -webkit-box-decoration-break: clone;
    }

    [data-theme='academia'][data-kp-effects] .kp-card[data-kp-reveal='emphasis'] mark:not(.is-cleared) {
        background: var(--background);
        color: var(--background);
    }

    /* ── Panels: dialog, confirm, popover, menu, toast, tooltip ───────── */

    [data-theme='academia'] .kp-dialog,
    [data-theme='academia'] .kp-confirm,
    [data-theme='academia'] .kp-popover,
    [data-theme='academia'] .kp-menu,
    [data-theme='academia'] .kp-toast,
    [data-theme='academia'] .kp-tooltip,
    [data-theme='academia'] .kp-datepicker__panel,
    [data-theme='academia'] .kp-combobox__list,
    [data-theme='academia'] .kp-palette,
    [data-theme='academia'] .kp-theme-menu {
        background: var(--popover);
        color: var(--popover-foreground);
        border: 1px solid var(--border-strong);
        border-radius: 0;
        box-shadow: none;
    }

    [data-theme='academia'] .kp-dialog::backdrop {
        background: color-mix(in srgb, var(--background) 70%, transparent);
    }

    [data-theme='academia'] .kp-dialog__title {
        font-size: 1.3rem;
    }

    [data-theme='academia'] .kp-dialog__description {
        color: var(--muted-foreground);
        font-size: 0.9rem;
    }

    [data-theme='academia'] .kp-menu__item:hover {
        background: color-mix(in srgb, var(--primary) 16%, transparent);
        color: var(--primary);
    }

    /* ── Footer ────────────────────────────────────────────────────────── */

    [data-theme='academia'] .kp-footer {
        border-block-start: 1px solid var(--border);
    }

    [data-theme='academia'] .kp-footer h4 {
        font-size: 1rem;
    }

    [data-theme='academia'] .kp-footer a {
        color: var(--muted-foreground);
        font-size: 0.9rem;
    }

    [data-theme='academia'] .kp-footer a:hover {
        color: var(--primary);
    }

    [data-theme='academia'] .kp-alert {
        background: var(--card);
        border: 1px solid var(--border-strong);
        border-radius: 0;
    }

    [data-theme='academia'] .kp-toasts {
        gap: var(--kp-space-sm);
    }

    /* ── Badges, tags, status ─────────────────────────────────────────── */

    [data-theme='academia'] .kp-badge,
    [data-theme='academia'] .kp-tag {
        border-radius: 0;
        border: 1px solid var(--border-strong);
    }

    [data-theme='academia'] .kp-health {
        letter-spacing: 0.04em;
    }

    [data-theme='academia'] .kp-health__dot {
        border-radius: 50%;
    }

    [data-theme='academia'] .kp-skeleton {
        background: var(--muted);
        border-radius: 0;
    }

    [data-theme='academia'] .kp-progress {
        background: var(--muted);
        border-radius: 0;
    }

    [data-theme='academia'] .kp-progress__value {
        background: var(--primary);
    }

    [data-theme='academia'] .kp-spinner {
        border-color: var(--border-strong);
        border-top-color: var(--primary);
    }

    [data-theme='academia'] .kp-empty {
        border: 1px dashed var(--border-strong);
        border-radius: 0;
    }

    [data-theme='academia'] .kp-error {
        color: var(--destructive);
    }

    /* ── Text shapes ──────────────────────────────────────────────────── */

    [data-theme='academia'] .kp-id,
    [data-theme='academia'] .kp-url,
    [data-theme='academia'] .kp-numeric,
    [data-theme='academia'] .kp-timestamp,
    [data-theme='academia'] .kp-masked,
    [data-theme='academia'] .kp-copyable,
    [data-theme='academia'] .kp-truncate,
    [data-theme='academia'] .kp-cell-break,
    [data-theme='academia'] .kp-cell-truncate {
        font-family: var(--theme-font-mono);
        letter-spacing: 0.01em;
    }

    [data-theme='academia'] .kp-timestamp,
    [data-theme='academia'] .kp-id {
        color: var(--muted-foreground);
    }

    [data-theme='academia'] .kp-copyable__button {
        border: 1px solid var(--border-strong);
        border-radius: 0;
        background: transparent;
    }

    /* ── Data ─────────────────────────────────────────────────────────── */

    [data-theme='academia'] .kp-table {
        border-collapse: separate;
        border-spacing: 0;
    }

    [data-theme='academia'] .kp-table th {
        font-family: var(--theme-font-mono);
        letter-spacing: 0.06em;
        text-transform: uppercase;
        font-weight: 400;
        color: var(--muted-foreground);
        border-bottom: 1px solid var(--border-strong);
    }

    [data-theme='academia'] .kp-table td {
        border-bottom: 1px solid var(--border);
    }

    [data-theme='academia'] .kp-datatable {
        border: 1px solid var(--border-strong);
        border-radius: 0;
    }

    [data-theme='academia'] .kp-datatable__bar {
        border-bottom: 1px solid var(--border);
    }

    [data-theme='academia'] .kp-datatable__sort[aria-sort] {
        color: var(--primary);
    }

    [data-theme='academia'] .kp-datatable__status,
    [data-theme='academia'] .kp-datatable__page {
        color: var(--muted-foreground);
    }

    [data-theme='academia'] .kp-diff {
        background: var(--card);
        border: 1px solid var(--border-strong);
        border-radius: 0;
    }

    [data-theme='academia'] .kp-timeline {
        border-inline-start: 1px solid var(--border-strong);
    }

    [data-theme='academia'] .kp-timeline__marker {
        background: var(--primary);
        border-radius: 50%;
    }

    [data-theme='academia'] .kp-timeline__when {
        color: var(--muted-foreground);
    }

    [data-theme='academia'] .kp-tree {
        letter-spacing: 0.01em;
    }

    [data-theme='academia'] .kp-reorder {
        border: 1px solid var(--border-strong);
        border-radius: 0;
    }

    /* ── Navigation and steps ─────────────────────────────────────────── */

    [data-theme='academia'] .kp-tab {
        border-radius: 0;
        color: var(--muted-foreground);
    }

    [data-theme='academia'] .kp-tab[aria-selected='true'] {
        color: var(--primary);
        border-color: var(--primary);
    }

    [data-theme='academia'] .kp-tabs__list {
        border-bottom: 1px solid var(--border-strong);
    }

    [data-theme='academia'] .kp-breadcrumb,
    [data-theme='academia'] .kp-pagination {
        font-size: 0.85rem;
    }

    [data-theme='academia'] .kp-pagination a[aria-current],
    [data-theme='academia'] .kp-pagination [aria-current] {
        background: var(--primary);
        color: var(--primary-foreground);
        border-radius: 0;
    }

    [data-theme='academia'] .kp-wizard {
        border: 1px solid var(--border-strong);
        border-radius: 0;
        background: var(--card);
    }

    [data-theme='academia'] .kp-wizard__steps {
        letter-spacing: 0.04em;
    }

    /* ── Pickers and palettes ─────────────────────────────────────────── */

    [data-theme='academia'] .kp-datepicker__day[aria-selected='true'] {
        background: var(--primary);
        color: var(--primary-foreground);
        border-radius: 50%;
    }

    [data-theme='academia'] .kp-datepicker__weekday,
    [data-theme='academia'] .kp-datepicker__title {
        letter-spacing: 0.06em;
        text-transform: uppercase;
    }

    [data-theme='academia'] .kp-colorpicker__swatch {
        border: 1px solid var(--border-strong);
    }

    [data-theme='academia'] .kp-colorpicker__value {
        font-family: var(--theme-font-mono);
    }

    [data-theme='academia'] .kp-shortcuts__row kbd {
        border: 1px solid var(--border-strong);
        border-radius: 0;
        background: var(--card);
    }

    [data-theme='academia'] .kp-shortcuts__group-label,
    [data-theme='academia'] .kp-palette__group-label {
        letter-spacing: 0.1em;
        text-transform: uppercase;
        color: var(--muted-foreground);
    }

    [data-theme='academia'] .kp-theme-menu__status,
    [data-theme='academia'] .kp-palette__status,
    [data-theme='academia'] .kp-combobox__status {
        color: var(--muted-foreground);
    }

    /* ── The roots the rules above reach only by their parts ──────────── */

    [data-theme='academia'] .kp-field {
        gap: 0.3rem;
    }

    [data-theme='academia'] .kp-combobox,
    [data-theme='academia'] .kp-datepicker,
    [data-theme='academia'] .kp-colorpicker,
    [data-theme='academia'] .kp-shortcuts,
    [data-theme='academia'] .kp-tabs {
        border-radius: 0;
    }

    [data-theme='academia'] .kp-split {
        gap: 1px;
    }

    [data-theme='academia'] .kp-split__separator {
        background: var(--border-strong);
    }

    [data-theme='academia'] .kp-grid {
        gap: var(--kp-space-md);
    }

    [data-theme='academia'] .kp-grid__tile {
        background: var(--card);
        border: 1px solid var(--border-strong);
        border-radius: 0;
    }

    /* ── The scrollbar joins the theme ────────────────────────────────── */

    [data-theme='academia'] {
        scrollbar-color: var(--border-strong) var(--background);
    }

    /* ── Motion, guarded [DI7] ────────────────────────────────────────── */

    /* Every animation and transition of this register lives here, inside
       the no-preference guard, so a reader who asked for reduced motion
       never receives one: the rest states above are what they get. The
       durations are literal because check-motion.mjs computes DI5's rate
       from them; the matching --kp-* knobs are what js/effects.js reads. */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='academia'] h1[data-kp-reveal='headline']::after {
            transition: transform var(--kp-headline-draw) var(--fx-ease);
        }

        [data-theme='academia'] h2[data-kp-reveal='rule']::after {
            transition: transform var(--kp-rule-draw) var(--fx-ease);
        }

        [data-theme='academia'] .kp-card[data-kp-reveal='emphasis'] mark {
            transition:
                background-color var(--kp-redact) var(--fx-ease),
                color var(--kp-redact) var(--fx-ease);
        }

        [data-theme='academia'] .kp-card[data-kp-reveal='emphasis'] mark:nth-of-type(2) {
            transition-delay: var(--kp-redact-stagger);
        }

        [data-theme='academia'] .kp-card[data-kp-reveal='emphasis'] mark:nth-of-type(3) {
            transition-delay: calc(2 * var(--kp-redact-stagger));
        }

        [data-theme='academia'] .kp-dialog[open] {
            animation: kp-dialog-in 180ms var(--fx-ease);
        }
    }

    @keyframes kp-dialog-in {
        0% {
            opacity: 0;
            transform: translateY(6px) scale(0.98);
        }

        100% {
            opacity: 1;
            transform: translateY(0) scale(1);
        }
    }
    /* The band [M1, M4]: Kenny picked this theme's own version over the
       shared one on 2026-09-08 — small caps over a thick ribbon, the gesture this theme already rules its headings with. */
    [data-theme='academia'] .kp-marquee {
        border-block-start: 1px solid var(--border-strong);
        border-block-end: 4px solid var(--primary);
        font-family: var(--theme-font-display);
        font-variant-caps: all-small-caps;
        --kp-marquee: 50000ms;
    }

    /* The menu's caption [M3]: the same choice, for the line a consumer
       may put above a dropdown's items. */
    [data-theme='academia'] .kp-nav__menu[data-kp-menu-label]::before {
        font-family: var(--theme-font-display);
        font-variant-caps: all-small-caps;
        letter-spacing: 0.06em;
        color: var(--primary);
    }
}

@layer kp.register {
    /* @kp-soft/themes — css/formal-register.css
   The formal register, 5.0.0 [S48, LIFT_PLAN row 16]: paper and ink.
   Scoped to [data-theme='formal'] and inert elsewhere; opt-in, imported
   after themes.css. The approved concept demo ("Fair Copy", 2026-09-08,
   scratchpad/formal-demo.html) is the reference for every value here.

   What this file does, in order: the knobs; the type; the hooks of S45 —
   the headline that fades and rises once (a demo's per-word underline
   recolour could not be carried: examples.mjs's conceptBody() renders the
   headline as one string with no sub-phrase mark, and giving it one would
   break gates/gates.test.mjs's exact-headline-string assertion for every
   theme, not only this one — a finding, not a silent substitution; see
   the anatomy's closing section), the lede's two marks as an ink wash,
   the section rule that draws itself in, the divider as a docket cut;
   the navbar as a masthead; the buttons, the mirror's static letterpress
   offset; the fields as ruled boxes; the dossier as a stamped file with
   redactions that clear left to right; and one answer per component
   root (56 of 64, TH124).

   Colour discipline (DI9): nothing here names a colour. Navy is the one
   hue that acts (anatomy.md: "one colour acts"); bronze/gold are the
   second voice, never a control. No ornament, no glow, no rounded
   flourish beyond the token radius — anatomy.md's own rule, carried
   into round six.

   The only motion is one-shot: the headline's fade and rise, the
   section rule's draw-in, the lede's two marks washing in, the
   dossier's redactions clearing. Nothing loops, nothing opposes its own
   direction fast enough to approach the flash threshold (DI5) — rated
   in the anatomy's closing section, not here, because none of it uses
   `@keyframes` (every effect below is a plain CSS transition, guarded
   under `@media (prefers-reduced-motion: no-preference)`, so DI5's
   report has nothing to add to TIMINGS: a transition has no keyframe
   for the table to describe). */

    [data-theme='formal'] {
        /* The configuration surface [AR43], the demo's own values as
           defaults: 1.05s before the lede's first mark washes in, 90ms
           between the two, a 0.4 viewport threshold for the section rule. */
        --kp-reveal-threshold: 0.4;
        --kp-classified-delay: 1050ms;
        --kp-reveal-stagger: 90ms;
        /* The reveals this theme performs [S45]: js/effects.js reads these
           and leaves a theme that declares none at rest. No arrival — the
           demo boots with nothing, and anatomy.md already answers DI5 "no
           animation" for the shipped theme; these three one-shot reveals
           are the round six addition on top of that baseline. */
        --kp-reveal-headline: arrive;
        --kp-reveal-emphasis: wash;
        --kp-reveal-rule: draw;
    }

    /* ── Type: the display face on headings, the microlabel a masthead line ── */

    [data-theme='formal'] h1,
    [data-theme='formal'] h2,
    [data-theme='formal'] h3 {
        font-family: var(--theme-font-display);
        font-optical-sizing: auto;
        font-weight: 560;
        color: var(--foreground);
    }

    [data-theme='formal'] [data-kp-surface] h1 {
        font-size: var(--kp-text-display);
        font-variation-settings: 'opsz' 144;
        letter-spacing: -0.03em;
        line-height: 1.08;
        margin-block: 0 1.25rem;
    }

    [data-theme='formal'] [data-kp-surface='app'] h2 {
        font-variation-settings: 'opsz' 90;
        letter-spacing: -0.02em;
        font-size: 1.5rem;
    }

    [data-theme='formal'] .microlabel {
        display: inline-block;
        font-family: var(--theme-font-body);
        font-size: 0.75rem;
        font-weight: 600;
        letter-spacing: 0.16em;
        text-transform: uppercase;
        color: var(--primary);
        margin-block-end: 0.75rem;
    }

    /* ── The headline hook [TH119, S45]: whole and untouched, the way an
       editorial page commits to a line rather than glitching into it. It
       fades and rises once; the underline the demo drew under one word
       is a finding in the anatomy, not built here (see the file header). ── */

    [data-theme='formal'][data-kp-effects] [data-kp-reveal='headline']:not(.is-deciphered) {
        opacity: 0;
        transform: translateY(6px);
    }

    [data-theme='formal'] [data-kp-reveal='headline'] {
        opacity: 1;
        transform: none;
    }

    /* ── The mark hook [TH120]: an ink wash under the lede's two phrases,
       left to right, the way a highlighter leaves a stroke. ── */

    [data-theme='formal'] mark {
        background: linear-gradient(var(--accent), var(--accent)) left / 100% 100% no-repeat;
        color: var(--foreground);
        padding: 0.02em 0.15em;
        border-radius: 2px;
    }

    [data-theme='formal'][data-kp-effects] mark:not(.is-cleared) {
        background-size: 0% 100%;
    }

    /* The dossier's own marks are covered in ink, not washed in bronze —
       see the card rules below, which take precedence by order. */

    /* ── The rule hook [TH122]: a line that draws itself under a heading
       when it scrolls into view, the way a printed rule is set once and
       stays. ── */

    [data-theme='formal'] [data-kp-reveal='rule'] {
        position: relative;
        padding-block-end: 0.4rem;
    }

    [data-theme='formal'] [data-kp-reveal='rule']::after {
        content: '';
        position: absolute;
        inset-inline-start: 0;
        inset-block-end: 0;
        block-size: 2px;
        inline-size: 100%;
        background: var(--primary);
        transform: scaleX(1);
        transform-origin: left center;
    }

    [data-theme='formal'][data-kp-effects] [data-kp-reveal='rule']:not(.is-in)::after {
        transform: scaleX(0);
    }

    /* ── The divider hook [TH121]: a docket cut, not a tear — a hairline
       and a short navy tick, the way a printed ledger marks a section
       closed. The alt divider (before the footer) is a dashed rule,
       quieter still. Static; anatomy.md licenses no ornament. ── */

    [data-theme='formal'] [data-kp-divider] {
        position: relative;
        block-size: auto;
        padding-block-start: 1px;
    }

    [data-theme='formal'] [data-kp-divider]::before {
        content: '';
        display: block;
        block-size: 1px;
        background: var(--border-strong);
    }

    [data-theme='formal'] [data-kp-divider]:not([data-kp-divider='alt'])::after {
        content: '';
        display: block;
        block-size: 4px;
        margin-block-start: 3px;
        inline-size: 3rem;
        background: var(--primary);
    }

    [data-theme='formal'] [data-kp-divider='alt']::before {
        border-block-start: 1px dashed var(--border-strong);
        background: none;
    }

    /* ── The navbar: a masthead line, not a bar ───────────────────────── */

    [data-theme='formal'] .kp-nav-wrap {
        background: var(--card);
        border-block-end: 1px solid var(--border);
    }

    [data-theme='formal'] .kp-nav {
        padding-block: 1rem;
    }

    [data-theme='formal'] .kp-nav__brand {
        font-family: var(--theme-font-display);
        font-optical-sizing: auto;
        font-variation-settings: 'opsz' 40;
        font-weight: 600;
        font-size: 1.25rem;
        letter-spacing: -0.01em;
        color: var(--foreground);
    }

    /* The file code beside the wordmark [S49, A3] is a demo line here, not
       a code: the masthead's own strapline, stacked below the name. */
    [data-theme='formal'] .kp-nav__brand-tag {
        display: block;
        font-family: var(--theme-font-body);
        font-size: 0.6875rem;
        font-weight: 500;
        letter-spacing: 0.14em;
        text-transform: uppercase;
        color: var(--muted-foreground);
    }

    [data-theme='formal'] .kp-nav__link {
        font-family: var(--theme-font-body);
        font-size: 0.9375rem;
        color: var(--foreground);
        border-radius: calc(var(--radius) / 2);
    }

    [data-theme='formal'] .kp-nav__link--lang {
        color: var(--muted-foreground);
        text-decoration: none;
        text-underline-offset: 0.2em;
    }

    [data-theme='formal'] .kp-nav__link--lang:hover {
        color: var(--primary);
        text-decoration: underline;
    }

    [data-theme='formal'] .kp-nav__link--cta {
        background: var(--primary);
        color: var(--primary-foreground);
        font-weight: 600;
        border-radius: var(--radius);
    }

    [data-theme='formal'] .kp-nav__link--cta:hover {
        background: var(--primary-hover);
    }

    /* The dropdown [KT14]: a card of the same paper as the rest of the
       theme, a hairline boundary, nothing floats further than the demo's
       own 8px/24px shadow. */
    [data-theme='formal'] .kp-nav__menu {
        background: var(--card);
        border: 1px solid var(--border);
        border-radius: var(--radius);
        box-shadow: 0 8px 24px -12px hsl(from var(--foreground) h s l / 0.28);
    }

    [data-theme='formal'] .kp-nav__menu a {
        color: var(--foreground);
        border-radius: calc(var(--radius) - 2px);
    }

    [data-theme='formal'] .kp-nav__menu a:hover,
    [data-theme='formal'] .kp-nav__menu a:focus-visible {
        background: var(--muted);
    }

    /* ── The hero ──────────────────────────────────────────────────────── */

    [data-theme='formal'] [data-kp-surface='hero'] {
        background: var(--card);
    }

    /* ── Buttons: no radius surprise, one static letterpress impression
       on the mirror modifier — an offset shadow, never an animation, so
       it costs nothing against DI5. ── */

    [data-theme='formal'] .kp-button {
        font-family: var(--theme-font-body);
        font-weight: 600;
        border-radius: var(--radius);
    }

    [data-theme='formal'] .kp-button--secondary {
        background: var(--muted);
        border-color: var(--border);
    }

    [data-theme='formal'] .kp-button--secondary:hover {
        background: var(--border);
    }

    [data-theme='formal'] .kp-button--ghost {
        color: var(--primary);
        border-color: var(--border-strong);
    }

    [data-theme='formal'] .kp-button--ghost:hover {
        background: var(--card);
    }

    /* The mirror: a static navy-on-gold double-strike offset shadow, the
       way a letterpress leaves its twin impression. Applies to whichever
       variant carries it — the demo puts it on the primary CTA and the
       shared markup also puts it on the destructive wipe button, which
       the demo itself did not show for that button (a Class B carry: the
       package's own markup, the demo's appearance kept where it can be). */
    [data-theme='formal'] .kp-button--mirror {
        box-shadow: 2px 2px 0 0 var(--fx-signal);
    }

    /* The mirror's static offset shadow and the two-channel focus ring
       share the box-shadow property; a combined rule (higher specificity
       than the plain :focus-visible selector, so order-independent) keeps
       both, exactly as the demo composes them. */
    [data-theme='formal'] .kp-button--mirror:focus-visible {
        box-shadow:
            2px 2px 0 0 var(--fx-signal),
            0 0 0 var(--kp-focus-ring-inner-width, 2px) var(--focus-ring);
    }

    [data-theme='formal'] .kp-icon-button {
        border-radius: var(--radius);
    }

    /* ── Fields: ruled boxes on the page ground ───────────────────────── */

    [data-theme='formal'] .kp-field {
        gap: var(--kp-space-xs);
    }

    [data-theme='formal'] .kp-field__label {
        font-weight: 600;
        color: var(--foreground);
    }

    [data-theme='formal'] .kp-field__input,
    [data-theme='formal'] .kp-datatable__search,
    [data-theme='formal'] .kp-combobox__input,
    [data-theme='formal'] .kp-palette__input {
        background: var(--background);
        border-color: var(--border-strong);
        border-radius: var(--radius);
    }

    [data-theme='formal'] .kp-fieldset {
        border-color: var(--border);
        border-radius: var(--radius);
    }

    /* ── Cards and the dossier: a file on the desk, redactions that clear
       left to right when the file is opened. ── */

    [data-theme='formal'] .kp-card {
        background: var(--card);
        border-color: var(--border);
        border-radius: var(--radius);
    }

    [data-theme='formal'] .kp-card__title {
        font-family: var(--theme-font-display);
        font-variation-settings: 'opsz' 60;
        font-weight: 600;
    }

    /* The stamp: a rotated brick-bordered badge, static — the demo's own
       "Draft — not for release" never changes text on reveal, so the
       package's data-kp-label-open swap is a no-op here by design (the
       copy entry repeats the same word). */
    [data-theme='formal'] .kp-card[data-kp-label]::before {
        content: attr(data-kp-label);
        position: absolute;
        inset-block-start: 0.8rem;
        inset-inline-end: 1.1rem;
        display: inline-block;
        font-family: var(--theme-font-display);
        font-variation-settings: 'opsz' 40;
        font-weight: 700;
        font-size: 0.75rem;
        letter-spacing: 0.14em;
        text-transform: uppercase;
        color: var(--destructive);
        border: 1.5px solid var(--destructive);
        border-radius: 3px;
        padding: 0.2rem 0.55rem;
        rotate: -3deg;
    }

    [data-theme='formal'] .kp-card[data-kp-reveal='emphasis'] {
        position: relative;
        background: var(--muted);
    }

    /* The redaction: a run of ink over the phrase, cleared left to right
       — a scale transform on a full-cover bar, the way a redaction pen is
       dragged off a page, not a fade. */
    [data-theme='formal'] .kp-card[data-kp-reveal='emphasis'] mark {
        position: relative;
        background: none;
        color: var(--card-foreground);
        padding: 0;
        border-radius: 0;
    }

    [data-theme='formal'] .kp-card[data-kp-reveal='emphasis'] mark::after {
        content: '';
        position: absolute;
        inset: -0.06em -0.1em;
        background: var(--foreground);
        transform-origin: left center;
        transform: scaleX(1);
    }

    [data-theme='formal'][data-kp-effects] .kp-card[data-kp-reveal='emphasis'] mark:not(.is-cleared)::after {
        transform: scaleX(1);
    }

    [data-theme='formal'][data-kp-effects] .kp-card[data-kp-reveal='emphasis'] mark.is-cleared::after {
        transform: scaleX(0);
    }

    /* ── Panels: one hairline boundary, the card's own paper ─────────── */

    [data-theme='formal'] .kp-dialog,
    [data-theme='formal'] .kp-popover,
    [data-theme='formal'] .kp-menu,
    [data-theme='formal'] .kp-toast,
    [data-theme='formal'] .kp-tooltip,
    [data-theme='formal'] .kp-confirm,
    [data-theme='formal'] .kp-datepicker__panel,
    [data-theme='formal'] .kp-combobox__list,
    [data-theme='formal'] .kp-palette,
    [data-theme='formal'] .kp-theme-menu {
        background: var(--card);
        border-color: var(--border);
        border-radius: var(--radius);
    }

    [data-theme='formal'] .kp-dialog__title {
        font-family: var(--theme-font-display);
        font-variation-settings: 'opsz' 60;
    }

    [data-theme='formal'] .kp-alert {
        border-radius: var(--radius);
    }

    [data-theme='formal'] .kp-toasts {
        gap: var(--kp-space-sm);
    }

    /* ── The footer: one step down, the muted stock ───────────────────── */

    [data-theme='formal'] .kp-footer {
        background: var(--muted);
    }

    [data-theme='formal'] .kp-footer h4 {
        font-size: 0.75rem;
        font-weight: 700;
        letter-spacing: 0.1em;
        text-transform: uppercase;
        color: var(--muted-foreground);
    }

    [data-theme='formal'] .kp-footer a {
        color: var(--foreground);
        text-decoration: none;
        text-underline-offset: 0.2em;
    }

    [data-theme='formal'] .kp-footer a:hover {
        color: var(--primary);
        text-decoration: underline;
    }

    /* ── The demo's own pieces [S46] ──────────────────────────────────── */

    [data-theme='formal'] .kp-side-note {
        font-family: var(--theme-font-body);
        font-size: 0.6875rem;
        letter-spacing: 0.18em;
        text-transform: uppercase;
        color: var(--muted-foreground);
        border-inline-start: 1px solid var(--border);
        padding-inline-start: 0.6rem;
    }

    [data-theme='formal'] .kp-laurels {
        font-size: 0.75rem;
        letter-spacing: 0.08em;
        color: var(--muted-foreground);
    }

    [data-theme='formal'] .kp-laurels svg,
    [data-theme='formal'] .kp-laurels [data-kp-icon] {
        color: var(--fx-signal);
    }

    [data-theme='formal'] .kp-platforms {
        font-size: 0.8125rem;
        color: var(--muted-foreground);
    }

    [data-theme='formal'] .kp-platforms strong,
    [data-theme='formal'] .kp-platforms b {
        color: var(--foreground);
        font-weight: 600;
    }

    /* The spec sheet: a specimen table, the palette and the two faces. */
    [data-theme='formal'] .kp-spec {
        border-block-start: 1px solid var(--border);
    }

    [data-theme='formal'] .kp-spec__swatch {
        border: 1px solid var(--border);
        border-radius: 4px;
    }

    [data-theme='formal'] .kp-spec__font {
        font-family: var(--theme-font-display);
    }

    [data-theme='formal'] .kp-spec__font--body {
        font-family: var(--theme-font-body);
    }

    /* ── Badges, tags, status ──────────────────────────────────────────── */

    [data-theme='formal'] .kp-badge,
    [data-theme='formal'] .kp-tag {
        border-radius: calc(var(--radius) - 2px);
    }

    [data-theme='formal'] .kp-health__dot {
        border-radius: 50%;
    }

    [data-theme='formal'] .kp-skeleton {
        border-radius: calc(var(--radius) / 2);
    }

    [data-theme='formal'] .kp-progress {
        background: var(--muted);
        border-radius: var(--radius);
    }

    [data-theme='formal'] .kp-progress__value {
        background: var(--primary);
    }

    [data-theme='formal'] .kp-spinner {
        border-color: var(--border);
        border-top-color: var(--primary);
    }

    [data-theme='formal'] .kp-empty {
        border: 1px dashed var(--border-strong);
        border-radius: var(--radius);
    }

    [data-theme='formal'] .kp-error {
        color: var(--destructive);
    }

    /* ── Text shapes ──────────────────────────────────────────────────── */

    [data-theme='formal'] .kp-id,
    [data-theme='formal'] .kp-url,
    [data-theme='formal'] .kp-numeric,
    [data-theme='formal'] .kp-timestamp,
    [data-theme='formal'] .kp-masked,
    [data-theme='formal'] .kp-copyable,
    [data-theme='formal'] .kp-truncate,
    [data-theme='formal'] .kp-cell-break,
    [data-theme='formal'] .kp-cell-truncate {
        font-family: var(--theme-font-body);
        color: var(--foreground);
    }

    [data-theme='formal'] .kp-timestamp,
    [data-theme='formal'] .kp-id {
        color: var(--muted-foreground);
    }

    [data-theme='formal'] .kp-copyable__button {
        border-radius: calc(var(--radius) / 2);
    }

    /* ── Data ─────────────────────────────────────────────────────────── */

    [data-theme='formal'] .kp-table {
        border-color: var(--border);
    }

    [data-theme='formal'] .kp-table th {
        font-weight: 600;
        color: var(--muted-foreground);
        border-bottom: 1px solid var(--border-strong);
    }

    [data-theme='formal'] .kp-table td {
        border-bottom: 1px solid var(--border);
    }

    [data-theme='formal'] .kp-datatable {
        border: 1px solid var(--border);
        border-radius: var(--radius);
    }

    [data-theme='formal'] .kp-datatable__sort[aria-sort] {
        color: var(--primary);
    }

    [data-theme='formal'] .kp-diff {
        border-radius: var(--radius);
    }

    [data-theme='formal'] .kp-timeline {
        border-inline-start: 1px solid var(--border);
    }

    [data-theme='formal'] .kp-timeline__marker {
        background: var(--primary);
        border-radius: 50%;
    }

    [data-theme='formal'] .kp-reorder {
        border-radius: var(--radius);
    }

    [data-theme='formal'] .kp-tree {
        font-family: var(--theme-font-body);
        color: var(--foreground);
    }

    /* ── Navigation and steps ──────────────────────────────────────────── */

    [data-theme='formal'] .kp-tab {
        border-radius: calc(var(--radius) - 2px);
    }

    [data-theme='formal'] .kp-tab[aria-selected='true'] {
        color: var(--primary);
        border-color: var(--primary);
    }

    [data-theme='formal'] .kp-breadcrumb,
    [data-theme='formal'] .kp-pagination {
        color: var(--muted-foreground);
    }

    [data-theme='formal'] .kp-pagination [aria-current] {
        background: var(--primary);
        color: var(--primary-foreground);
        border-radius: var(--radius);
    }

    [data-theme='formal'] .kp-wizard {
        border: 1px solid var(--border);
        border-radius: var(--radius);
        background: var(--card);
    }

    /* ── Pickers and palettes ─────────────────────────────────────────── */

    [data-theme='formal'] .kp-datepicker__day[aria-selected='true'] {
        background: var(--primary);
        color: var(--primary-foreground);
        border-radius: 50%;
    }

    [data-theme='formal'] .kp-colorpicker__swatch {
        border: 1px solid var(--border);
        border-radius: 4px;
    }

    [data-theme='formal'] .kp-shortcuts__row kbd {
        border: 1px solid var(--border-strong);
        border-radius: calc(var(--radius) / 2);
        background: var(--muted);
    }

    [data-theme='formal'] .kp-shortcuts__group-label,
    [data-theme='formal'] .kp-palette__group-label {
        color: var(--muted-foreground);
        letter-spacing: 0.06em;
        text-transform: uppercase;
    }

    [data-theme='formal'] .kp-theme-menu__status,
    [data-theme='formal'] .kp-palette__status,
    [data-theme='formal'] .kp-combobox__status {
        color: var(--muted-foreground);
    }

    /* ── The roots the rules above reach only by their parts ──────────── */

    [data-theme='formal'] .kp-form {
        gap: var(--kp-space-lg);
    }

    [data-theme='formal'] .kp-grid {
        gap: var(--kp-space-lg);
    }

    [data-theme='formal'] .kp-grid > * {
        border-radius: var(--radius);
    }

    [data-theme='formal'] .kp-split {
        gap: 0;
    }

    [data-theme='formal'] .kp-split__separator {
        background: var(--border);
    }

    [data-theme='formal'] .kp-health {
        color: var(--muted-foreground);
    }

    [data-theme='formal'] .kp-combobox,
    [data-theme='formal'] .kp-datepicker,
    [data-theme='formal'] .kp-colorpicker,
    [data-theme='formal'] .kp-shortcuts,
    [data-theme='formal'] .kp-tabs {
        border-radius: var(--radius);
    }

    /* ── Motion, guarded [DI7] ────────────────────────────────────────── */

    /* Every transition of this register lives here, inside the
       no-preference guard, so a reader who asked for reduced motion never
       receives one: the rest states above (already the revealed look) are
       what they get. There is no `@keyframes` in this register — every
       reveal is a plain transition — so DI5's report has nothing to add
       for formal: nothing here loops and every run is one-shot, well
       under the three-opposing-changes-per-second bar. */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='formal'] [data-kp-reveal='headline'] {
            transition:
                opacity 450ms var(--fx-ease),
                transform 450ms var(--fx-ease);
        }

        [data-theme='formal'] mark {
            transition: background-size 350ms var(--fx-ease);
        }

        [data-theme='formal'] [data-kp-reveal='rule']::after {
            transition: transform 450ms var(--fx-ease);
        }

        [data-theme='formal'] .kp-card[data-kp-reveal='emphasis'] mark::after {
            transition: transform 260ms var(--fx-ease);
        }

        [data-theme='formal'] .kp-card[data-kp-reveal='emphasis'] mark:nth-of-type(2)::after {
            transition-delay: var(--kp-redact-stagger, 80ms);
        }

        [data-theme='formal'] .kp-card[data-kp-reveal='emphasis'] mark:nth-of-type(3)::after {
            transition-delay: calc(2 * var(--kp-redact-stagger, 80ms));
        }
    }
    /* The band [M1, M4]: Kenny picked this theme's own version over the
       shared one on 2026-09-08 — small caps between two hairlines, the slowest pass in the package. */
    [data-theme='formal'] .kp-marquee {
        border-block: 1px solid var(--border-strong);
        background: color-mix(in srgb, var(--card) 70%, var(--background));
        font-variant-caps: all-small-caps;
        letter-spacing: 0.08em;
        --kp-marquee: 60000ms;
    }

    /* The menu's caption [M3]: the same choice, for the line a consumer
       may put above a dropdown's items. */
    [data-theme='formal'] .kp-nav__menu[data-kp-menu-label]::before {
        font-variant-caps: all-small-caps;
        letter-spacing: 0.1em;
        color: var(--foreground);
        border-block-end: 1px solid var(--border-strong);
    }
}

@layer kp.register {
    /* @kp-soft/themes — css/sepia-register.css
   The sepia register, 5.0.0 [S48, LIFT_PLAN row 9]: aged paper and warm
   brown ink. Scoped to [data-theme='sepia'] and inert elsewhere; opt-in,
   imported after themes.css. The approved concept demo ("Aged Well",
   2026-09-08) is the reference for every value here, and
   docs/RESEARCH_2026-09.md §9 is where each mechanism was measured:
   Public Domain Review's double gold rule as a section divider, here in
   the theme's own warm-brown family rather than PDR's literal gold (no
   colour outside 24°–45°, anatomy.md); Miranda's `mix-blend-mode:
   multiply` ink wash, confined to two small marks (the drop cap's corner,
   the dossier stamp) and never a page-wide texture — the obvious
   flourish, and the one this file refuses, because a mottled background
   would cost the contrast the reader is here for; Miranda's 7vw drop cap
   on the lede's first letter; Miranda's hand-drawn underline
   (`stroke-dasharray`/`stroke-dashoffset` in the demo's SVG) rebuilt here
   as a transform-scaled rule, because the concept page's markup is fixed
   across every theme (S46) and carries no `<svg>` for a per-theme curve —
   the finding is recorded in anatomy.md; craigmod's small-caps
   microlabels and laurels, and its habit of naming every colour once
   rather than re-deriving it.

   Every value in the demo's `:root` block already equalled a token this
   theme's tokens.json declared before this file existed (measured at X0
   by converting each of the demo's literal hex values to HSL and diffing
   against tokens.json: paper is --background, ink is --foreground,
   sienna is --primary, rule-color is --border-strong and --input,
   hairline is --border, tint is --accent, red is --destructive, selected
   is --selected, and so on for every remaining pair) — so no token
   changed for this lift, which is itself an X0 finding, not a silent
   assumption.

   What this file does, in order: the knobs; the type; the hooks of S45 —
   the headline's ink-in settle, the mark as a wash that deepens, the
   drawn rule under a heading, the double warm-brown divider; the hero's
   colophon and drop cap; the navbar with the dropdown (KT14); the quiet
   plate buttons; the fields; the dossier's stamp and redactions; the
   confirmation dialog; and one answer per component root (TH124). The
   reveals have their rest state here and their motion in js/effects.js;
   without the script every one of them stands at rest, already legible
   — this theme conceals nothing behind its script (anatomy.md: "no
   aged-paper texture", "no sepia photograph feel").

   Colour discipline (DI9): nothing here names a colour. The ink wash is
   `hsl(from var(--primary) h s l / alpha)`; every plate, border and
   shadow is a token. No texture: this theme declares neither
   `--fx-texture` nor `--fx-texture-opacity` — the DI9 hazard this
   register refuses is a page-wide grain, and the two small multiply
   marks below sit beside text, never across it (S42's spirit, applied
   to a hazard rather than an overrun: refused wholesale rather than
   dialled down).

   Motion (DI5, DI7): every transition and the one keyframes animation
   below live inside the no-preference guard. Every reveal is one-shot —
   the headline settles once, the two lede marks deepen once each
   staggered by --kp-reveal-stagger, the rule draws once on scroll, the
   redactions lift once on a click, the dialog's backdrop fades once.
   Nothing loops, nothing oscillates: DI5's rate is zero opposing changes
   a second everywhere on this page, because nothing here repeats. */

    [data-theme='sepia'] {
        /* The configuration surface [AR43], the demo's own values as
           defaults: 900ms before the first mark deepens, 420ms between
           the two (the demo's own setTimeout schedule), 150ms between
           one redaction lifting and the next. */
        --kp-reveal-threshold: 0.6;
        --kp-reveal-stagger: 420ms;
        --kp-classified-delay: 900ms;
        --kp-redact-stagger: 150ms;
        --kp-ink-duration: 1050ms;
        --kp-rule-duration: 760ms;
        --kp-redact-duration: 600ms;
        --kp-underline-duration: 450ms;
        /* The demo's own easing: a hand-drawn settle, not a mechanical one. */
        --kp-hand: cubic-bezier(0.785, 0.135, 0.15, 0.86);
        /* The reveals this theme performs [S45]: js/effects.js reads these
           and leaves a theme that declares none at rest. `ink` is new —
           no existing headline routine is a whole-line settle with no
           per-word stagger (this theme is unhurried on purpose,
           anatomy.md) — added at X2 with its own branch in
           js/effects.js. `wash` and `draw` do not change effects.js at
           all: the emphasis and rule reveals are routine-agnostic there,
           toggling only `is-cleared` / `is-in`, so any name documents the
           mechanism without adding code. */
        --kp-reveal-headline: ink;
        --kp-reveal-emphasis: wash;
        --kp-reveal-rule: draw;
        --kp-mono: var(--theme-font-mono);
        /* The ink wash [Miranda, mix-blend-mode: multiply]: confined to the
           drop cap's corner and the dossier stamp, never a page-wide
           texture. A relative colour of --primary, never a colour of its
           own (DI9). */
        --kp-wash: radial-gradient(ellipse at 30% 30%, hsl(from var(--primary) h s l / 0.5), transparent 70%);
    }

    /* ── Type ──────────────────────────────────────────────────────────── */

    [data-theme='sepia'] h1,
    [data-theme='sepia'] h2,
    [data-theme='sepia'] h3 {
        font-family: var(--theme-font-display);
        font-weight: 400;
        line-height: 1.1;
    }

    [data-theme='sepia'] [data-kp-surface] h2,
    [data-theme='sepia'] .kp-card__title,
    [data-theme='sepia'] .kp-dialog__title,
    [data-theme='sepia'] .kp-spec h2 {
        font-style: italic;
    }

    /* Microlabels: craigmod's small caps, the sienna ink. */
    [data-theme='sepia'] .microlabel {
        font-variant: small-caps;
        text-transform: lowercase;
        letter-spacing: 0.1em;
        color: var(--primary);
    }

    /* ── The hooks [S45]: the headline, the mark, the rule, the divider ── */

    /* The heading accent: a surface heading is the serif at rest, roman
       for h1 and italic for h2 — the theme's whole character is the face,
       not a shadow or an offset (anatomy.md: nothing here glows or
       shouts). */
    [data-theme='sepia'] [data-kp-surface] h1 {
        font-size: var(--kp-text-display);
        font-weight: 400;
        line-height: 1.08;
        margin-block: 0 0.35em;
        text-wrap: balance;
        color: var(--foreground);
    }

    /* The headline reveal: the ink-in. A faint ghost of the ink colour,
       blurred, settles to the full colour in one shot — the whole line
       moving together, because this theme (anatomy.md) is "unhurried on
       purpose" and stages no per-word stagger. Without the script the
       headline stands in its full colour already; with the script armed
       the module adds `is-settling` for one frame, then removes it —
       the transition below carries the properties back to their plain
       values (js/effects.js: the ink routine). A quiet theme or reduced
       motion never adds the class at all, so nothing ghosts. */
    [data-theme='sepia'][data-kp-effects] [data-kp-reveal='headline'].is-settling {
        color: var(--muted-foreground);
        filter: blur(5px);
        opacity: 0.35;
    }

    /* The mark: a wash. At rest — no script, or a loose mark once the
       module has cleared it — the tint is a warm plate the ink already
       reads on; the script's own contribution is a small deepening of
       the ink to the plate's own foreground once the mark has "settled",
       the same restraint the headline keeps. */
    [data-theme='sepia'] mark {
        background: var(--accent);
        color: var(--accent-foreground);
        padding-inline: 0.2em;
        border-radius: 0.2em;
        box-decoration-break: clone;
        -webkit-box-decoration-break: clone;
    }

    [data-theme='sepia'][data-kp-effects] mark:not(.is-cleared) {
        color: var(--foreground);
    }

    /* The rule: a hand-drawn line under a heading, drawn once when the
       heading scrolls into view. The demo drew this with an SVG path and
       `stroke-dashoffset`; the concept page's markup is the same for
       every theme (S46) and carries no `<svg>` for a per-theme curve, so
       this register draws the same motion — a line growing from nothing
       to its full width, the demo's own easing — with a scaled
       pseudo-element instead (an X1 finding, recorded in anatomy.md:
       "not reproducible without markup"). Without the script the rule
       stands drawn. */
    [data-theme='sepia'] [data-kp-reveal='rule']::after {
        content: '';
        display: block;
        inline-size: 6rem;
        block-size: 2px;
        margin-block-start: 0.65rem;
        background: var(--border-strong);
        transform: scaleX(1);
        transform-origin: left center;
    }

    [data-theme='sepia'][data-kp-effects] [data-kp-reveal='rule']:not(.is-in)::after {
        transform: scaleX(0);
    }

    /* The divider: a double warm-brown rule, sepia's answer to the razor
       tear — Public Domain Review's device, kept inside this theme's own
       24°–45° family rather than PDR's literal gold (anatomy.md). The
       concept page's divider is one bare element for every theme (S46),
       so both lines are painted as layered backgrounds on it rather than
       child elements. The `alt` variant carries a small diamond at the
       centre, drawn in a pseudo-element — the theme's second-tear
       flourish, still the same two lines underneath. */
    [data-theme='sepia'] [data-kp-divider] {
        position: relative;
        display: block;
        block-size: 1rem;
        background:
            linear-gradient(var(--border-strong), var(--border-strong)) 0 32% / 100% 1px no-repeat,
            linear-gradient(var(--border-strong), var(--border-strong)) 0 68% / 100% 1px no-repeat;
    }

    [data-theme='sepia'] [data-kp-divider='alt']::after {
        content: '◆';
        position: absolute;
        inset-inline-start: 50%;
        inset-block-start: 50%;
        translate: -50% -55%;
        color: var(--border-strong);
        background: var(--background);
        padding-inline: 0.6rem;
        font-size: 0.75rem;
    }

    /* ── The hero: the side note, the laurels, the drop cap, the colophon ── */

    [data-theme='sepia'] .kp-side-note {
        font-variant: small-caps;
        text-transform: lowercase;
        letter-spacing: 0.14em;
        color: var(--muted-foreground);
    }

    [data-theme='sepia'] .kp-laurels {
        gap: 0.5rem;
    }

    [data-theme='sepia'] .kp-laurels li {
        padding: 0.3rem 0.7rem;
        font-size: 0.78rem;
        letter-spacing: 0.04em;
        font-variant: small-caps;
        text-transform: lowercase;
        color: var(--muted-foreground);
        border: 1px solid var(--border);
        border-radius: 999px;
        background: var(--card);
    }

    [data-theme='sepia'] .kp-laurels li:first-child {
        color: var(--primary-foreground);
        background: var(--primary);
        border-color: var(--primary);
    }

    [data-theme='sepia'] .kp-laurels b {
        font-weight: inherit;
    }

    [data-theme='sepia'] .kp-lede {
        max-width: 38rem;
    }

    /* The drop cap: Miranda's 7vw display-face initial, clamped so it
       cannot outgrow a small viewport, with the ink wash confined to its
       own corner — a decorative mark, never crossing a line of text. */
    [data-theme='sepia'] .kp-lede::first-letter {
        font-family: var(--theme-font-display);
        font-style: italic;
        font-size: clamp(2.4rem, 7vw, 4.2rem);
        line-height: 0.72;
        float: inline-start;
        margin: 0.03em 0.14em 0 0;
        color: var(--primary);
        position: relative;
    }

    [data-theme='sepia'] .kp-lede::before {
        content: '';
        position: absolute;
        inset-inline-start: 0;
        inset-block-start: 0;
        inline-size: 1.6em;
        block-size: 1.6em;
        background: var(--kp-wash);
        mix-blend-mode: multiply;
        pointer-events: none;
        z-index: -1;
    }

    [data-theme='sepia'] .kp-platforms {
        gap: 0.2rem 1.3rem;
        color: var(--muted-foreground);
    }

    [data-theme='sepia'] .kp-platforms span::before {
        content: '· ';
        color: var(--primary);
    }

    /* The colophon: a quiet card, the palette named once. */
    [data-theme='sepia'] .kp-spec {
        background: var(--card);
        border: 1px solid var(--border);
        border-radius: 0.5rem;
        padding: 1.2rem 1.3rem 1.4rem;
        font-size: 0.85rem;
    }

    [data-theme='sepia'] .kp-spec dt {
        font-variant: small-caps;
        text-transform: lowercase;
        letter-spacing: 0.04em;
        color: var(--muted-foreground);
    }

    [data-theme='sepia'] .kp-spec__swatch {
        border: 1px solid hsl(from var(--foreground) h s l / 0.18);
        border-radius: 50%;
    }

    [data-theme='sepia'] .kp-spec__font {
        font-family: var(--theme-font-display);
    }

    /* ── The navbar: the brand, the tag, the strip, the dropdown (KT14) ── */

    [data-theme='sepia'] .kp-nav-wrap {
        background: var(--background);
        border-bottom: 1px solid var(--border);
    }

    [data-theme='sepia'] .kp-nav {
        background: var(--background);
        padding-block: 1.1rem;
    }

    [data-theme='sepia'] .kp-nav__brand {
        font-family: var(--theme-font-display);
        font-style: italic;
        font-size: 1.5rem;
        color: var(--foreground);
    }

    [data-theme='sepia'] .kp-nav__brand-tag {
        display: block;
        font-family: var(--font-sans, var(--theme-font-body));
        font-style: normal;
        font-size: 0.68rem;
        letter-spacing: 0.16em;
        font-variant: small-caps;
        text-transform: lowercase;
        color: var(--muted-foreground);
        margin-block-start: 0.1rem;
    }

    [data-theme='sepia'] .kp-nav__link {
        padding: 0.5rem 0.7rem;
        font-size: 0.92rem;
        color: var(--foreground);
        border-radius: 0.25rem;
    }

    [data-theme='sepia'] .kp-nav__link:hover,
    [data-theme='sepia'] .kp-nav__link:focus-visible,
    [data-theme='sepia'] .kp-nav__link[aria-current],
    [data-theme='sepia'] .kp-nav__links > li:focus-within > .kp-nav__link {
        background: var(--card);
        color: var(--primary);
        box-shadow: none;
    }

    [data-theme='sepia'] .kp-nav__link[aria-haspopup]::after {
        content: ' \2304';
        font-size: 0.7em;
        color: var(--muted-foreground);
    }

    [data-theme='sepia'] .kp-nav__link--lang {
        margin-inline-start: 0.2rem;
        border-inline-start: 1px solid var(--border);
        padding-inline-start: 0.9rem;
    }

    [data-theme='sepia'] .kp-nav__link--cta {
        margin-inline-start: 0.5rem;
        background: var(--primary);
        color: var(--primary-foreground);
        align-self: center;
    }

    [data-theme='sepia'] .kp-nav__link--cta:hover,
    [data-theme='sepia'] .kp-nav__link--cta:focus-visible {
        background: hsl(from var(--primary) h s calc(l - 5%));
        color: var(--primary-foreground);
    }

    /* The dropdown (KT14): a quiet card popover, the sienna ink on hover —
       opened and looked at before this register was called done. */
    [data-theme='sepia'] .kp-nav__menu {
        background: var(--popover);
        border: 1px solid var(--border);
        border-radius: 0.375rem;
        box-shadow: 0 8px 24px -8px hsl(from var(--foreground) h s l / 0.25);
        padding: 0.35rem 0;
        min-width: 12rem;
    }

    [data-theme='sepia'] .kp-nav__menu a {
        padding: 0.4rem 0.9rem;
        font-size: 0.86rem;
        color: var(--foreground);
        border-radius: 0;
    }

    [data-theme='sepia'] .kp-nav__menu a:hover,
    [data-theme='sepia'] .kp-nav__menu a:focus-visible {
        background: var(--card);
        color: var(--primary);
    }

    /* ── Buttons: quiet plates, no bevel, the theme's own 0.375rem ──────── */

    [data-theme='sepia'] .kp-button,
    [data-theme='sepia'] .kp-icon-button {
        border-radius: 0.375rem;
        border: 1px solid var(--border-strong);
        background: transparent;
        color: var(--foreground);
        font-weight: 500;
        /* The transition itself lives inside the no-preference guard
           below (DI7); box-shadow is deliberately not in it, because
           DI2's focus ring must be visible instantly, not eased in. */
    }

    [data-theme='sepia'] .kp-button:hover,
    [data-theme='sepia'] .kp-icon-button:hover {
        border-color: var(--foreground);
    }

    [data-theme='sepia'] .kp-button:active:not(:disabled),
    [data-theme='sepia'] .kp-icon-button:active:not(:disabled) {
        box-shadow: inset 0 1px 3px hsl(from var(--foreground) h s l / 0.18);
    }

    [data-theme='sepia'] .kp-button--primary {
        background: var(--primary);
        color: var(--primary-foreground);
        border-color: var(--primary);
    }

    [data-theme='sepia'] .kp-button--primary:hover {
        background: hsl(from var(--primary) h s calc(l - 4%));
        border-color: hsl(from var(--primary) h s calc(l - 4%));
    }

    [data-theme='sepia'] .kp-button--ghost {
        border-color: transparent;
        color: var(--muted-foreground);
    }

    [data-theme='sepia'] .kp-button--ghost:hover {
        color: var(--foreground);
        background: var(--card);
    }

    [data-theme='sepia'] .kp-button--destructive {
        border-color: var(--destructive);
        color: var(--destructive);
        background: transparent;
    }

    [data-theme='sepia'] .kp-button--destructive:hover {
        background: var(--destructive);
        color: var(--destructive-foreground);
    }

    [data-theme='sepia'] .kp-button--mirror {
        box-shadow:
            0 0 0 1px var(--background),
            0 0 0 2px var(--border-strong);
    }

    [data-theme='sepia'] .kp-button:disabled,
    [data-theme='sepia'] .kp-icon-button:disabled {
        opacity: 0.5;
    }

    /* ── Fields: wells on the palest surface ────────────────────────────── */

    [data-theme='sepia'] .kp-field__label {
        font-size: 0.85rem;
        color: var(--muted-foreground);
    }

    [data-theme='sepia'] .kp-field__input,
    [data-theme='sepia'] .kp-datatable__search,
    [data-theme='sepia'] .kp-combobox__input,
    [data-theme='sepia'] .kp-palette__input {
        background: var(--popover);
        border: 1px solid var(--border-strong);
        border-radius: 0.375rem;
    }

    [data-theme='sepia'] .kp-field__input:focus-visible,
    [data-theme='sepia'] .kp-datatable__search:focus-visible,
    [data-theme='sepia'] .kp-combobox__input:focus-visible,
    [data-theme='sepia'] .kp-palette__input:focus-visible {
        border-color: var(--foreground);
    }

    [data-theme='sepia'] select.kp-field__input::picker-icon {
        color: var(--primary);
    }

    [data-theme='sepia'] .kp-field__help {
        font-size: 0.8rem;
        color: var(--muted-foreground);
    }

    [data-theme='sepia'] .kp-field--invalid .kp-field__input {
        border-color: var(--destructive);
    }

    [data-theme='sepia'] .kp-field__error {
        color: var(--destructive);
    }

    [data-theme='sepia'] .kp-field__check {
        accent-color: var(--primary);
    }

    [data-theme='sepia'] .kp-fieldset {
        border: 1px solid var(--border);
        border-radius: 0.375rem;
    }

    [data-theme='sepia'] .kp-form__summary {
        border-inline-start: 3px solid var(--primary);
        background: var(--card);
        border-radius: 0.375rem;
    }

    /* ── Cards, dialogs, popovers: paper-2 and paper-3 ──────────────────── */

    [data-theme='sepia'] .kp-card {
        background: var(--card);
        border: 1px solid var(--border);
        border-radius: 0.5rem;
    }

    /* The dossier's stamp (KT5: the word is data, from data-kp-label, not
       CSS content) — rotated, the ink wash behind it, the second and last
       appearance of the multiply layer. */
    [data-theme='sepia'] .kp-card[data-kp-label] {
        position: relative;
    }

    [data-theme='sepia'] .kp-card[data-kp-label]::before {
        content: attr(data-kp-label);
        position: absolute;
        inset-inline-end: 1.1rem;
        inset-block-start: 1rem;
        rotate: -3deg;
        font-variant: small-caps;
        text-transform: lowercase;
        letter-spacing: 0.1em;
        font-size: 0.72rem;
        color: var(--accent-foreground);
        border: 1px solid var(--primary);
        border-radius: 0.25rem;
        padding: 0.25rem 0.6rem;
        background: var(--card);
    }

    [data-theme='sepia'] .kp-card[data-kp-label]::after {
        content: '';
        position: absolute;
        inset-inline-end: 0.6rem;
        inset-block-start: 0.4rem;
        inline-size: 3.6rem;
        block-size: 2rem;
        background: var(--kp-wash);
        mix-blend-mode: multiply;
        opacity: 0.55;
        border-radius: inherit;
        pointer-events: none;
        z-index: -1;
    }

    /* The dossier's redactions: a mark inside a triggered emphasis
       container is a solid ink bar over the words until the file opens,
       then the bar lifts — the demo's own mechanism (a scaled
       pseudo-element, transform-origin left, matching the CSS the demo
       actually ships, not only its prose). Without the script the bar is
       retracted and the words read plainly (AR34: the rest state holds
       without the module). */
    [data-theme='sepia'] .kp-card[data-kp-reveal='emphasis'] mark {
        position: relative;
        color: var(--card-foreground);
        background: none;
        padding: 0;
        font-weight: 400;
        border-radius: 0.15em;
    }

    [data-theme='sepia'] .kp-card[data-kp-reveal='emphasis'] mark::after {
        content: '';
        position: absolute;
        inset: -0.04em -0.08em;
        background: var(--foreground);
        border-radius: 0.15em;
        transform-origin: left center;
        transform: scaleX(0);
        pointer-events: none;
    }

    [data-theme='sepia'][data-kp-effects] .kp-card[data-kp-reveal='emphasis'] mark:not(.is-cleared) {
        color: transparent;
    }

    [data-theme='sepia'][data-kp-effects] .kp-card[data-kp-reveal='emphasis'] mark:not(.is-cleared)::after {
        transform: scaleX(1);
    }

    [data-theme='sepia'] .kp-dialog,
    [data-theme='sepia'] .kp-popover,
    [data-theme='sepia'] .kp-menu,
    [data-theme='sepia'] .kp-toast,
    [data-theme='sepia'] .kp-tooltip,
    [data-theme='sepia'] .kp-confirm,
    [data-theme='sepia'] .kp-datepicker__panel,
    [data-theme='sepia'] .kp-combobox__list,
    [data-theme='sepia'] .kp-palette,
    [data-theme='sepia'] .kp-theme-menu {
        background: var(--popover);
        border: 1px solid var(--border);
        border-radius: 0.6rem;
        box-shadow: 0 20px 50px -12px hsl(from var(--foreground) h s l / 0.35);
    }

    [data-theme='sepia'] .kp-toasts {
        gap: 0.6rem;
    }

    /* The keyboard highlight stays the base layer's wash of the ink
       (KT8): the list text keeps its own colour, the highlight is a
       plate under it, never a colour the option's text takes on. */
    [data-theme='sepia'] .kp-menu__item:hover {
        background: var(--card);
    }

    [data-theme='sepia'] .kp-alert {
        background: var(--card);
        border: 1px solid var(--border);
        border-inline-start: 3px solid var(--accent);
        border-radius: 0.5rem;
    }

    [data-theme='sepia'] .kp-alert--destructive {
        border-inline-start-color: var(--destructive);
    }

    [data-theme='sepia'] .kp-alert--warning {
        border-inline-start-color: var(--warning, var(--accent));
    }

    [data-theme='sepia'] .kp-alert--success {
        border-inline-start-color: var(--success-foreground, var(--primary));
    }

    [data-theme='sepia'] .kp-alert__label {
        font-family: var(--theme-font-display);
        font-style: italic;
    }

    [data-theme='sepia'] .kp-grid {
        gap: var(--kp-space-md, 0.75rem);
    }

    [data-theme='sepia'] .kp-grid__tile,
    [data-theme='sepia'] .kp-split__pane {
        background: var(--card);
        border: 1px solid var(--border);
        border-radius: 0.5rem;
    }

    [data-theme='sepia'] .kp-split {
        gap: var(--kp-space-md, 0.75rem);
    }

    [data-theme='sepia'] .kp-split__separator {
        background: var(--border);
    }

    /* ── Footer: hairline rule, sienna links ────────────────────────────── */

    [data-theme='sepia'] .kp-footer {
        background: var(--card);
        color: var(--muted-foreground);
        border-block-start: 1px solid var(--border);
    }

    [data-theme='sepia'] .kp-footer h4 {
        font-variant: small-caps;
        text-transform: lowercase;
        letter-spacing: 0.06em;
        color: var(--foreground);
    }

    /* The footer's links: the demo's hand-drawn underline, here a
       background-size transition rather than an injected SVG rule per
       link (the same markup constraint as the drawn rule above; an X1
       finding, anatomy.md). At rest the underline is drawn — a page
       without the script shows exactly what a page with it settles to. */
    [data-theme='sepia'] .kp-footer a {
        color: var(--primary);
        text-decoration: none;
        background-image: linear-gradient(var(--primary), var(--primary));
        background-repeat: no-repeat;
        background-position: 0 100%;
        background-size: 100% 1px;
        padding-block-end: 0.05em;
    }

    [data-theme='sepia'] .kp-footer a:hover,
    [data-theme='sepia'] .kp-footer a:focus-visible {
        color: var(--foreground);
        background-image: linear-gradient(var(--foreground), var(--foreground));
    }

    /* ── Badges, tags, status: warm plates ──────────────────────────────── */

    [data-theme='sepia'] .kp-badge,
    [data-theme='sepia'] .kp-tag {
        border-radius: 999px;
        border: 1px solid var(--border);
        font-size: 0.78rem;
        letter-spacing: 0.02em;
    }

    [data-theme='sepia'] .kp-health {
        font-size: 0.85rem;
    }

    [data-theme='sepia'] .kp-health__dot {
        border-radius: 50%;
    }

    [data-theme='sepia'] .kp-skeleton {
        background: var(--card);
        border-radius: 0.375rem;
    }

    [data-theme='sepia'] .kp-progress {
        background: var(--card);
        border-radius: 999px;
        overflow: hidden;
    }

    [data-theme='sepia'] .kp-progress__value {
        background: var(--primary);
    }

    [data-theme='sepia'] .kp-spinner {
        border-color: var(--border);
        border-top-color: var(--primary);
    }

    [data-theme='sepia'] .kp-empty {
        border: 1px dashed var(--border);
        border-radius: 0.5rem;
    }

    [data-theme='sepia'] .kp-empty__title {
        font-family: var(--theme-font-display);
        font-style: italic;
    }

    [data-theme='sepia'] .kp-error {
        color: var(--destructive);
    }

    /* ── Text shapes: the mono face, the theme's only concession to it ─── */

    [data-theme='sepia'] .kp-id,
    [data-theme='sepia'] .kp-url,
    [data-theme='sepia'] .kp-numeric,
    [data-theme='sepia'] .kp-timestamp,
    [data-theme='sepia'] .kp-masked,
    [data-theme='sepia'] .kp-copyable,
    [data-theme='sepia'] .kp-truncate,
    [data-theme='sepia'] .kp-cell-break,
    [data-theme='sepia'] .kp-cell-truncate {
        font-family: var(--kp-mono);
        font-size: 0.92em;
    }

    [data-theme='sepia'] .kp-copyable__button {
        border: 1px solid var(--border);
        border-radius: 0.25rem;
    }

    /* ── Data: the table, the diff, the timeline, the tree ──────────────── */

    [data-theme='sepia'] .kp-table {
        background: var(--popover);
    }

    [data-theme='sepia'] .kp-table th {
        background: var(--card);
        border-bottom: 1px solid var(--border-strong);
        font-weight: 600;
    }

    [data-theme='sepia'] .kp-table td {
        border-bottom: 1px solid var(--border);
    }

    [data-theme='sepia'] .kp-table tbody tr:hover {
        background: var(--card);
    }

    [data-theme='sepia'] .kp-datatable {
        border: 1px solid var(--border);
        border-radius: 0.5rem;
        background: var(--popover);
    }

    [data-theme='sepia'] .kp-datatable__bar {
        background: var(--card);
        border-bottom: 1px solid var(--border);
    }

    [data-theme='sepia'] .kp-datatable__sort[aria-sort] {
        color: var(--primary);
    }

    [data-theme='sepia'] .kp-datatable__status,
    [data-theme='sepia'] .kp-datatable__page {
        font-size: 0.82rem;
        color: var(--muted-foreground);
    }

    [data-theme='sepia'] .kp-diff {
        border: 1px solid var(--border);
        border-radius: 0.5rem;
        background: var(--popover);
    }

    [data-theme='sepia'] .kp-diff__line {
        font-family: var(--kp-mono);
    }

    [data-theme='sepia'] .kp-timeline {
        border-inline-start: 2px solid var(--border);
    }

    [data-theme='sepia'] .kp-timeline__marker {
        background: var(--primary);
        border-radius: 50%;
    }

    [data-theme='sepia'] .kp-timeline__when {
        color: var(--muted-foreground);
        font-family: var(--kp-mono);
        font-size: 0.85rem;
    }

    [data-theme='sepia'] .kp-tree {
        font-family: var(--kp-mono);
        font-size: 0.9rem;
    }

    [data-theme='sepia'] .kp-reorder {
        border: 1px solid var(--border);
        border-radius: 0.5rem;
        background: var(--popover);
    }

    /* ── Navigation and steps ────────────────────────────────────────────── */

    [data-theme='sepia'] .kp-tab {
        color: var(--muted-foreground);
        border-bottom: 2px solid transparent;
    }

    [data-theme='sepia'] .kp-tab[aria-selected='true'] {
        color: var(--primary);
        border-bottom-color: var(--primary);
        font-weight: 600;
    }

    [data-theme='sepia'] .kp-tabs__list {
        border-bottom: 1px solid var(--border);
    }

    [data-theme='sepia'] .kp-breadcrumb,
    [data-theme='sepia'] .kp-pagination {
        font-size: 0.88rem;
        color: var(--muted-foreground);
    }

    [data-theme='sepia'] .kp-pagination a[aria-current],
    [data-theme='sepia'] .kp-pagination [aria-current] {
        background: var(--primary);
        color: var(--primary-foreground);
        border-radius: 0.25rem;
    }

    [data-theme='sepia'] .kp-wizard {
        border: 1px solid var(--border);
        border-radius: 0.5rem;
        background: var(--card);
    }

    [data-theme='sepia'] .kp-wizard__steps {
        color: var(--muted-foreground);
        font-size: 0.85rem;
    }

    /* ── Pickers and palettes ────────────────────────────────────────────── */

    [data-theme='sepia'] .kp-datepicker__day[aria-selected='true'] {
        background: var(--primary);
        color: var(--primary-foreground);
        border-radius: 50%;
    }

    [data-theme='sepia'] .kp-datepicker__weekday,
    [data-theme='sepia'] .kp-datepicker__title {
        color: var(--muted-foreground);
    }

    [data-theme='sepia'] .kp-colorpicker__swatch {
        border: 1px solid var(--border);
        border-radius: 0.25rem;
    }

    [data-theme='sepia'] .kp-colorpicker__value {
        font-family: var(--kp-mono);
    }

    [data-theme='sepia'] .kp-shortcuts__row kbd {
        font-family: var(--kp-mono);
        border: 1px solid var(--border-strong);
        border-radius: 0.25rem;
        background: var(--card);
        padding: 0 0.4em;
    }

    [data-theme='sepia'] .kp-shortcuts__group-label,
    [data-theme='sepia'] .kp-palette__group-label {
        font-family: var(--theme-font-display);
        font-style: italic;
    }

    [data-theme='sepia'] .kp-theme-menu__status,
    [data-theme='sepia'] .kp-palette__status,
    [data-theme='sepia'] .kp-combobox__status {
        color: var(--muted-foreground);
        font-size: 0.85rem;
    }

    /* ── The roots the rules above reach only by their parts ────────────── */

    [data-theme='sepia'] .kp-field {
        gap: 0.35rem;
    }

    [data-theme='sepia'] .kp-form {
        gap: 1.1rem;
    }

    [data-theme='sepia'] .kp-combobox,
    [data-theme='sepia'] .kp-datepicker,
    [data-theme='sepia'] .kp-colorpicker,
    [data-theme='sepia'] .kp-shortcuts,
    [data-theme='sepia'] .kp-tabs {
        border-radius: 0.5rem;
    }

    /* ── The confirmation dialog (Kenny, 2026-09-08): a real <dialog>,
       never a button relabelling itself. Focus lands on Cancel — the
       destructive choice is never the visual or focus default (DI10).
       The backdrop's one-shot fade is the demo's own `@keyframes
       confirm-in`, kept as a keyframe (not a transition) because a
       `::backdrop` needs `@starting-style` to transition on its own
       appearance, which the demo did not use. ─────────────────────────── */

    [data-theme='sepia'] .kp-confirm::backdrop {
        background: hsl(from var(--foreground) h s l / 0.38);
    }

    /* ── Reduced motion: everything resolves to rest [DI7] ──────────────── */

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='sepia'][data-kp-effects] [data-kp-reveal='headline'] {
            transition:
                color var(--kp-ink-duration) var(--fx-ease),
                filter var(--kp-ink-duration) var(--fx-ease),
                opacity var(--kp-ink-duration) var(--fx-ease);
        }

        [data-theme='sepia'][data-kp-effects] mark {
            transition: color var(--fx-duration) var(--fx-ease);
        }

        [data-theme='sepia'][data-kp-effects] [data-kp-reveal='rule']::after {
            transition: transform var(--kp-rule-duration) var(--kp-hand);
        }

        [data-theme='sepia'][data-kp-effects] .kp-card[data-kp-reveal='emphasis'] mark::after {
            transition: transform var(--kp-redact-duration) cubic-bezier(0.65, 0, 0.35, 1);
        }

        [data-theme='sepia'][data-kp-effects] .kp-card[data-kp-reveal='emphasis'] mark:nth-of-type(2)::after {
            transition-delay: var(--kp-redact-stagger);
        }

        [data-theme='sepia'][data-kp-effects] .kp-card[data-kp-reveal='emphasis'] mark:nth-of-type(3)::after {
            transition-delay: calc(2 * var(--kp-redact-stagger));
        }

        [data-theme='sepia'] .kp-footer a {
            transition: background-size var(--kp-underline-duration) var(--kp-hand);
        }

        [data-theme='sepia'] .kp-nav__menu {
            transition:
                opacity var(--fx-duration) var(--fx-ease),
                transform var(--fx-duration) var(--fx-ease);
        }

        [data-theme='sepia'] .kp-button,
        [data-theme='sepia'] .kp-icon-button {
            transition:
                background var(--fx-duration) var(--fx-ease),
                color var(--fx-duration) var(--fx-ease),
                border-color var(--fx-duration) var(--fx-ease);
        }

        [data-theme='sepia'] .kp-confirm[open]::backdrop {
            animation: kp-confirm-in 160ms var(--fx-ease);
        }
    }

    /* Every keyframe here has its row in TIMINGS (js/effects.js): a pure
       opacity fade, once, on the dialog's backdrop only. */
    @keyframes kp-confirm-in {
        0% {
            opacity: 0;
        }

        100% {
            opacity: 1;
        }
    }
    /* The band [M1, M4]: Kenny picked this theme's own version over the
       shared one on 2026-09-08 — a double gold rule above it, set in the italic display face. */
    [data-theme='sepia'] .kp-marquee {
        border-block-start: 3px double var(--primary);
        border-block-end: 1px solid var(--primary);
        font-family: var(--theme-font-display);
        font-style: italic;
        --kp-marquee: 56000ms;
    }

    /* The menu's caption [M3]: the same choice, for the line a consumer
       may put above a dropdown's items. */
    [data-theme='sepia'] .kp-nav__menu[data-kp-menu-label]::before {
        font-family: var(--theme-font-display);
        font-style: italic;
        text-transform: none;
        letter-spacing: 0;
        color: var(--primary);
    }
}

@layer kp.register {
    /* @kp-soft/themes — css/solstice-register.css
   The solstice register, 5.0.0 [S48, S49]: warm dark, no neon. The
   approved concept demo ("Low Sun", 2026-09-08) is the reference for
   every value here; its own header comment names the two measured
   sources (a display-serif recipe and a colour triad) and the hazards it
   refuses. `themes/solstice/anatomy.md` is the idea in words; this file
   is the idea in rules.

   The character is an hour of the day, not a filter: charcoal warmed by
   a trace of red, amber leading, rust following, a serif for display
   because warmth reads better with a little contrast in the letterforms,
   and the softest radius in the set because sharp corners fight the
   warmth. Nothing here is a bevel, a scanline or a grid — DI9's texture
   answer is "no texture, no register" (anatomy.md), and there is none.

   Colour discipline (DI9): nothing here names a colour; every value is
   var(--token) or a relative colour of one. Two knobs are new for this
   theme and shared by nothing else: --kp-cal-* (the calibration wipe)
   and --kp-redact-* (the dossier's redaction lift) — both one-shot,
   both monotonic, both inside the no-preference guard at the bottom of
   this file, so DI5 counts zero opposing changes for either. */

    [data-theme='solstice'] {
        /* The configuration surface [AR43], the demo's own values as
       defaults. */
        --kp-reveal-threshold: 0.6;
        --kp-reveal-stagger: 260ms;
        --kp-classified-delay: 1500ms;
        --kp-cal-duration: 520ms;
        --kp-cal-stagger: 110ms;
        --kp-rule-duration: 480ms;
        --kp-rule-delay: 260ms;
        --kp-redact-duration: 320ms;
        --kp-redact-stagger: 110ms;
        /* The reveals this theme performs [S45]: js/effects.js reads
       these and leaves a theme that declares none at rest. */
        --kp-reveal-headline: calibrate;
        --kp-reveal-emphasis: redact;
        --kp-reveal-rule: draw;
        /* No arrival: the demo's script wires the dropdown, the dossier
       and the wipe dialog only — nothing counts up on first paint
       (anatomy.md, "what it deliberately does not do"). */

        /* The calibration wipe's three bands, in the demo's own order:
       primary, accent, foreground — the same triad the swatches show. A
       relative colour is not needed here; each band names a token
       directly, which is the DI9-preferred form when a plain token IS
       the value. */
        --kp-cal-bands: linear-gradient(90deg, var(--primary) 0% 33.333%, var(--accent) 33.333% 66.666%, var(--foreground) 66.666% 100%);
        /* A translucent version of the ground itself, standing in for the
       demo's literal near-black shadow (DI9: no colour of the page's
       own is available here, so the page's own darkest surface is). */
        --kp-shadow-soft: hsl(from var(--background) h s l / 0.45);
        --kp-shadow-deep: hsl(from var(--background) h s l / 0.55);
        --kp-shadow-hair: hsl(from var(--background) h s l / 0.3);
    }

    /* ── Type ──────────────────────────────────────────────────────────── */

    [data-theme='solstice'] h1,
    [data-theme='solstice'] h2,
    [data-theme='solstice'] h3 {
        font-family: var(--theme-font-display);
        font-weight: 400;
    }

    [data-theme='solstice'] .microlabel {
        font-family: var(--theme-font-mono);
        font-weight: 600;
        font-size: 0.75rem;
        line-height: 1.2;
        letter-spacing: 0.1em;
        text-transform: uppercase;
        color: var(--muted-foreground);
    }

    /* ── The hooks [S45]: the headline, the mark, the rule, the divider ── */

    /* The headline: the calibration wipe. Three flat bands in the demo's
       triad sit over the text with mix-blend-mode: difference and slide
       away to their own right edge; the text itself is solid var(--fg)
       underneath from first paint, so a page without the module — or a
       theme answering quietly — simply shows the headline (anatomy: the
       hazard note on Moranta's blend mode, confined here to a one-shot
       decorative overlay, never to anything that must stay legible after
       it settles). */
    [data-theme='solstice'] [data-kp-reveal='headline'] {
        position: relative;
        display: inline-block;
        overflow: hidden;
        max-width: 100%;
    }

    [data-theme='solstice'] [data-kp-reveal='headline']::after {
        content: '';
        position: absolute;
        inset: 0;
        background-image: var(--kp-cal-bands);
        mix-blend-mode: difference;
        pointer-events: none;
        opacity: 0;
    }

    [data-theme='solstice'][data-kp-effects] [data-kp-reveal='headline']:not(.is-deciphered)::after {
        opacity: 1;
    }

    /* The rule: a plain scaleX(0→1) draw, left to right, when the heading
       enters the viewport — the demo's own mechanism, unornamented. */
    [data-theme='solstice'] [data-kp-reveal='rule']::after {
        content: '';
        display: block;
        block-size: 3px;
        margin-block-start: 0.6rem;
        background: var(--primary);
        transform-origin: left center;
        transform: scaleX(1);
    }

    [data-theme='solstice'][data-kp-effects] [data-kp-reveal='rule']:not(.is-in)::after {
        transform: scaleX(0);
    }

    /* The lede's mark: the base layer's warning plate already matches the
       demo (background var(--warning), color var(--warning-foreground));
       this only adds the demo's own corner and box-decoration. */
    [data-theme='solstice'] mark {
        border-radius: 3px;
        box-decoration-break: clone;
        -webkit-box-decoration-break: clone;
    }

    /* The divider: the demo's horizon seam, without the SVG the shared
       markup has no room for (an empty [data-kp-divider] div — S49
       finding, recorded in anatomy.md). A hairline plus one accent peak
       carries the idea: a low sun just above or just below the line. */
    [data-theme='solstice'] [data-kp-divider] {
        display: block;
        block-size: 28px;
        background:
            conic-gradient(from 225deg at 50% 100%, transparent 0deg 45deg, var(--accent) 45deg 90deg, transparent 90deg 135deg) center / 46px 22px
                no-repeat,
            linear-gradient(var(--border), var(--border)) center / 100% 1px no-repeat;
    }

    [data-theme='solstice'] [data-kp-divider='alt'] {
        background:
            conic-gradient(from 45deg at 50% 0%, transparent 0deg 45deg, var(--primary) 45deg 90deg, transparent 90deg 135deg) center / 46px 22px
                no-repeat,
            linear-gradient(var(--border), var(--border)) center / 100% 1px no-repeat;
    }

    /* ── The hero ─────────────────────────────────────────────────────── */

    [data-theme='solstice'] [data-kp-surface='hero'] {
        padding-block: clamp(3rem, 8vw, 6rem) clamp(2.5rem, 6vw, 4rem);
    }

    [data-theme='solstice'] [data-kp-surface='hero'] h1 {
        font-size: clamp(2.5rem, 10vw, 10.5rem);
        line-height: 0.91;
        letter-spacing: -0.04em;
    }

    /* The emphasised word inside the headline, small-caps rather than a
       second colour on the overlay's own band (anatomy: amber leads). */
    [data-theme='solstice'] [data-kp-surface='hero'] h1 em {
        font-style: normal;
        font-variant: all-small-caps;
        letter-spacing: -0.03em;
        color: var(--primary);
    }

    /* ── Nav: chrome, no bevel — a warm strip over the app ─────────────── */

    [data-theme='solstice'] .kp-nav-wrap {
        background: var(--card);
        border-bottom: 1px solid var(--border);
    }

    [data-theme='solstice'] .kp-nav {
        gap: 0.75rem 1.5rem;
    }

    [data-theme='solstice'] .kp-nav__brand {
        font-family: var(--theme-font-display);
        font-weight: 400;
        font-size: 1.35rem;
        letter-spacing: -0.01em;
    }

    [data-theme='solstice'] .kp-nav__link {
        color: var(--muted-foreground);
    }

    [data-theme='solstice'] .kp-nav__link:hover {
        color: var(--primary);
        background: none;
    }

    [data-theme='solstice'] .kp-nav__link--lang {
        text-transform: uppercase;
        letter-spacing: 0.06em;
    }

    /* The dropdown caret: one glyph, drawn by content, never a word
       [KT5] — the demo's own ⌄, not a borrowed arrow. */
    [data-theme='solstice'] .kp-nav__link[aria-haspopup]::after {
        content: ' ⌄';
        font-size: 0.7em;
        opacity: 0.8;
    }

    /* The dropdown (KT14): the demo's popover, opened and read before
       this register was called done. */
    [data-theme='solstice'] .kp-nav__menu {
        background: var(--popover);
        border: 1px solid var(--border-strong);
        border-radius: var(--radius);
        padding: 0.4rem;
        box-shadow: 0 12px 28px var(--kp-shadow-soft);
    }

    [data-theme='solstice'] .kp-nav__menu a {
        border-radius: calc(var(--radius) - 3px);
        padding: 0.5rem 0.6rem;
    }

    [data-theme='solstice'] .kp-nav__menu a:hover,
    [data-theme='solstice'] .kp-nav__menu a:focus-visible {
        background: var(--muted);
        color: var(--primary);
    }

    [data-theme='solstice'] .kp-nav__link--cta {
        background: var(--primary);
        color: var(--primary-foreground);
        border-radius: var(--radius);
        font-weight: 600;
    }

    [data-theme='solstice'] .kp-nav__link--cta:hover {
        background: hsl(from var(--primary) h s calc(l + 8%));
        color: var(--primary-foreground);
    }

    /* ── Buttons: no bevel, one soft accent highlight [S49, A7] ────────── */

    [data-theme='solstice'] .kp-button,
    [data-theme='solstice'] .kp-icon-button {
        border-radius: var(--radius);
        font-weight: 600;
    }

    [data-theme='solstice'] .kp-button--primary:hover {
        background: hsl(from var(--primary) h s calc(l + 8%));
    }

    [data-theme='solstice'] .kp-button--secondary:hover {
        background: hsl(from var(--secondary) h s calc(l + 4%));
    }

    [data-theme='solstice'] .kp-button--ghost {
        border-color: var(--border-strong);
    }

    [data-theme='solstice'] .kp-button--ghost:hover {
        background: var(--muted);
    }

    [data-theme='solstice'] .kp-button--destructive {
        background: transparent;
        color: var(--destructive);
        border-color: var(--destructive);
    }

    [data-theme='solstice'] .kp-button--destructive:hover {
        background: var(--destructive);
        color: var(--destructive-foreground);
    }

    /* The demo's answer to "mirror" [S49, A7]: a thin calibration-bar
       highlight riding the top and bottom inset edges, echoing the
       headline's fg/ink pair — this theme carries no gradients
       (anatomy.md), so this is a highlight, not a flip. */
    [data-theme='solstice'] .kp-button--mirror {
        box-shadow:
            inset 0 2px 0 hsl(from var(--foreground) h s l / 0.35),
            inset 0 -2px 0 hsl(from var(--primary-foreground) h s l / 0.25);
    }

    [data-theme='solstice'] .kp-button--primary.kp-button--mirror {
        box-shadow:
            inset 0 2px 0 hsl(from var(--foreground) h s l / 0.35),
            inset 0 -2px 0 hsl(from var(--primary-foreground) h s l / 0.25);
    }

    /* The mirror's own box-shadow would otherwise replace the two-channel
       ring outright (kp.register sits after kp.components in the cascade)
       — the exact fault retro's own comment records for its bevel [DI2,
       AR30 as amended 2026-09-07]. Composed in front of the highlight,
       never instead of it. */
    [data-theme='solstice'] .kp-button--mirror:focus-visible {
        box-shadow:
            0 0 0 var(--kp-focus-ring-inner-width, 2px) var(--focus-ring),
            inset 0 2px 0 hsl(from var(--foreground) h s l / 0.35),
            inset 0 -2px 0 hsl(from var(--primary-foreground) h s l / 0.25);
    }

    /* ── Fields: wells with the softest radius in the set ──────────────── */

    [data-theme='solstice'] .kp-field__label {
        font-weight: 600;
        font-size: 0.8125rem;
    }

    [data-theme='solstice'] .kp-field__required {
        font-weight: 600;
        font-size: 0.625rem;
        text-transform: uppercase;
        letter-spacing: 0.08em;
        color: var(--muted-foreground);
    }

    [data-theme='solstice'] .kp-field__input {
        border-radius: calc(var(--radius) - 2px);
        border-color: var(--border-strong);
    }

    [data-theme='solstice'] .kp-field__help {
        color: var(--muted-foreground);
    }

    [data-theme='solstice'] .kp-field__error {
        color: var(--destructive);
    }

    [data-theme='solstice'] .kp-fieldset {
        border: 1px solid var(--border);
        border-radius: var(--radius);
    }

    [data-theme='solstice'] .kp-form__summary {
        border: 1px solid var(--border-strong);
        border-radius: var(--radius);
        background: var(--card);
    }

    /* ── Cards, windows and containers ─────────────────────────────────── */

    [data-theme='solstice'] .kp-card {
        border-radius: var(--radius);
    }

    [data-theme='solstice'] .kp-card__title {
        font-family: var(--theme-font-display);
        font-weight: 400;
        font-size: 1.4rem;
    }

    /* The dossier: the stamp rides a slight rotation the way a printed
       tag would sit on a folder, and the redactions are the mark hook's
       own emphasis reveal, styled below. */
    [data-theme='solstice'] .kp-card[data-kp-label]::before {
        content: attr(data-kp-label);
        rotate: -2deg;
        background: var(--accent);
        color: var(--accent-foreground);
        font-weight: 700;
        font-size: 0.6875rem;
        letter-spacing: 0.1em;
        text-transform: uppercase;
        border-radius: 4px;
        padding: 0.35rem 0.6rem;
    }

    [data-theme='solstice'] .kp-card[data-kp-open]::before {
        content: attr(data-kp-label-open);
    }

    /* The redactions: three marks inside the dossier, covered by a bar in
       the theme's own boundary colour until the trigger opens the file,
       then lifted one after another, right to left — the demo's own
       clip-path direction. The ink underneath is present throughout
       (color kept, never removed): the bar is what hides it, not the
       text itself, which is how the demo's own `.kp-redaction` reads. */
    [data-theme='solstice'] .kp-card[data-kp-reveal='emphasis'] mark {
        position: relative;
        background: none;
        color: var(--card-foreground);
        padding: 0.05em 0.15em;
        font-weight: 400;
        border-radius: 3px;
    }

    [data-theme='solstice'] .kp-card[data-kp-reveal='emphasis'] mark::after {
        content: '';
        position: absolute;
        inset: 1px;
        background: var(--border-strong);
        border-radius: 3px;
        clip-path: inset(0 0 0 0);
        pointer-events: none;
    }

    [data-theme='solstice'][data-kp-effects] .kp-card[data-kp-reveal='emphasis'] mark:not(.is-cleared)::after {
        clip-path: inset(0 0 0 0);
    }

    [data-theme='solstice'] .kp-card[data-kp-reveal='emphasis'] mark.is-cleared::after {
        clip-path: inset(0 100% 0 0);
    }

    /* Windows: a plain popover panel with the demo's soft drop shadow —
       no bevel, no ramp; the softest radius in the set doing the work
       DI9's "no texture" leaves it to do. */
    [data-theme='solstice'] .kp-dialog,
    [data-theme='solstice'] .kp-popover,
    [data-theme='solstice'] .kp-menu,
    [data-theme='solstice'] .kp-toast,
    [data-theme='solstice'] .kp-tooltip,
    [data-theme='solstice'] .kp-confirm,
    [data-theme='solstice'] .kp-datepicker__panel,
    [data-theme='solstice'] .kp-combobox__list,
    [data-theme='solstice'] .kp-palette,
    [data-theme='solstice'] .kp-theme-menu {
        box-shadow: 0 24px 56px var(--kp-shadow-deep);
    }

    [data-theme='solstice'] .kp-toasts {
        gap: var(--kp-space-sm);
    }

    [data-theme='solstice'] .kp-dialog__title {
        font-family: var(--theme-font-display);
        font-weight: 400;
        font-size: 1.4rem;
    }

    [data-theme='solstice'] .kp-menu__item:hover {
        background: var(--muted);
        color: var(--primary);
    }

    [data-theme='solstice'] .kp-alert {
        border-radius: var(--radius);
    }

    [data-theme='solstice'] .kp-grid {
        gap: var(--kp-space-lg);
    }

    [data-theme='solstice'] .kp-grid__tile {
        border-radius: var(--radius);
    }

    [data-theme='solstice'] .kp-split {
        gap: 1px;
    }

    [data-theme='solstice'] .kp-split__pane {
        border-radius: var(--radius);
    }

    [data-theme='solstice'] .kp-split__separator {
        background: var(--border);
    }

    /* ── Footer ───────────────────────────────────────────────────────── */

    [data-theme='solstice'] .kp-footer {
        border-top: 1px solid var(--border);
    }

    [data-theme='solstice'] .kp-footer h4 {
        font-weight: 600;
        font-size: 0.8125rem;
        letter-spacing: 0.06em;
        text-transform: uppercase;
    }

    [data-theme='solstice'] .kp-footer a {
        color: var(--muted-foreground);
        text-decoration: none;
    }

    [data-theme='solstice'] .kp-footer a:hover {
        color: var(--primary);
    }

    /* ── Badges, tags, status ───────────────────────────────────────────── */

    [data-theme='solstice'] .kp-badge,
    [data-theme='solstice'] .kp-tag {
        border-radius: var(--radius);
        font-weight: 600;
    }

    [data-theme='solstice'] .kp-health {
        font-family: var(--theme-font-mono);
    }

    [data-theme='solstice'] .kp-health__dot {
        border-radius: 50%;
    }

    [data-theme='solstice'] .kp-skeleton {
        border-radius: var(--radius);
    }

    [data-theme='solstice'] .kp-progress {
        border-radius: var(--radius);
        background: var(--popover);
    }

    [data-theme='solstice'] .kp-progress__value {
        background: var(--primary);
    }

    [data-theme='solstice'] .kp-spinner {
        border-color: var(--border);
        border-top-color: var(--primary);
    }

    [data-theme='solstice'] .kp-empty {
        border: 1px dashed var(--border);
        border-radius: var(--radius);
    }

    [data-theme='solstice'] .kp-empty__title {
        font-family: var(--theme-font-display);
        font-weight: 400;
    }

    [data-theme='solstice'] .kp-error {
        color: var(--destructive);
    }

    /* ── Text shapes: identifiers in the mono face, unornamented ───────── */

    [data-theme='solstice'] .kp-id,
    [data-theme='solstice'] .kp-url,
    [data-theme='solstice'] .kp-numeric,
    [data-theme='solstice'] .kp-timestamp,
    [data-theme='solstice'] .kp-masked,
    [data-theme='solstice'] .kp-copyable,
    [data-theme='solstice'] .kp-truncate,
    [data-theme='solstice'] .kp-cell-break,
    [data-theme='solstice'] .kp-cell-truncate {
        font-family: var(--theme-font-mono);
    }

    [data-theme='solstice'] .kp-copyable__button {
        border-radius: calc(var(--radius) - 3px);
    }

    /* ── Data: table, datatable, diff, timeline, tree, reorder ─────────── */

    [data-theme='solstice'] .kp-table {
        border-collapse: separate;
        border-spacing: 0;
    }

    [data-theme='solstice'] .kp-table th {
        color: var(--muted-foreground);
        font-weight: 600;
        border-bottom: 1px solid var(--border-strong);
    }

    [data-theme='solstice'] .kp-table td {
        border-bottom: 1px solid var(--border);
    }

    [data-theme='solstice'] .kp-datatable {
        border-radius: var(--radius);
    }

    [data-theme='solstice'] .kp-datatable__sort[aria-sort] {
        color: var(--primary);
    }

    [data-theme='solstice'] .kp-diff {
        border-radius: var(--radius);
    }

    [data-theme='solstice'] .kp-diff__line {
        font-family: var(--theme-font-mono);
    }

    [data-theme='solstice'] .kp-timeline {
        border-inline-start: 2px solid var(--border);
    }

    [data-theme='solstice'] .kp-timeline__marker {
        background: var(--primary);
    }

    [data-theme='solstice'] .kp-timeline__when {
        color: var(--muted-foreground);
        font-family: var(--theme-font-mono);
    }

    [data-theme='solstice'] .kp-tree {
        font-family: var(--theme-font-mono);
    }

    [data-theme='solstice'] .kp-reorder {
        border-radius: var(--radius);
    }

    /* ── Navigation and steps ───────────────────────────────────────────── */

    [data-theme='solstice'] .kp-tab[aria-selected='true'] {
        color: var(--primary);
    }

    [data-theme='solstice'] .kp-tabs__list {
        border-bottom: 1px solid var(--border-strong);
    }

    [data-theme='solstice'] .kp-breadcrumb,
    [data-theme='solstice'] .kp-pagination {
        font-family: var(--theme-font-mono);
    }

    [data-theme='solstice'] .kp-pagination [aria-current] {
        background: var(--primary);
        color: var(--primary-foreground);
        border-radius: var(--radius);
    }

    [data-theme='solstice'] .kp-wizard {
        border-radius: var(--radius);
    }

    [data-theme='solstice'] .kp-wizard__steps {
        font-family: var(--theme-font-mono);
    }

    /* ── Pickers and palettes ────────────────────────────────────────────── */

    [data-theme='solstice'] .kp-datepicker__day[aria-selected='true'] {
        background: var(--primary);
        color: var(--primary-foreground);
        border-radius: var(--radius);
    }

    [data-theme='solstice'] .kp-datepicker__weekday,
    [data-theme='solstice'] .kp-datepicker__title {
        font-family: var(--theme-font-mono);
    }

    [data-theme='solstice'] .kp-colorpicker__swatch {
        border-radius: calc(var(--radius) - 3px);
    }

    [data-theme='solstice'] .kp-colorpicker__value {
        font-family: var(--theme-font-mono);
    }

    [data-theme='solstice'] .kp-shortcuts__row kbd {
        font-family: var(--theme-font-mono);
        border: 1px solid var(--border-strong);
        border-radius: calc(var(--radius) - 3px);
        background: var(--card);
        padding: 0 0.4em;
    }

    [data-theme='solstice'] .kp-shortcuts__group-label,
    [data-theme='solstice'] .kp-palette__group-label {
        font-family: var(--theme-font-display);
        font-weight: 400;
    }

    [data-theme='solstice'] .kp-theme-menu__status,
    [data-theme='solstice'] .kp-palette__status,
    [data-theme='solstice'] .kp-combobox__status {
        color: var(--muted-foreground);
        font-family: var(--theme-font-mono);
    }

    /* ── The roots the rules above reach only by their parts ───────────── */

    [data-theme='solstice'] .kp-field {
        gap: 0.4rem;
    }

    [data-theme='solstice'] .kp-form {
        gap: 1.1rem;
    }

    [data-theme='solstice'] .kp-combobox,
    [data-theme='solstice'] .kp-datepicker,
    [data-theme='solstice'] .kp-colorpicker,
    [data-theme='solstice'] .kp-shortcuts,
    [data-theme='solstice'] .kp-tabs {
        border-radius: var(--radius);
    }

    /* ── The demo's own pieces [S46] ─────────────────────────────────────── */

    /* The vertical margin note: static on narrow screens, rotated into
       the hero's left margin from 960px, the demo's own breakpoint. */
    [data-theme='solstice'] .kp-side-note {
        font-family: var(--theme-font-mono);
        font-size: 0.75rem;
        letter-spacing: 0.14em;
        text-transform: uppercase;
        color: var(--muted-foreground);
    }

    @media (min-width: 60rem) {
        [data-theme='solstice'] .kp-side-note {
            position: absolute;
            inset-block-start: 6rem;
            inset-inline-start: clamp(0.5rem, 2vw, 1.5rem);
            writing-mode: vertical-rl;
            transform: rotate(180deg);
            max-width: none;
        }
    }

    /* Laurels: a bold lead-in and a rust hairline either side, the way a
       printed spec sheet sets its own tick marks. */
    [data-theme='solstice'] .kp-laurels {
        text-transform: uppercase;
        letter-spacing: 0.12em;
        font-size: 0.6875rem;
        color: var(--muted-foreground);
    }

    [data-theme='solstice'] .kp-laurels li {
        position: relative;
        padding-inline: 0.85rem;
    }

    [data-theme='solstice'] .kp-laurels li::before,
    [data-theme='solstice'] .kp-laurels li::after {
        content: '';
        position: absolute;
        inset-block: 0.15rem;
        inline-size: 1px;
        background: var(--accent);
    }

    [data-theme='solstice'] .kp-laurels li::before {
        inset-inline-start: 0;
    }

    [data-theme='solstice'] .kp-laurels li::after {
        inset-inline-end: 0;
    }

    [data-theme='solstice'] .kp-laurels b {
        color: var(--foreground);
        font-weight: 700;
    }

    /* The platforms line: a rust tick before every name. */
    [data-theme='solstice'] .kp-platforms {
        font-weight: 500;
        color: var(--muted-foreground);
    }

    [data-theme='solstice'] .kp-platforms span {
        color: var(--foreground);
        font-weight: 600;
    }

    /* The spec sheet: the plain card the demo shows — no ramp, no chrome. */
    [data-theme='solstice'] .kp-spec {
        border-radius: var(--radius);
    }

    [data-theme='solstice'] .kp-spec__swatch {
        border-radius: 5px;
    }

    [data-theme='solstice'] .kp-spec__font[data-font='display'] {
        font-family: var(--theme-font-display);
        font-weight: 400;
    }

    /* ── Motion, guarded [DI7] ────────────────────────────────────────── */

    /* Every animation of this register lives here, inside the
       no-preference guard, so a reader who asked for reduced motion never
       receives one: the rest states above (headline solid, rule drawn,
       redaction covered) are what they get. The durations are literal
       because check-motion.mjs computes DI5's rate from them; the
       matching --kp-* knobs above are what a consumer can retune
       [AR43]. */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='solstice'] [data-kp-reveal='headline'].is-calibrating::after {
            animation: kp-cal-slide calc(var(--kp-cal-duration) + 2 * var(--kp-cal-stagger)) var(--fx-ease) 1 forwards;
        }

        [data-theme='solstice'] [data-kp-reveal='rule'].is-in::after {
            animation: kp-cal-rule var(--kp-rule-duration) var(--fx-ease) var(--kp-rule-delay) 1 both;
        }

        [data-theme='solstice'] .kp-card[data-kp-reveal='emphasis'] mark.is-cleared::after {
            animation: kp-cal-redact var(--kp-redact-duration) var(--fx-ease) 1 both;
        }

        [data-theme='solstice'] .kp-card[data-kp-reveal='emphasis'] mark.is-cleared:nth-of-type(2)::after {
            animation-delay: var(--kp-redact-stagger);
        }

        [data-theme='solstice'] .kp-card[data-kp-reveal='emphasis'] mark.is-cleared:nth-of-type(3)::after {
            animation-delay: calc(2 * var(--kp-redact-stagger));
        }
    }

    /* ── Motion [DI5, DI7] ────────────────────────────────────────────── */

    /* One monotonic wipe, never opposed: the three bands recede together
       on a single timeline (js/effects.js adds is-calibrating for the
       whole 740ms span; the demo's own three independently-staggered
       transforms are approximated here as one clip-path sweep, left to
       right, at the theme's own ease — the same triad, the same total
       time, a different mechanism [S49 finding, recorded in
       anatomy.md]). */
    @keyframes kp-cal-slide {
        0% {
            clip-path: inset(0 0 0 0);
        }

        100% {
            clip-path: inset(0 0 0 100%);
        }
    }

    /* The rule: scaleX(0→1), one direction, one step. */
    @keyframes kp-cal-rule {
        from {
            transform: scaleX(0);
        }

        to {
            transform: scaleX(1);
        }
    }

    /* The redaction: the bar lifts right to left, the demo's own
       direction (`clip-path: inset(0 100% 0 0)` at rest-cleared). */
    @keyframes kp-cal-redact {
        from {
            clip-path: inset(0 0 0 0);
        }

        to {
            clip-path: inset(0 100% 0 0);
        }
    }
    /* The band [M1, M4]: Kenny picked this theme's own version over the
       shared one on 2026-09-08 — amber between two translucent amber rules. */
    [data-theme='solstice'] .kp-marquee {
        color: var(--primary);
        border-block: 1px solid color-mix(in srgb, var(--primary) 35%, transparent);
        font-family: var(--theme-font-mono);
        --kp-marquee: 44000ms;
    }

    /* The menu's caption [M3]: the same choice, for the line a consumer
       may put above a dropdown's items. */
    [data-theme='solstice'] .kp-nav__menu[data-kp-menu-label]::before {
        color: var(--primary);
        font-family: var(--theme-font-mono);
        border-block-end: 1px solid color-mix(in srgb, var(--primary) 40%, transparent);
    }
}

@layer kp.register {
    /* @kp-soft/themes — css/mono-register.css
   The mono register, 5.0.0 [S48, LIFT_PLAN row 6]: a well-set document,
   not a design. Scoped to [data-theme='mono'] and inert elsewhere;
   opt-in, imported after themes.css. The approved concept demo ("Paper
   Trail", 2026-09-08) is the reference for every value here, and
   docs/RESEARCH_2026-09.md "20. mono" is where each mechanism was
   measured: rauno.me's overhanging hairline that fades at both ends
   (both dividers and the drawn rule under a heading), rauno.me's
   mask-image fade under chrome — adapted from opacity to mask-position, a
   hard-edge sweep rather than a cross-fade, so nothing ever flashes — for
   the headline arrival and the three dossier redactions, and rauno.me's
   inverting link (mix-blend-mode: difference) for the nav links and the
   ghost button, an instant state change with no transition, never
   touching the two-channel focus ring.

   What this file does, in order: the knobs; the ring, in the demo's
   order; the type — one face for text, one for headings, numerals,
   labels and code; the hooks of S45 — the headline that sweeps into view
   once, the mark as a static highlight (a dossier's marks are redaction
   bars that sweep clear on a trigger, one after another), the hairline
   that draws itself under a heading, the fading hairline as divider; the
   strip as navbar with the inverting hover; the buttons, left to the
   package's own lightness derivation (AR12) — this theme adds no colour
   step of its own; the wells; the dossier with its stamp and its bars;
   the panels; and one answer per component root (TH124). The reveals
   have their rest state here and their motion in js/effects.js; without
   the script every one of them stands at rest, plain and legible.

   Colour discipline (DI9): nothing here names a colour. Ink over paper,
   nowhere else, no accent hue: DI4's second channel is lightness,
   pattern and label, not a second colour. No shadow but the nav
   dropdown's, which the demo draws and nothing else does — a document
   does not cast shadows, a menu floating over one does. No texture at
   all (css/_rules.css, TH72): the absence is the register.

   The only loops in this file: none. Every reveal here runs once, on
   load or on the dossier's own trigger, and stops. */

    [data-theme='mono'] {
        /* The configuration surface [AR43], the demo's values as defaults. */
        --kp-reveal-threshold: 0.4;
        --kp-redact-stagger: 400ms;
        --kp-wipe-headline: 600ms;
        --kp-wipe-redact: 400ms;
        --kp-rule: 400ms;
        /* The reveals this theme performs [S45]: js/effects.js reads these
           and leaves a theme that declares none at rest. */
        --kp-reveal-headline: wipe;
        --kp-reveal-emphasis: classified;
        --kp-reveal-rule: draw;
        /* The one mechanism, in both directions [S48, A2]: a 200%-wide,
           hard-edge, two-stop mask swept by mask-position. `-in` reveals
           content that was hidden (the headline); `-out` hides a bar that
           was covering it (a redaction). Neither stop's own colour matters
           to the mask — only which half is opaque — so both read a single
           token and stay DI9-clean. */
        --kp-mask-in: linear-gradient(90deg, transparent 50%, var(--foreground) 50%);
        --kp-mask-out: linear-gradient(90deg, var(--foreground) 50%, transparent 50%);
        /* The overhanging, fading hairline [S48, A1]: both dividers and the
           rule drawn under a heading are this one gradient, scoped to
           whichever boundary token the demo used for that hairline. */
        --kp-hairline: linear-gradient(to right, transparent, var(--border-strong) 10%, var(--border-strong) 90%, transparent);
        --kp-hairline-strong: linear-gradient(to right, transparent, var(--foreground) 10%, var(--foreground) 90%, transparent);
        --kp-rule-fade: linear-gradient(to right, var(--border-strong) 0, var(--border-strong) 60%, transparent 92%);
        /* The nav dropdown's shadow, the one shadow in the theme [S48, A3]:
           the demo's own tinted-black shadow is the ink token at 12%. */
        --kp-menu-shadow: 0 4px 12px hsl(from var(--foreground) h s l / 0.12);
    }

    /* ── The ring, in the demo's order [S49, A5 of 2026-09-08] ────────────
       The base layer puts the contrast colour outside and the ring colour
       against the element; this theme's approved demo does it the other
       way round — a 2px paper ring against the control, a 4px ink ring
       outside it — and DI2's promise holds either way: two channels, one
       of which always clears 3:1 on the surface behind it. Restated here
       so a control that composes its own shadow stack still wins. */
    [data-theme='mono'] :focus-visible {
        outline-color: var(--focus-ring);
        box-shadow: 0 0 0 var(--kp-focus-ring-inner-width, 2px) var(--focus-ring-contrast);
    }

    [data-theme='mono'] ::selection {
        background: var(--primary);
        color: var(--primary-foreground);
    }

    /* ── Type ──────────────────────────────────────────────────────────── */

    [data-theme='mono'] h1,
    [data-theme='mono'] h2,
    [data-theme='mono'] h3 {
        font-family: var(--theme-font-display);
        font-weight: 600;
        letter-spacing: -0.01em;
    }

    [data-theme='mono'] [data-kp-surface] h1 {
        font-size: var(--kp-text-display);
        line-height: 1.1;
        margin-block: 0 0.5em;
        overflow-wrap: anywhere;
    }

    /* Microlabels: the demo's small uppercase caption, in the mono face. */
    [data-theme='mono'] .microlabel {
        font-family: var(--theme-font-mono);
        font-size: 0.6875rem;
        letter-spacing: 0.14em;
        text-transform: uppercase;
        color: var(--muted-foreground);
    }

    /* ── The hooks [S45]: the headline, the mark, the rule, the divider ─── */

    /* The headline: the text stays whole — never split into words or
       glyphs — and a hard-edge mask sweeps across it once, left to right.
       At rest (no script) it is plain text, no mask; armed and not yet
       revealed it is hidden behind the mask's own starting position. */
    [data-theme='mono'][data-kp-effects] [data-kp-reveal='headline']:not(.is-deciphered) {
        mask-image: var(--kp-mask-in);
        -webkit-mask-image: var(--kp-mask-in);
        mask-size: 200% 100%;
        -webkit-mask-size: 200% 100%;
        mask-position: 0% 0%;
        -webkit-mask-position: 0% 0%;
    }

    /* The mark: a static highlight, the only emphasis a loose word gets —
       this theme has no clearing effect for a mark outside the dossier
       (the lede's two marked phrases sit on the page already lit). */
    [data-theme='mono'] mark {
        background: var(--accent);
        color: var(--accent-foreground);
        padding: 0 0.2em;
        border-radius: 2px;
    }

    /* A dossier's marks are redaction bars instead: the mark's own text
       renders (colour transparent while covered, so it still occupies its
       own width and a screen reader still finds it), and an ink bar sits
       over it, masked by the same mechanism as the headline, the other
       direction — opaque first, so at rest (armed, not yet cleared) the
       bar fully covers. Without the script the dossier is never armed, so
       the bar stays off and the words are plain [S49, "without the script
       every one of them stands at rest"]. */
    [data-theme='mono'] .kp-card[data-kp-reveal='emphasis'] mark {
        position: relative;
        background: none;
        color: var(--card-foreground);
        padding: 0;
        border-radius: 0;
    }

    [data-theme='mono'] .kp-card[data-kp-reveal='emphasis'] mark::after {
        content: '';
        position: absolute;
        inset: -0.05em -0.15em;
        background: var(--foreground);
        border-radius: 2px;
        pointer-events: none;
        mask-image: var(--kp-mask-out);
        -webkit-mask-image: var(--kp-mask-out);
        mask-size: 200% 100%;
        -webkit-mask-size: 200% 100%;
        mask-position: 100% 0%;
        -webkit-mask-position: 100% 0%;
    }

    [data-theme='mono'][data-kp-effects] .kp-card[data-kp-reveal='emphasis'] mark:not(.is-cleared) {
        color: transparent;
    }

    [data-theme='mono'][data-kp-effects] .kp-card[data-kp-reveal='emphasis'] mark:not(.is-cleared)::after {
        mask-position: 0% 0%;
        -webkit-mask-position: 0% 0%;
    }

    /* The rule: the fading hairline, drawn left to right, once, when its
       heading enters the viewport — the same mechanism as the divider
       below, animated. */
    [data-theme='mono'] [data-kp-reveal='rule']::after {
        content: '';
        display: block;
        block-size: 1px;
        margin-block-start: 0.5rem;
        background: var(--kp-rule-fade);
        transform: scaleX(1);
        transform-origin: left center;
    }

    [data-theme='mono'][data-kp-effects] [data-kp-reveal='rule']:not(.is-in)::after {
        transform: scaleX(0);
    }

    /* The divider: rauno.me's overhanging hairline that fades at both
       ends rather than stopping hard — a line the page's own edges
       interrupt, not a rule drawn to fit its box. Static; nothing here
       animates. */
    [data-theme='mono'] [data-kp-divider] {
        display: block;
        block-size: 1px;
        background: var(--kp-hairline);
    }

    [data-theme='mono'] [data-kp-divider='alt'] {
        background: var(--kp-hairline-strong);
    }

    /* ── The hero: paper, nothing added ───────────────────────────────── */

    [data-theme='mono'] [data-kp-surface='hero'] {
        position: relative;
        padding-block: 2.2rem 3.2rem;
    }

    [data-theme='mono'] [data-kp-surface='hero'] [data-kp-hero-grid] {
        grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
        gap: 2.5rem;
        align-items: start;
    }

    @container (max-width: 46rem) {
        [data-theme='mono'] [data-kp-surface='hero'] [data-kp-hero-grid] {
            grid-template-columns: 1fr;
        }
    }

    /* ── The navbar: a strip on paper, the inverting hover ────────────── */

    [data-theme='mono'] .kp-nav-wrap {
        background: var(--card);
        border-bottom: 1px solid var(--border);
    }

    [data-theme='mono'] .kp-nav {
        background: var(--card);
        padding-block: 0.9rem;
        position: relative;
        z-index: var(--kp-z-nav, 30);
    }

    [data-theme='mono'] .kp-nav__brand {
        font-family: var(--theme-font-mono);
        font-weight: 600;
        letter-spacing: -0.02em;
        font-size: 1.05rem;
        color: var(--foreground);
        text-decoration: none;
    }

    [data-theme='mono'] .kp-nav__links {
        gap: 1rem;
        align-items: center;
    }

    /* rauno.me's inverting link: a fill sits behind the label with
       mix-blend-mode: difference and grows on hover/focus. An instant
       state change — no transition — and it never touches the ring. */
    [data-theme='mono'] .kp-nav__link {
        position: relative;
        display: inline-block;
        padding: 0.3rem 0.55rem;
        font-size: 0.875rem;
        color: var(--foreground);
        border-radius: var(--radius);
        text-decoration: none;
        z-index: 0;
    }

    [data-theme='mono'] .kp-nav__link::before {
        content: '';
        position: absolute;
        inset: 0;
        background: var(--foreground);
        mix-blend-mode: difference;
        opacity: 0;
        z-index: -1;
        border-radius: inherit;
    }

    [data-theme='mono'] .kp-nav__link:hover::before,
    [data-theme='mono'] .kp-nav__link:focus-visible::before,
    [data-theme='mono'] .kp-nav__links > li:focus-within > .kp-nav__link::before {
        opacity: 1;
    }

    [data-theme='mono'] .kp-nav__link--cta {
        border: 1px solid var(--border-strong);
    }

    /* The dropdown, styled in the theme's own language (KT14): the one
       shadow in the register — a menu floats, a document does not. */
    [data-theme='mono'] .kp-nav__menu {
        background: var(--card);
        border: 1px solid var(--border-strong);
        border-radius: var(--radius);
        box-shadow: var(--kp-menu-shadow);
        padding: 0.25rem;
        min-width: 10rem;
    }

    [data-theme='mono'] .kp-nav__menu a {
        display: block;
        padding: 0.35rem 0.6rem;
        font-size: 0.8125rem;
        color: var(--foreground);
        text-decoration: none;
        border-radius: calc(var(--radius) * 0.7);
    }

    [data-theme='mono'] .kp-nav__menu a:hover,
    [data-theme='mono'] .kp-nav__menu a:focus-visible {
        background: var(--muted);
    }

    /* ── Buttons: left to the package's own derivation (AR12) ─────────── */

    /* The demo shows no hover of its own on a plain or primary button —
       lightness alone carries the state (DI3), which is the default the
       package already derives; this theme adds no colour step on top of
       it. The ghost is the one button with a mechanism of its own. */
    [data-theme='mono'] .kp-button {
        font-family: var(--theme-font-body);
        font-weight: 500;
        border-radius: var(--radius);
    }

    [data-theme='mono'] .kp-button--mirror {
        letter-spacing: 0.01em;
    }

    [data-theme='mono'] .kp-button--ghost {
        position: relative;
        overflow: hidden;
        z-index: 0;
    }

    [data-theme='mono'] .kp-button--ghost::before {
        content: '';
        position: absolute;
        inset: 0;
        background: var(--foreground);
        mix-blend-mode: difference;
        opacity: 0;
        z-index: -1;
        border-radius: inherit;
    }

    [data-theme='mono'] .kp-button--ghost:hover::before,
    [data-theme='mono'] .kp-button--ghost:focus-visible::before {
        opacity: 1;
    }

    [data-theme='mono'] .kp-icon-button {
        border-radius: var(--radius);
    }

    /* ── Fields: white wells, a hairline border ───────────────────────── */

    [data-theme='mono'] .kp-field__label {
        font-size: 0.8125rem;
        font-weight: 500;
    }

    [data-theme='mono'] .kp-field__required {
        color: var(--muted-foreground);
        font-weight: 400;
    }

    [data-theme='mono'] .kp-field__input,
    [data-theme='mono'] .kp-datatable__search,
    [data-theme='mono'] .kp-combobox__input,
    [data-theme='mono'] .kp-palette__input {
        background: var(--card);
        color: var(--card-foreground);
        border: 1px solid var(--border-strong);
        border-radius: var(--radius);
    }

    [data-theme='mono'] .kp-field__help {
        font-size: 0.75rem;
        color: var(--muted-foreground);
    }

    [data-theme='mono'] .kp-field--invalid .kp-field__input {
        border-color: var(--destructive);
    }

    [data-theme='mono'] .kp-field__error {
        color: var(--destructive);
    }

    [data-theme='mono'] .kp-field__check {
        accent-color: var(--kp-control-accent, var(--foreground));
    }

    [data-theme='mono'] .kp-fieldset {
        border: 1px solid var(--border-strong);
        border-radius: var(--radius);
    }

    [data-theme='mono'] .kp-form__summary {
        background: var(--card);
        border: 1px solid var(--border-strong);
        border-radius: var(--radius);
    }

    /* ── Cards and the dossier ─────────────────────────────────────────── */

    [data-theme='mono'] .kp-card {
        background: var(--card);
        border: 1px solid var(--border-strong);
        border-radius: var(--radius);
        box-shadow: none;
    }

    [data-theme='mono'] .kp-card__title {
        font-size: 1rem;
    }

    [data-theme='mono'] .kp-card[data-kp-reveal='emphasis'] {
        position: relative;
    }

    /* The stamp: a bordered pill in the mono face, the way a form stamps
       a status word rather than colouring it. The demo's own stamp never
       changes when the file opens, so this theme declares no
       [data-kp-open] override — Classified stays Classified. */
    [data-theme='mono'] .kp-card[data-kp-label]::before {
        content: attr(data-kp-label);
        font-family: var(--theme-font-mono);
        font-size: 0.6875rem;
        letter-spacing: 0.1em;
        text-transform: uppercase;
        color: var(--muted-foreground);
        border: 1px solid var(--border-strong);
        border-radius: 999px;
        padding: 0.2em 0.7em;
    }

    /* ── Panels: the nav dropdown's family, floating over the page ────── */

    [data-theme='mono'] .kp-dialog,
    [data-theme='mono'] .kp-popover,
    [data-theme='mono'] .kp-menu,
    [data-theme='mono'] .kp-toast,
    [data-theme='mono'] .kp-tooltip,
    [data-theme='mono'] .kp-confirm,
    [data-theme='mono'] .kp-datepicker__panel,
    [data-theme='mono'] .kp-combobox__list,
    [data-theme='mono'] .kp-palette,
    [data-theme='mono'] .kp-theme-menu {
        background: var(--popover);
        color: var(--popover-foreground);
        border: 1px solid var(--border-strong);
        border-radius: var(--radius);
    }

    /* Floating over content earns the shadow the dossier's own card does
       not carry (a menu floats, a document does not); the dialog is the
       demo's own exception — it is modal, not a menu, and the demo draws
       it flat, so it is listed separately below without one. */
    [data-theme='mono'] .kp-popover,
    [data-theme='mono'] .kp-menu,
    [data-theme='mono'] .kp-toast,
    [data-theme='mono'] .kp-tooltip,
    [data-theme='mono'] .kp-confirm,
    [data-theme='mono'] .kp-datepicker__panel,
    [data-theme='mono'] .kp-combobox__list,
    [data-theme='mono'] .kp-palette,
    [data-theme='mono'] .kp-theme-menu {
        box-shadow: var(--kp-menu-shadow);
    }

    [data-theme='mono'] .kp-dialog {
        box-shadow: none;
    }

    [data-theme='mono'] .kp-dialog__title {
        font-size: 1.1rem;
    }

    [data-theme='mono'] .kp-menu__item:hover,
    [data-theme='mono'] .kp-menu__item:focus-visible {
        background: var(--muted);
    }

    [data-theme='mono'] .kp-toasts {
        gap: 0.6rem;
    }

    [data-theme='mono'] .kp-alert {
        background: var(--card);
        border: 1px solid var(--border-strong);
        border-radius: var(--radius);
    }

    [data-theme='mono'] .kp-grid__tile,
    [data-theme='mono'] .kp-split__pane {
        background: var(--card);
        border: 1px solid var(--border-strong);
        border-radius: var(--radius);
    }

    [data-theme='mono'] .kp-grid {
        gap: 1.25rem;
    }

    [data-theme='mono'] .kp-split {
        gap: 1px;
    }

    [data-theme='mono'] .kp-split__separator {
        background: var(--border);
    }

    /* ── The footer ─────────────────────────────────────────────────────── */

    [data-theme='mono'] .kp-footer {
        border-top: 1px solid var(--border);
    }

    [data-theme='mono'] .kp-footer h4 {
        font-size: 0.875rem;
    }

    [data-theme='mono'] .kp-footer a {
        font-size: 0.8125rem;
        color: var(--muted-foreground);
        text-decoration: none;
    }

    [data-theme='mono'] .kp-footer a:hover,
    [data-theme='mono'] .kp-footer a:focus-visible {
        color: var(--foreground);
    }

    [data-theme='mono'] .kp-footer .microlabel {
        border-top: 1px solid var(--border);
        padding-top: 1rem;
        display: block;
    }

    /* ── Badges, tags, status ──────────────────────────────────────────── */

    [data-theme='mono'] .kp-badge,
    [data-theme='mono'] .kp-tag {
        border-radius: var(--radius);
        font-weight: 500;
    }

    [data-theme='mono'] .kp-health {
        font-size: 0.8125rem;
    }

    [data-theme='mono'] .kp-health__dot {
        border-radius: 50%;
    }

    [data-theme='mono'] .kp-skeleton {
        background: var(--muted);
        border-radius: var(--radius);
    }

    [data-theme='mono'] .kp-progress {
        background: var(--muted);
        border-radius: var(--radius);
    }

    [data-theme='mono'] .kp-progress__value {
        background: var(--foreground);
    }

    [data-theme='mono'] .kp-spinner {
        border-color: var(--border);
        border-top-color: var(--foreground);
    }

    [data-theme='mono'] .kp-empty {
        border: 1px dashed var(--border-strong);
        border-radius: var(--radius);
    }

    [data-theme='mono'] .kp-error {
        color: var(--destructive);
    }

    /* ── Text shapes ──────────────────────────────────────────────────── */

    [data-theme='mono'] .kp-id,
    [data-theme='mono'] .kp-url,
    [data-theme='mono'] .kp-numeric,
    [data-theme='mono'] .kp-timestamp,
    [data-theme='mono'] .kp-masked,
    [data-theme='mono'] .kp-copyable,
    [data-theme='mono'] .kp-truncate,
    [data-theme='mono'] .kp-cell-break,
    [data-theme='mono'] .kp-cell-truncate {
        font-family: var(--theme-font-mono);
    }

    [data-theme='mono'] .kp-timestamp,
    [data-theme='mono'] .kp-id {
        color: var(--muted-foreground);
    }

    [data-theme='mono'] .kp-copyable__button {
        border-radius: calc(var(--radius) * 0.7);
    }

    /* ── Data ─────────────────────────────────────────────────────────── */

    [data-theme='mono'] .kp-table {
        border-collapse: separate;
        border-spacing: 0;
    }

    [data-theme='mono'] .kp-table th {
        font-family: var(--theme-font-mono);
        font-size: 0.75rem;
        letter-spacing: 0.06em;
        text-transform: uppercase;
        color: var(--muted-foreground);
        font-weight: 500;
    }

    [data-theme='mono'] .kp-table tbody tr:hover {
        background: var(--muted);
    }

    [data-theme='mono'] .kp-datatable {
        border: 1px solid var(--border-strong);
        border-radius: var(--radius);
    }

    [data-theme='mono'] .kp-datatable__status,
    [data-theme='mono'] .kp-datatable__page {
        font-family: var(--theme-font-mono);
        font-size: 0.75rem;
        color: var(--muted-foreground);
    }

    [data-theme='mono'] .kp-diff {
        border: 1px solid var(--border-strong);
        border-radius: var(--radius);
    }

    [data-theme='mono'] .kp-diff__line {
        font-family: var(--theme-font-mono);
    }

    [data-theme='mono'] .kp-timeline {
        border-inline-start: 1px solid var(--border-strong);
    }

    [data-theme='mono'] .kp-timeline__marker {
        background: var(--foreground);
        border-radius: 50%;
    }

    [data-theme='mono'] .kp-timeline__when {
        font-family: var(--theme-font-mono);
        color: var(--muted-foreground);
    }

    [data-theme='mono'] .kp-tree {
        font-family: var(--theme-font-mono);
        font-size: 0.875rem;
    }

    [data-theme='mono'] .kp-reorder {
        border: 1px solid var(--border-strong);
        border-radius: var(--radius);
    }

    /* ── Navigation and steps ─────────────────────────────────────────── */

    [data-theme='mono'] .kp-tab {
        border-radius: var(--radius);
    }

    [data-theme='mono'] .kp-tab[aria-selected='true'] {
        background: var(--muted);
        color: var(--foreground);
        font-weight: 500;
    }

    [data-theme='mono'] .kp-tabs__list {
        border-bottom: 1px solid var(--border);
    }

    [data-theme='mono'] .kp-breadcrumb,
    [data-theme='mono'] .kp-pagination {
        font-size: 0.875rem;
    }

    [data-theme='mono'] .kp-pagination a[aria-current],
    [data-theme='mono'] .kp-pagination [aria-current] {
        background: var(--foreground);
        color: var(--background);
        border-radius: var(--radius);
    }

    [data-theme='mono'] .kp-wizard {
        border: 1px solid var(--border-strong);
        border-radius: var(--radius);
        background: var(--card);
    }

    [data-theme='mono'] .kp-wizard__steps {
        font-family: var(--theme-font-mono);
        font-size: 0.8125rem;
    }

    /* ── Pickers and palettes ─────────────────────────────────────────── */

    [data-theme='mono'] .kp-datepicker__day[aria-selected='true'] {
        background: var(--foreground);
        color: var(--background);
        border-radius: var(--radius);
    }

    [data-theme='mono'] .kp-datepicker__weekday,
    [data-theme='mono'] .kp-datepicker__title {
        font-family: var(--theme-font-mono);
        font-size: 0.75rem;
    }

    [data-theme='mono'] .kp-colorpicker__swatch {
        border: 1px solid var(--border-strong);
        border-radius: calc(var(--radius) * 0.7);
    }

    [data-theme='mono'] .kp-colorpicker__value {
        font-family: var(--theme-font-mono);
    }

    [data-theme='mono'] .kp-shortcuts__row kbd {
        font-family: var(--theme-font-mono);
        border: 1px solid var(--border-strong);
        border-radius: calc(var(--radius) * 0.7);
        background: var(--card);
        display: inline-block;
        padding: 0 0.4em;
    }

    [data-theme='mono'] .kp-shortcuts__group-label,
    [data-theme='mono'] .kp-palette__group-label {
        font-family: var(--theme-font-mono);
        letter-spacing: 0.06em;
        text-transform: uppercase;
        color: var(--muted-foreground);
    }

    [data-theme='mono'] .kp-theme-menu__status,
    [data-theme='mono'] .kp-palette__status,
    [data-theme='mono'] .kp-combobox__status {
        font-family: var(--theme-font-mono);
        font-size: 0.75rem;
        color: var(--muted-foreground);
    }

    /* ── The roots the rules above reach only by their parts ──────────── */

    [data-theme='mono'] .kp-field {
        gap: 0.25rem;
    }

    [data-theme='mono'] .kp-form {
        gap: 1rem;
    }

    [data-theme='mono'] .kp-combobox,
    [data-theme='mono'] .kp-datepicker,
    [data-theme='mono'] .kp-colorpicker,
    [data-theme='mono'] .kp-shortcuts,
    [data-theme='mono'] .kp-tabs {
        border-radius: var(--radius);
    }

    /* ── The scrollbar joins the theme ────────────────────────────────── */

    [data-theme='mono'] {
        scrollbar-color: var(--border-strong) var(--background);
    }

    /* ── The demo's own pieces [S46] ──────────────────────────────────── */

    [data-theme='mono'] .kp-side-note {
        font-family: var(--theme-font-mono);
        font-size: 0.6875rem;
        letter-spacing: 0.14em;
        color: var(--muted-foreground);
        writing-mode: vertical-rl;
        text-orientation: mixed;
        position: absolute;
        inset-inline-start: -1.75rem;
        inset-block-start: 0;
    }

    @container (max-width: 46rem) {
        [data-theme='mono'] .kp-side-note {
            writing-mode: horizontal-tb;
            position: static;
            display: block;
            margin-block-end: 1rem;
        }
    }

    [data-theme='mono'] .kp-laurels {
        gap: 1rem;
        font-size: 0.8125rem;
        color: var(--muted-foreground);
    }

    [data-theme='mono'] .kp-laurels b {
        display: block;
        font-family: var(--theme-font-mono);
        color: var(--foreground);
        font-size: 0.9375rem;
    }

    [data-theme='mono'] .kp-lede {
        max-width: 42rem;
        color: var(--foreground);
    }

    [data-theme='mono'] .kp-platforms {
        gap: 1rem;
        font-family: var(--theme-font-mono);
        font-size: 0.75rem;
        color: var(--muted-foreground);
    }

    /* The spec sheet: a bordered card, no shadow — the dossier's own
       language, not the dropdown's. */
    [data-theme='mono'] .kp-spec {
        border: 1px solid var(--border-strong);
        border-radius: var(--radius);
        background: var(--card);
        padding: 1rem;
    }

    [data-theme='mono'] .kp-spec dt {
        font-family: var(--theme-font-mono);
        font-size: 0.6875rem;
        text-transform: uppercase;
        letter-spacing: 0.08em;
        color: var(--muted-foreground);
    }

    [data-theme='mono'] .kp-spec dd {
        font-family: var(--theme-font-mono);
        font-size: 0.8125rem;
    }

    [data-theme='mono'] .kp-spec__swatch {
        border-radius: 3px;
        border: 1px solid var(--border-strong);
    }

    [data-theme='mono'] .kp-spec__font {
        font-size: 1rem;
    }

    /* ── Motion, guarded [DI7] ────────────────────────────────────────── */

    /* Every animation and transition of this register lives here, inside
       the no-preference guard, so a reader who asked for reduced motion
       never receives one: the rest states above are what they get — a
       plain headline, hairlines already drawn, redaction bars already
       resolved to whichever side their class says. The durations are
       literal because check-motion.mjs computes DI5's rate from them; the
       matching --kp-* knobs are what js/effects.js reads. */
    @media (prefers-reduced-motion: no-preference) {
        /* The headline: one sweep, once, on load. */
        [data-theme='mono'] [data-kp-reveal='headline'].is-revealed {
            animation: kp-wipe 600ms var(--fx-ease) 1 both;
        }

        /* The rule: the base layer's own kp-rule-in, at the demo's 400ms. */
        [data-theme='mono'] [data-kp-reveal='rule'].is-in::after {
            animation: kp-rule-in 400ms var(--fx-ease) 1 both;
        }

        /* The dossier's redaction bars: a transition, not an animation —
           each mark toggles between two known mask positions as its own
           .is-cleared class comes and goes, staggered 400ms apart
           (0/400/800ms) by nth-of-type, exactly as the demo's three
           transition-delay values did. */
        [data-theme='mono'] .kp-card[data-kp-reveal='emphasis'] mark::after {
            transition: mask-position 400ms var(--fx-ease);
        }

        [data-theme='mono'] .kp-card[data-kp-reveal='emphasis'] mark:nth-of-type(2)::after {
            transition-delay: var(--kp-redact-stagger);
        }

        [data-theme='mono'] .kp-card[data-kp-reveal='emphasis'] mark:nth-of-type(3)::after {
            transition-delay: calc(2 * var(--kp-redact-stagger));
        }
    }

    /* ── Motion [DI5, DI7] ────────────────────────────────────────────── */

    /* kp-wipe has its row in TIMINGS (js/effects.js); kp-rule-in is the
       base layer's own, reused here at the demo's own duration. The mask
       sweeps once, hard-edge; nothing here changes luminance. */
    @keyframes kp-wipe {
        from {
            mask-position: 0% 0%;
            -webkit-mask-position: 0% 0%;
        }

        to {
            mask-position: 100% 0%;
            -webkit-mask-position: 100% 0%;
        }
    }

    /* The file code beside the wordmark [S49, A3]. */
    [data-theme='mono'] .kp-nav__brand-tag {
        font-family: var(--theme-font-mono);
        color: var(--muted-foreground);
        letter-spacing: 0.08em;
    }
    /* The band [M1, M4]: Kenny picked this theme's own version over the
       shared one on 2026-09-08 — a hairline above and below, everything in mono, a step smaller. */
    [data-theme='mono'] .kp-marquee {
        border-block: 1px solid var(--border);
        font-family: var(--theme-font-mono);
        font-size: 0.85em;
        --kp-marquee: 40000ms;
    }

    /* The menu's caption [M3]: the same choice, for the line a consumer
       may put above a dropdown's items. */
    [data-theme='mono'] .kp-nav__menu[data-kp-menu-label]::before {
        font-family: var(--theme-font-mono);
        letter-spacing: 0.04em;
        border-block-end: 1px solid var(--border);
    }
}

@layer kp.register {
    /* @kp-soft/themes — css/high-contrast-register.css
   The high-contrast register, 5.0.0 [S48, LIFT_PLAN row 6]: printed for
   the reader who needs contrast, not comfort. Scoped to
   [data-theme='high-contrast'] and inert elsewhere; opt-in, imported
   after themes.css. The approved concept demo ("Ink & Signal",
   2026-09-08) is the reference for every value here.

   The idea, restated from the demo's own comment block: pure black on
   pure white (21:1), one signal-yellow accent that is never used as
   text, no gradient, no shadow, no texture, no gloss. Every control
   keeps a real border — 2px at rest, black on focus — never a colour
   change alone. Every motion is a single load- or click-triggered
   transition that starts and stops once; nothing loops, nothing blinks,
   nothing eases past linear or ease-out.

   What this file does, in order: the knobs; the ring and the selection;
   type; the hooks of S45 — the headline's one-shot ellipse wipe, the
   redaction bars a mark hides behind, the drawn rule, the razor-tear
   divider; the hero's own pieces; the navbar and its dropdown; the
   buttons, including the mirrored press and the ghost's rising bar; the
   fields; the dossier and its stamp; the panels; the footer; and one
   answer per component root (TH124). The reveals have their rest state
   here and their motion in this file's own guarded block; without a
   script or with reduced motion every one of them stands at rest —
   these two reveals are pure CSS and do not depend on js/effects.js at
   all (a deliberate divergence from the JS-driven, once-per-session
   convention the other five registers use; recorded in the anatomy and
   the lift report, S49).

   Colour discipline (DI9): nothing here names a colour. --border-strong
   is the only ink most controls need; --accent is the one signal colour
   and it is never set as a foreground on the page ground (1.51:1, well
   under the floor — refused by construction, matching the demo's own
   contrast table). */

    [data-theme='high-contrast'] {
        /* The configuration surface [AR43], the demo's own values. */
        --kp-headline-wipe: 550ms;
        --kp-rule-wipe: 400ms;
        --kp-redact-lift: 300ms;
        --kp-redact-stagger: 90ms;
        --kp-ghost-bar: 140ms;
        /* The reveals this theme performs [S45]. The headline and the rule
           are left unset on purpose: js/effects.js treats an unset routine
           as quiet and leaves the element alone, which is what lets the
           plain CSS keyframes below run unconditionally, exactly once,
           on every load — the demo's own idiom, with no character
           scrambling and no session memo. Emphasis needs a routine (any
           non-empty word) so the module leaves the dossier's marks in
           their CSS rest state instead of clearing them before the
           trigger is ever pressed [S49]. */
        --kp-reveal-emphasis: classified;
        /* The mirror press: a flat 3px offset, no blur, no colour. */
        --kp-mirror-offset: 3px;
    }

    /* ── The ring and the selection [DI2] ─────────────────────────────────
       The demo stacks the paper channel inside and the ink channel
       outside — the opposite order from the base layer's default, which
       register rule 8 allows either way, since both channels still clear
       3:1 against what is behind them. */
    [data-theme='high-contrast'] :focus-visible {
        outline: none;
        box-shadow:
            0 0 0 2px var(--background),
            0 0 0 4px var(--foreground);
    }

    [data-theme='high-contrast'] ::selection {
        background: var(--foreground);
        color: var(--background);
    }

    /* ── Type ──────────────────────────────────────────────────────────── */

    [data-theme='high-contrast'] a {
        text-decoration-thickness: 2px;
        text-underline-offset: 0.15em;
    }

    [data-theme='high-contrast'] .microlabel {
        text-transform: uppercase;
        letter-spacing: 0.12em;
        font-size: var(--kp-text-xs);
        font-weight: 700;
        color: var(--muted-foreground);
    }

    /* ── The hooks [S45]: the headline, the mark, the rule, the divider ── */

    /* The headline: a clip-path ellipse wipe sweeping on from the left
       edge, once, on load — no character scrambling, text intact
       throughout. The base value IS the fully-revealed state, so a page
       with no script (or reduced motion, which drops the animation
       below) still shows the headline whole [AR34's promise, kept by a
       plain property rather than a class]. */
    [data-theme='high-contrast'] [data-kp-reveal='headline'] {
        clip-path: ellipse(150% 150% at 0% 50%);
    }

    @keyframes kp-hc-headline-wipe {
        from {
            clip-path: ellipse(0% 0% at 0% 50%);
        }

        to {
            clip-path: ellipse(150% 150% at 0% 50%);
        }
    }

    /* The rule under a heading: a 3px bar that draws left to right, once,
       on load. Same rest-state-is-final idiom as the headline. */
    [data-theme='high-contrast'] [data-kp-reveal='rule']::after {
        content: '';
        display: block;
        height: 3px;
        margin-block-start: 0.5rem;
        background: var(--foreground);
        transform: scaleX(1);
        transform-origin: left center;
    }

    @keyframes kp-hc-rule-wipe {
        from {
            transform: scaleX(0);
        }

        to {
            transform: scaleX(1);
        }
    }

    /* The mark, outside the dossier: an accent plate, always on — the
       demo's own lede treatment, with no cover-and-clear mechanism (the
       shared module still toggles is-cleared on it, but nothing here
       reads that class, so nothing changes). */
    [data-theme='high-contrast'] mark {
        background: var(--accent);
        color: var(--accent-foreground);
        padding: 0.05em 0.25em;
        border-radius: 0.15em;
    }

    /* The divider: a flat two-tone hard edge, no blur — the "razor tear". */
    [data-theme='high-contrast'] [data-kp-divider] {
        display: block;
        block-size: 6px;
        background: var(--border-strong);
        border-bottom: 2px solid var(--accent);
        margin: 0;
    }

    [data-theme='high-contrast'] [data-kp-divider='alt'] {
        background: var(--accent);
        border-bottom: 2px solid var(--border-strong);
    }

    /* ── The nav bar and its dropdown [KT14] ──────────────────────────── */

    [data-theme='high-contrast'] .kp-nav-wrap {
        background: var(--background);
        border-bottom: 3px solid var(--border-strong);
        box-shadow: none;
    }

    /* No script sets data-scrolled today [finding, S49]: the demo's nav
       recolour on scroll has no shared JS hook to drive it (no module in
       this package writes [data-scrolled], and a page-local script is
       forbidden, TH109). The rule is kept, inert, so the mechanism is
       exactly what the demo specifies the moment such a hook exists. */
    [data-theme='high-contrast'] .kp-nav-wrap[data-scrolled] {
        border-bottom-color: var(--border-strong);
        box-shadow: 0 3px 0 0 var(--accent);
    }

    [data-theme='high-contrast'] .kp-nav__brand {
        letter-spacing: 0.01em;
    }

    [data-theme='high-contrast'] .kp-nav__link {
        font-weight: 700;
        border-bottom: 2px solid transparent;
        border-radius: 0;
    }

    [data-theme='high-contrast'] .kp-nav__link:hover,
    [data-theme='high-contrast'] .kp-nav__link[aria-current='page'] {
        border-bottom-color: var(--foreground);
    }

    [data-theme='high-contrast'] .kp-nav__link--lang {
        text-transform: uppercase;
        font-size: 0.85rem;
    }

    [data-theme='high-contrast'] .kp-nav__link--cta {
        background: var(--accent);
        color: var(--accent-foreground);
        border-bottom: none;
        border-radius: var(--radius);
        padding-inline: var(--kp-space-md);
    }

    [data-theme='high-contrast'] .kp-nav__link--cta:hover {
        border-bottom: none;
    }

    /* The dropdown: white, the black line, no fade — matches the demo's
       own panel exactly [KT14]. */
    [data-theme='high-contrast'] .kp-nav__menu {
        border: 2px solid var(--border-strong);
        border-radius: var(--radius);
        box-shadow: none;
    }

    [data-theme='high-contrast'] .kp-nav__menu a:hover,
    [data-theme='high-contrast'] .kp-nav__menu a:focus-visible {
        background: var(--muted);
    }

    /* ── The hero's own pieces [S46] ──────────────────────────────────── */

    [data-theme='high-contrast'] .kp-side-note {
        font-family: var(--theme-font-mono);
        letter-spacing: 0.08em;
    }

    [data-theme='high-contrast'] .kp-laurels {
        border-bottom: 1px solid var(--border);
        padding-block-end: var(--kp-space-md);
        gap: var(--kp-space-lg) var(--kp-space-2xl);
    }

    [data-theme='high-contrast'] .kp-laurels b {
        font-size: 1.15rem;
        letter-spacing: -0.01em;
    }

    [data-theme='high-contrast'] .kp-platforms {
        font-family: var(--theme-font-mono);
        padding-block-start: var(--kp-space-sm);
        border-top: 1px solid var(--border);
    }

    [data-theme='high-contrast'] h1.kp-headline,
    [data-theme='high-contrast'] [data-kp-surface] h1 {
        letter-spacing: -0.015em;
        max-width: 18ch;
    }

    [data-theme='high-contrast'] .kp-lede {
        max-width: 52ch;
        font-size: 1.1rem;
    }

    /* The spec sheet: the card treatment, the swatches with the ink line. */
    [data-theme='high-contrast'] .kp-spec {
        border: 2px solid var(--border-strong);
    }

    [data-theme='high-contrast'] .kp-spec dt {
        text-transform: uppercase;
        letter-spacing: 0.06em;
        font-size: var(--kp-text-xs);
    }

    [data-theme='high-contrast'] .kp-spec dd {
        font-family: var(--theme-font-mono);
        font-size: var(--kp-text-xs);
    }

    [data-theme='high-contrast'] .kp-spec__swatch {
        border: 2px solid var(--border-strong);
        border-radius: 0.2rem;
        inline-size: 1.1em;
        block-size: 1.1em;
    }

    /* ── Buttons: a real border, never a colour alone ─────────────────── */

    [data-theme='high-contrast'] .kp-button {
        border-width: 2px;
        font-weight: 700;
    }

    [data-theme='high-contrast'] .kp-button--primary {
        border-color: var(--primary);
    }

    [data-theme='high-contrast'] .kp-button--destructive {
        border-color: var(--destructive);
    }

    /* The mirror: a flat offset shadow, no blur — pressed drops the
       button onto it. Only the buttons the demo marks --mirror carry
       this; every other theme's --fx-shadow-offset knob stays 0 so
       nothing changes for them. */
    [data-theme='high-contrast'] .kp-button--mirror {
        box-shadow: var(--kp-mirror-offset) var(--kp-mirror-offset) 0 0 var(--border-strong);
    }

    [data-theme='high-contrast'] .kp-button--mirror:active:not(:disabled) {
        box-shadow: none;
        translate: var(--kp-mirror-offset) var(--kp-mirror-offset);
    }

    [data-theme='high-contrast'] .kp-button--mirror:focus-visible {
        box-shadow:
            0 0 0 2px var(--background),
            0 0 0 4px var(--foreground),
            var(--kp-mirror-offset) var(--kp-mirror-offset) 0 0 var(--border-strong);
    }

    /* Ghost: no fill, border-strong outline. The demo's mechanism — a
       second copy of the label sliding up from below — needs two copies
       of the text in the DOM; the shared Button renderer emits one
       [finding, S49]. Kept instead: a bar rises from the bottom edge on
       hover/focus, the same "something arrives from below" gesture,
       CSS-only and content-free. */
    [data-theme='high-contrast'] .kp-button--ghost {
        border-color: var(--border-strong);
        overflow: hidden;
        position: relative;
    }

    [data-theme='high-contrast'] .kp-button--ghost::after {
        content: '';
        position: absolute;
        inset-inline: 0;
        inset-block-end: 0;
        block-size: 3px;
        background: var(--foreground);
        transform: translateY(100%);
    }

    [data-theme='high-contrast'] .kp-button--ghost:hover::after,
    [data-theme='high-contrast'] .kp-button--ghost:focus-visible::after {
        transform: translateY(0);
    }

    [data-theme='high-contrast'] .kp-icon-button {
        border-width: 2px;
    }

    /* ── Fields: a soft hairline at rest, black on focus ──────────────── */

    [data-theme='high-contrast'] .kp-field__input,
    [data-theme='high-contrast'] .kp-datatable__search,
    [data-theme='high-contrast'] .kp-combobox__input,
    [data-theme='high-contrast'] .kp-palette__input {
        border: 2px solid var(--border);
    }

    [data-theme='high-contrast'] .kp-field__input:focus-visible,
    [data-theme='high-contrast'] .kp-datatable__search:focus-visible,
    [data-theme='high-contrast'] .kp-combobox__input:focus-visible,
    [data-theme='high-contrast'] .kp-palette__input:focus-visible {
        border-color: var(--border-strong);
    }

    [data-theme='high-contrast'] .kp-field__label {
        font-weight: 700;
    }

    [data-theme='high-contrast'] .kp-field__required,
    [data-theme='high-contrast'] .kp-field__help {
        color: var(--muted-foreground);
        font-size: 0.78rem;
        font-weight: 400;
    }

    [data-theme='high-contrast'] .kp-field__check {
        accent-color: var(--primary);
    }

    [data-theme='high-contrast'] .kp-fieldset {
        border: 2px solid var(--border-strong);
    }

    [data-theme='high-contrast'] .kp-form__summary {
        border: 2px solid var(--border-strong);
    }

    /* ── Cards and the dossier ────────────────────────────────────────── */

    [data-theme='high-contrast'] .kp-card {
        border: 2px solid var(--border-strong);
        box-shadow: none;
    }

    /* The stamp: a bordered plate in the destructive ink, tilted — the
       demo's own "On record". */
    [data-theme='high-contrast'] .kp-card[data-kp-label]::before {
        content: attr(data-kp-label);
        position: absolute;
        inset-block-start: var(--kp-space-lg);
        inset-inline-end: var(--kp-space-lg);
        border: 2px solid var(--destructive);
        color: var(--destructive);
        font-family: var(--theme-font-mono);
        font-size: 0.7rem;
        font-weight: 700;
        letter-spacing: 0.1em;
        padding: 0.15em 0.5em;
        border-radius: 0.2rem;
        text-transform: uppercase;
    }

    [data-theme='high-contrast'] .kp-card[data-kp-reveal='emphasis'] {
        position: relative;
    }

    /* The redactions: solid bars over the words, one per mark. At rest —
       no script — the marks stand clear, matching AR34's promise; armed
       and not yet cleared, the bar covers the word from the left, and
       lifting shrinks it away, three staggered by 90/180ms exactly as
       the demo's transition-delay ladder does. */
    [data-theme='high-contrast'] .kp-card[data-kp-reveal='emphasis'] mark {
        /* inline-block: an absolutely positioned ::after covers the box
           an inline element generates, and an inline mark that wraps
           generates one box PER LINE — the bar then covers only the
           last fragment, a sliver rather than a bar (caught by eye at
           1280px, "tired eyes at the end of a shift" wrapping). As one
           atomic box the phrase wraps as a whole instead. */
        display: inline-block;
        position: relative;
        background: none;
        color: var(--card-foreground);
        font-weight: 400;
        padding: 0;
        border-radius: 0;
    }

    [data-theme='high-contrast'] .kp-card[data-kp-reveal='emphasis'] mark::after {
        content: '';
        position: absolute;
        inset: -0.05em -0.15em;
        background: var(--foreground);
        border-radius: 0.1em;
        transform: scaleX(0);
        transform-origin: left center;
        pointer-events: none;
    }

    [data-theme='high-contrast'][data-kp-effects] .kp-card[data-kp-reveal='emphasis'] mark:not(.is-cleared) {
        color: transparent;
    }

    [data-theme='high-contrast'][data-kp-effects] .kp-card[data-kp-reveal='emphasis'] mark:not(.is-cleared)::after {
        transform: scaleX(1);
    }

    [data-theme='high-contrast'] .kp-card[data-kp-reveal='emphasis'] mark:nth-of-type(2)::after {
        transition-delay: var(--kp-redact-stagger);
    }

    [data-theme='high-contrast'] .kp-card[data-kp-reveal='emphasis'] mark:nth-of-type(3)::after {
        transition-delay: calc(2 * var(--kp-redact-stagger));
    }

    /* ── Panels: white, the line, no float, no fade ───────────────────── */

    [data-theme='high-contrast'] .kp-dialog,
    [data-theme='high-contrast'] .kp-confirm {
        border: 3px solid var(--border-strong);
    }

    [data-theme='high-contrast'] .kp-popover,
    [data-theme='high-contrast'] .kp-menu,
    [data-theme='high-contrast'] .kp-toast,
    [data-theme='high-contrast'] .kp-tooltip,
    [data-theme='high-contrast'] .kp-datepicker__panel,
    [data-theme='high-contrast'] .kp-combobox__list,
    [data-theme='high-contrast'] .kp-palette,
    [data-theme='high-contrast'] .kp-theme-menu {
        border: 2px solid var(--border-strong);
    }

    [data-theme='high-contrast'] .kp-toast {
        border-color: var(--success);
    }

    [data-theme='high-contrast'] .kp-menu__item:hover,
    [data-theme='high-contrast'] .kp-menu__item:focus-visible {
        background: var(--muted);
    }

    [data-theme='high-contrast'] .kp-alert {
        border: 2px solid var(--border-strong);
    }

    [data-theme='high-contrast'] .kp-alert__label {
        font-weight: 700;
    }

    [data-theme='high-contrast'] .kp-grid__tile,
    [data-theme='high-contrast'] .kp-split__pane {
        border: 2px solid var(--border-strong);
    }

    [data-theme='high-contrast'] .kp-split__separator {
        background: var(--border-strong);
        inline-size: 2px;
    }

    /* ── The footer ────────────────────────────────────────────────────── */

    [data-theme='high-contrast'] .kp-footer {
        border-top: 3px solid var(--border-strong);
    }

    [data-theme='high-contrast'] .kp-footer h4 {
        font-size: 0.9rem;
    }

    [data-theme='high-contrast'] .kp-footer a {
        text-decoration: none;
        border-bottom: 1px solid transparent;
    }

    [data-theme='high-contrast'] .kp-footer a:hover,
    [data-theme='high-contrast'] .kp-footer a:focus-visible {
        border-bottom-color: currentColor;
    }

    /* ── Badges, tags, status: plates with black ink, never colour alone ── */

    [data-theme='high-contrast'] .kp-badge,
    [data-theme='high-contrast'] .kp-tag {
        border: 2px solid var(--border-strong);
        font-weight: 700;
    }

    [data-theme='high-contrast'] .kp-health {
        font-weight: 700;
    }

    [data-theme='high-contrast'] .kp-health__dot {
        border: 2px solid var(--border-strong);
    }

    [data-theme='high-contrast'] .kp-skeleton {
        border: 1px solid var(--border);
    }

    [data-theme='high-contrast'] .kp-progress {
        border: 2px solid var(--border-strong);
    }

    [data-theme='high-contrast'] .kp-progress__value {
        background: var(--primary);
    }

    [data-theme='high-contrast'] .kp-spinner {
        border-color: var(--border);
        border-top-color: var(--foreground);
    }

    [data-theme='high-contrast'] .kp-empty {
        border: 2px dashed var(--border);
    }

    [data-theme='high-contrast'] .kp-empty__title {
        font-weight: 700;
    }

    [data-theme='high-contrast'] .kp-error {
        color: var(--destructive);
        font-weight: 700;
    }

    /* ── Text shapes ──────────────────────────────────────────────────── */

    [data-theme='high-contrast'] .kp-id,
    [data-theme='high-contrast'] .kp-url,
    [data-theme='high-contrast'] .kp-numeric,
    [data-theme='high-contrast'] .kp-timestamp,
    [data-theme='high-contrast'] .kp-masked,
    [data-theme='high-contrast'] .kp-copyable,
    [data-theme='high-contrast'] .kp-truncate,
    [data-theme='high-contrast'] .kp-cell-break,
    [data-theme='high-contrast'] .kp-cell-truncate {
        font-family: var(--theme-font-mono);
    }

    [data-theme='high-contrast'] .kp-timestamp,
    [data-theme='high-contrast'] .kp-id {
        color: var(--muted-foreground);
    }

    [data-theme='high-contrast'] .kp-copyable__button {
        border: 2px solid var(--border-strong);
    }

    /* ── Data ─────────────────────────────────────────────────────────── */

    [data-theme='high-contrast'] .kp-table {
        border: 2px solid var(--border-strong);
    }

    [data-theme='high-contrast'] .kp-table th {
        border-bottom: 2px solid var(--border-strong);
        font-weight: 700;
    }

    [data-theme='high-contrast'] .kp-table td {
        border-bottom: 1px solid var(--border);
    }

    [data-theme='high-contrast'] .kp-table tbody tr:hover {
        background: var(--muted);
    }

    [data-theme='high-contrast'] .kp-datatable {
        border: 2px solid var(--border-strong);
    }

    [data-theme='high-contrast'] .kp-datatable__bar {
        border-bottom: 2px solid var(--border-strong);
    }

    [data-theme='high-contrast'] .kp-datatable__sort[aria-sort] {
        background: var(--muted);
    }

    [data-theme='high-contrast'] .kp-datatable__status,
    [data-theme='high-contrast'] .kp-datatable__page {
        font-family: var(--theme-font-mono);
    }

    [data-theme='high-contrast'] .kp-diff {
        border: 2px solid var(--border-strong);
    }

    [data-theme='high-contrast'] .kp-diff__line {
        font-family: var(--theme-font-mono);
    }

    [data-theme='high-contrast'] .kp-timeline {
        border-inline-start: 2px solid var(--border-strong);
    }

    [data-theme='high-contrast'] .kp-timeline__marker {
        border: 2px solid var(--border-strong);
        background: var(--background);
    }

    [data-theme='high-contrast'] .kp-timeline__when {
        font-family: var(--theme-font-mono);
        color: var(--muted-foreground);
    }

    [data-theme='high-contrast'] .kp-reorder {
        border: 2px solid var(--border-strong);
    }

    /* ── Navigation and steps ─────────────────────────────────────────── */

    [data-theme='high-contrast'] .kp-tab {
        border-bottom: 2px solid transparent;
        font-weight: 700;
    }

    [data-theme='high-contrast'] .kp-tab[aria-selected='true'] {
        border-bottom-color: var(--foreground);
    }

    [data-theme='high-contrast'] .kp-tabs__list {
        border-bottom: 2px solid var(--border);
    }

    [data-theme='high-contrast'] .kp-breadcrumb,
    [data-theme='high-contrast'] .kp-pagination {
        font-weight: 700;
    }

    [data-theme='high-contrast'] .kp-pagination a[aria-current],
    [data-theme='high-contrast'] .kp-pagination [aria-current] {
        background: var(--primary);
        color: var(--primary-foreground);
        border-radius: var(--radius);
    }

    [data-theme='high-contrast'] .kp-wizard {
        border: 2px solid var(--border-strong);
    }

    [data-theme='high-contrast'] .kp-wizard__steps {
        font-weight: 700;
    }

    /* ── Pickers and palettes ─────────────────────────────────────────── */

    [data-theme='high-contrast'] .kp-datepicker__day[aria-selected='true'] {
        background: var(--primary);
        color: var(--primary-foreground);
    }

    [data-theme='high-contrast'] .kp-colorpicker__swatch {
        border: 2px solid var(--border-strong);
    }

    [data-theme='high-contrast'] .kp-colorpicker__value {
        font-family: var(--theme-font-mono);
    }

    [data-theme='high-contrast'] .kp-shortcuts__row kbd {
        font-family: var(--theme-font-mono);
        border: 2px solid var(--border-strong);
        border-radius: 0.2rem;
        padding: 0 0.4em;
    }

    [data-theme='high-contrast'] .kp-theme-menu__status,
    [data-theme='high-contrast'] .kp-palette__status,
    [data-theme='high-contrast'] .kp-combobox__status {
        font-family: var(--theme-font-mono);
    }

    /* ── The roots the rules above reach only by their parts ──────────── */

    [data-theme='high-contrast'] .kp-field {
        gap: 0.3rem;
    }

    [data-theme='high-contrast'] .kp-form {
        gap: var(--kp-space-lg);
    }

    [data-theme='high-contrast'] .kp-nav {
        border-bottom: 0;
    }

    [data-theme='high-contrast'] .kp-grid {
        gap: var(--kp-space-lg);
    }

    [data-theme='high-contrast'] .kp-split {
        gap: var(--kp-space-md);
    }

    [data-theme='high-contrast'] .kp-toasts {
        gap: var(--kp-space-md);
    }

    [data-theme='high-contrast'] .kp-combobox,
    [data-theme='high-contrast'] .kp-datepicker,
    [data-theme='high-contrast'] .kp-colorpicker,
    [data-theme='high-contrast'] .kp-shortcuts {
        border-radius: var(--radius);
    }

    [data-theme='high-contrast'] .kp-tree {
        font-weight: 500;
    }

    /* ── The scrollbar joins the theme ────────────────────────────────── */

    [data-theme='high-contrast'] {
        scrollbar-color: var(--border-strong) var(--background);
    }

    /* ── Motion, guarded [DI7] ────────────────────────────────────────── */

    /* Every animation and transition of this register lives here. The
       headline and the rule wipe once on load, unconditionally — no
       class, no [data-kp-effects] gate, matching the demo's own idiom of
       plain CSS with no session memo. The ghost bar and the redaction
       lift are interaction-bound; the mirror press has no transition at
       all, exactly as the demo draws it (an instant drop, not an
       eased one). */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='high-contrast'] [data-kp-reveal='headline'] {
            animation: kp-hc-headline-wipe var(--kp-headline-wipe) ease-out 1;
        }

        [data-theme='high-contrast'] [data-kp-reveal='rule']::after {
            animation: kp-hc-rule-wipe var(--kp-rule-wipe) ease-out 1;
        }

        [data-theme='high-contrast'] .kp-nav-wrap {
            transition:
                border-color var(--fx-duration) var(--fx-ease),
                box-shadow var(--fx-duration) var(--fx-ease);
        }

        /* The shared .kp-button rule (css/components.css) puts `translate`
           in its own transition list for the hover lift every other theme
           uses; high-contrast's --fx-lift is 0px, so that lift is already
           a no-op here, but the same list would ease the mirror's press
           over --fx-duration instead of snapping it, which is not what
           the demo draws. Cancelled for this variant only. */
        [data-theme='high-contrast'] .kp-button--mirror {
            transition: none;
        }

        [data-theme='high-contrast'] .kp-button--ghost::after {
            transition: transform var(--kp-ghost-bar) var(--fx-ease);
        }

        [data-theme='high-contrast'] .kp-card[data-kp-reveal='emphasis'] mark::after {
            transition: transform var(--kp-redact-lift) ease-out;
        }

        [data-theme='high-contrast'] .kp-nav__link {
            transition: border-color var(--fx-duration) var(--fx-ease);
        }
    }
    /* The band [M1, M4]: Kenny picked this theme's own version over the
       shared one on 2026-09-08 — inverted: the ground is ink and the ink is paper. */
    [data-theme='high-contrast'] .kp-marquee {
        background: var(--foreground);
        color: var(--background);
        font-weight: 700;
        text-transform: uppercase;
        --kp-marquee: 52000ms;
    }

    /* The menu's caption [M3]: the same choice, for the line a consumer
       may put above a dropdown's items. */
    [data-theme='high-contrast'] .kp-nav__menu[data-kp-menu-label]::before {
        background: var(--foreground);
        color: var(--background);
        font-weight: 700;
        border-block-end: 0;
    }
}

@layer kp.register {
    /* @kp-soft/themes — css/lapis-register.css
   The lapis register, 5.0.0 [S48, LIFT_PLAN row 6]: Persian illumination.
   Scoped to [data-theme='lapis'] and inert elsewhere; opt-in, imported
   after themes.css. The approved concept demo ("Lapis and Leaf",
   2026-09-08) is the reference for every value here.

   What this file does, in order: the knobs, the girih tile and the
   four-ring frame; the type; the hooks of S45 — the headline that burnishes
   in with one gold wipe, the mark as an inscription in the lede and as the
   seal over the dossier's redactions, the rule that draws under a heading,
   the ruled divider (the wide one carrying the girih dot, the narrow one a
   plain hatch); the hero's side note and its own hatch; the navbar with the
   double-stroke ruling; the buttons; the fields; the spec sheet and the
   footer; and one answer per component root (TH124). The reveals have
   their rest state here and their motion in js/effects.js; without the
   script every one of them stands at rest.

   Colour discipline (DI9): nothing here names a colour. Lapis, void, card,
   popover, ivory, ivory-muted, gold, gold-ink, gold-line (== --input),
   hairline (== --border), vermilion, scarlet and the teal accent are all
   `var(--token)` or a relative colour of one — the demo's own palette maps
   onto the existing 94-token contract one-for-one (see the anatomy), so no
   token gains a new entry and no other theme owes a change.

   The girih tile [§ demo (1), DI9]: this theme shipped a page-wide girih
   SVG texture in css/_rules.css before round six (3.1.1, TH74); the
   approved demo refuses that as a hazard — "the same conic-gradient recipe
   at 5%, confined to the hero/app surfaces, not the whole page" — so this
   register turns the page-wide layer off (`--fx-texture-opacity: 0`, a
   later cascade layer than css/_rules.css's kp.base) and paints the tile
   itself only on `[data-kp-surface]`, at the same 5% the old page-wide
   layer used.

   Nothing here flickers or loops: the burnish is a single wipe, the
   inscription and the seal are one-shot transitions, the ruling is
   otherwise static — the approved demo's own DI5 section found zero
   `@keyframes`/`transition` across every measured reference and its own
   research file, and anatomy.md's pre-round-six answer was already "no
   animation; the ruling is static." */

    [data-theme='lapis'] {
        /* The configuration surface [AR43], the demo's values as defaults. */
        --kp-reveal-threshold: 0.6;
        --kp-reveal-stagger: 300ms;
        --kp-redact-stagger: 120ms;
        --kp-classified-delay: 700ms;
        --kp-burnish: 900ms;
        --kp-inscribe: 600ms;
        --kp-inscribe-lead: 200ms;
        --kp-seal: 220ms;
        --kp-rule: 480ms;
        /* The reveals this theme performs [S45]: js/effects.js reads these
           and leaves a theme that declares none at rest. `gild` is this
           theme's own headline routine [S49]: neither a per-word shout, a
           per-glyph type nor a dither dissolve, but one wipe over the
           whole clause — the gilder's burnishing pass. */
        --kp-reveal-headline: gild;
        --kp-reveal-emphasis: classified;
        --kp-reveal-rule: draw;
        /* No arrival: the demo shows none, and anatomy.md's own rule is
           "no animation; the ruling is static" — a boot sequence would be
           the one thing here that moves without being asked. */

        /* The girih tile [DI9, §(1)]: a ten-spoke wheel in the gold, plus a
           small radial in the teal accent, at 5% peak alpha — under DI9's
           6% ceiling, so no perTheme override is needed. */
        --kp-girih-tile:
            repeating-conic-gradient(
                from 18deg at 50% 50%,
                transparent 0deg 29deg,
                hsl(from var(--primary) h s l / 0.05) 29deg 31deg,
                transparent 31deg 36deg
            ),
            radial-gradient(circle at 50% 50%, hsl(from var(--chart-3) h s l / 0.05) 0 5%, transparent 6%);
        --kp-girih-size: 96px 96px, 96px 96px;
        /* The page-wide texture this theme carried since 3.1.1 (TH74) is
           refused by the demo as a hazard [§(2)] — turned off here, one
           cascade layer above css/_rules.css's kp.base declaration. */
        --fx-texture-opacity: 0;

        /* The gold hatch [§(1)]: a 1px hairline at low alpha, the pitch the
           demo measured. */
        --kp-hatch: repeating-linear-gradient(90deg, hsl(from var(--primary) h s l / 0.16) 0 1px, transparent 1px 24px);
        --kp-hatch-faint: repeating-linear-gradient(90deg, hsl(from var(--primary) h s l / 0.14) 0 1px, transparent 1px 24px);

        /* The four-ring frame [§(1)]: a ruled border of concentric rings —
           the gold-line edge, an ivory inset, a deeper gold-line inset —
           drawn rather than filled, on whatever surface it sits over. */
        --kp-ring-on-card:
            inset 0 0 0 1px var(--card), inset 0 0 0 3px hsl(from var(--card-foreground) h s l / 0.28), inset 0 0 0 4px var(--border-strong);
        --kp-ring-on-popover:
            inset 0 0 0 1px var(--popover), inset 0 0 0 3px hsl(from var(--popover-foreground) h s l / 0.28), inset 0 0 0 4px var(--border-strong);
        --kp-ring-on-ground:
            inset 0 0 0 1px var(--background), inset 0 0 0 3px hsl(from var(--foreground) h s l / 0.28), inset 0 0 0 4px var(--border-strong);
    }

    /* ── Type ──────────────────────────────────────────────────────────── */

    [data-theme='lapis'] h1,
    [data-theme='lapis'] h2,
    [data-theme='lapis'] h3 {
        font-family: var(--theme-font-display);
        font-weight: 600;
        line-height: 1.1;
        letter-spacing: 0.01em;
    }

    [data-theme='lapis'] [data-kp-surface] h1 {
        font-size: var(--kp-text-display);
        line-height: 1.1;
        margin-block: 0 0.35em;
        text-wrap: balance;
    }

    /* Microlabels: the mono voice, in gold, the small print of a colophon. */
    [data-theme='lapis'] .microlabel {
        font-family: var(--theme-font-mono);
        font-size: 0.78rem;
        letter-spacing: 0.12em;
        text-transform: uppercase;
        color: var(--primary);
        line-height: 1.4;
    }

    /* ── The hooks [S45]: the burnish, the inscription, the rule, the divider ── */

    /* The burnish [§(1)/(5)]: the headline is whole and already gold; the
       wipe is a clip-path inset that opens left to right once, with a
       brief brightness/saturation lift that settles as it lands — the
       gilder's burnishing pass. Without the script it stands fully
       revealed, flat gold. */
    [data-theme='lapis'] [data-kp-reveal='headline'] {
        color: var(--primary);
        display: inline-block;
    }

    [data-theme='lapis'][data-kp-effects] [data-kp-reveal='headline']:not(.is-deciphered) {
        clip-path: inset(0 100% 0 0);
        filter: brightness(1.7) saturate(0.7);
    }

    /* The rule [§ template]: a gold hairline draws in under a heading, left
       to right, when it enters the viewport — the ruling of a page drawn
       once, at rest. */
    [data-theme='lapis'] [data-kp-reveal='rule']::after {
        content: '';
        display: block;
        block-size: 1px;
        margin-block-start: 0.6rem;
        background: var(--border-strong);
        transform: scaleX(1);
        transform-origin: left center;
    }

    [data-theme='lapis'][data-kp-effects] [data-kp-reveal='rule']:not(.is-in)::after {
        transform: scaleX(0);
    }

    /* The inscription [§(1)/(5)]: a mark in running prose stands in ivory
       with no rule under it, then its ink shifts to gold and a gold
       underline draws in, once, staggered per mark — an illuminator inking
       a rubric after the black text is already laid. Loose marks (the
       lede) get this; a mark inside the dossier is overridden below to the
       seal instead. */
    [data-theme='lapis'] mark {
        background: transparent;
        color: var(--foreground);
        padding: 0 0.05em;
        border-bottom: 2px solid transparent;
    }

    [data-theme='lapis'] mark.is-cleared {
        color: var(--primary);
        border-bottom-color: var(--primary);
    }

    /* The divider: the wide ruled one carries the four-ring frame, the gold
       hatch and a small teal dot at centre; the narrow one is a plain
       hatch, no ring. */
    [data-theme='lapis'] [data-kp-divider] {
        block-size: 34px;
        background-color: var(--background);
        border-block: 1px solid var(--border);
        box-shadow: var(--kp-ring-on-ground);
        background-image: var(--kp-hatch), radial-gradient(circle 9px at 50% 50%, hsl(from var(--chart-3) h s l / 0.4) 0 60%, transparent 75%);
        background-position: center;
        background-repeat: no-repeat, no-repeat;
    }

    [data-theme='lapis'] [data-kp-divider='alt'] {
        block-size: 16px;
        box-shadow: none;
        border-block-start: none;
        background-image: var(--kp-hatch-faint);
    }

    /* ── The hero: the girih tile, the side note ──────────────────────── */

    [data-theme='lapis'] [data-kp-surface='hero'],
    [data-theme='lapis'] [data-kp-surface='app'] {
        position: relative;
        background-image: var(--kp-girih-tile);
        background-size: var(--kp-girih-size);
    }

    [data-theme='lapis'] [data-kp-surface='hero'] {
        padding-block: 2.4rem 3.2rem;
    }

    [data-theme='lapis'] [data-kp-surface='hero'] [data-kp-hero-grid] {
        grid-template-columns: minmax(0, 1.4fr) minmax(260px, 1fr);
        gap: 2.5rem;
        align-items: start;
    }

    @container (max-width: 60rem) {
        [data-theme='lapis'] [data-kp-surface='hero'] [data-kp-hero-grid] {
            grid-template-columns: 1fr;
        }
    }

    [data-theme='lapis'] .kp-side-note {
        font-family: var(--theme-font-mono);
        font-size: 0.75rem;
        letter-spacing: 0.18em;
        color: var(--muted-foreground);
        display: inline-block;
        margin: 0 0 0.6rem;
    }

    @media (min-width: 64rem) {
        [data-theme='lapis'] .kp-side-note {
            writing-mode: vertical-rl;
            transform: rotate(180deg);
            position: absolute;
            inset-block-start: 0;
            inset-inline-start: 0;
            margin: 0;
            padding: 0.5rem 0.2rem;
            background-image: var(--kp-hatch);
        }
    }

    /* ── The navbar: the double-stroke ruling ─────────────────────────── */

    /* girih.js's engraved strapwork line [§(1)]: a wide gold-line hairline
       under a narrow, offset hairline the same colour, so the boundary
       reads as ruled rather than flat. */
    [data-theme='lapis'] .kp-nav-wrap {
        background: var(--sidebar-background);
        border-block-end: 2px solid var(--border-strong);
        box-shadow: 0 3px 0 -2px var(--border);
    }

    [data-theme='lapis'] .kp-nav {
        background: var(--sidebar-background);
        position: relative;
        z-index: var(--kp-z-nav, 30);
    }

    [data-theme='lapis'] .kp-nav__brand {
        font-family: var(--theme-font-display);
        font-weight: 600;
        font-size: 1.375rem;
        letter-spacing: 0.02em;
        color: var(--primary);
    }

    [data-theme='lapis'] .kp-nav__link {
        color: var(--foreground);
        border-radius: 0;
        border-block-end: 1px solid transparent;
        background: none;
    }

    [data-theme='lapis'] .kp-nav__link:hover,
    [data-theme='lapis'] .kp-nav__link:focus-visible,
    [data-theme='lapis'] .kp-nav__link[aria-current],
    [data-theme='lapis'] .kp-nav__links > li:focus-within > .kp-nav__link {
        color: var(--primary);
        border-color: var(--primary);
        background: none;
    }

    [data-theme='lapis'] .kp-nav__link--lang {
        text-transform: uppercase;
        font-family: var(--theme-font-mono);
        font-size: 0.85em;
    }

    /* The call to action is a filled gold plate, the way a rubric is
       filled solid rather than only ruled. */
    [data-theme='lapis'] .kp-nav__link--cta {
        background: var(--primary);
        color: var(--primary-foreground);
        border-radius: var(--radius);
        font-weight: 600;
    }

    [data-theme='lapis'] .kp-nav__link--cta:hover,
    [data-theme='lapis'] .kp-nav__link--cta:focus-visible {
        background: var(--foreground);
        color: var(--background);
        border-color: transparent;
    }

    /* The dropdown: a popover carrying the four-ring frame, KT14's part. */
    [data-theme='lapis'] .kp-nav__menu {
        background: var(--popover);
        border: 1px solid var(--border-strong);
        border-radius: var(--radius);
        box-shadow:
            var(--kp-ring-on-popover),
            0 10px 24px hsl(from var(--sidebar-background) h s l / 0.5);
        min-width: 180px;
    }

    [data-theme='lapis'] .kp-nav__menu a {
        color: var(--popover-foreground);
        border-radius: calc(var(--radius) - 2px);
    }

    [data-theme='lapis'] .kp-nav__menu a:hover,
    [data-theme='lapis'] .kp-nav__menu a:focus-visible {
        background: var(--card);
        color: var(--primary);
    }

    /* ── Buttons: a ruled frame, or a filled gold plate ───────────────── */

    [data-theme='lapis'] .kp-button {
        font-family: var(--theme-font-body);
        font-weight: 600;
        border: 1px solid var(--border-strong);
        border-radius: var(--radius);
        background: transparent;
        color: var(--foreground);
    }

    [data-theme='lapis'] .kp-button:hover {
        border-color: var(--primary);
        color: var(--primary);
    }

    /* The mirror modifier: a burnished-metal gloss on the gold plate — a
       pale highlight along the top edge, a deep shadow along the bottom. */
    [data-theme='lapis'] .kp-button--mirror {
        box-shadow:
            inset 0 1px 0 hsl(from var(--card-foreground) h s l / 0.45),
            inset 0 -8px 12px -8px hsl(from var(--primary-foreground) h s l / 0.55);
    }

    [data-theme='lapis'] .kp-button--primary {
        background: var(--primary);
        color: var(--primary-foreground);
        border-color: var(--primary);
    }

    [data-theme='lapis'] .kp-button--primary:hover,
    [data-theme='lapis'] .kp-button--primary:focus-visible {
        background: var(--foreground);
        color: var(--background);
        border-color: var(--foreground);
    }

    [data-theme='lapis'] .kp-button--destructive {
        background: transparent;
        border-color: var(--destructive);
        color: var(--destructive);
    }

    [data-theme='lapis'] .kp-button--destructive:hover,
    [data-theme='lapis'] .kp-button--destructive:focus-visible {
        background: var(--destructive);
        color: var(--destructive-foreground);
    }

    [data-theme='lapis'] .kp-button--ghost {
        border-color: transparent;
        background: transparent;
    }

    [data-theme='lapis'] .kp-button--ghost:hover,
    [data-theme='lapis'] .kp-button--ghost:focus-visible {
        border-color: var(--border);
        color: var(--primary);
    }

    [data-theme='lapis'] .kp-icon-button {
        border: 1px solid var(--border-strong);
        background: transparent;
        color: var(--foreground);
    }

    [data-theme='lapis'] .kp-icon-button:hover {
        border-color: var(--primary);
        color: var(--primary);
    }

    /* ── Fields ────────────────────────────────────────────────────────── */

    [data-theme='lapis'] .kp-field__label {
        font-weight: 600;
        color: var(--foreground);
    }

    [data-theme='lapis'] .kp-field__required {
        color: var(--primary);
        font-weight: 400;
        font-size: 0.8em;
        margin-inline-start: 0.3em;
    }

    [data-theme='lapis'] .kp-field__input,
    [data-theme='lapis'] .kp-datatable__search,
    [data-theme='lapis'] .kp-combobox__input,
    [data-theme='lapis'] .kp-palette__input {
        background: var(--card);
        color: var(--foreground);
        border: 1px solid var(--border-strong);
        caret-color: var(--primary);
    }

    [data-theme='lapis'] .kp-field__input:focus-visible,
    [data-theme='lapis'] .kp-datatable__search:focus-visible,
    [data-theme='lapis'] .kp-combobox__input:focus-visible,
    [data-theme='lapis'] .kp-palette__input:focus-visible {
        border-color: var(--primary);
    }

    [data-theme='lapis'] select.kp-field__input::picker-icon {
        color: var(--primary);
    }

    [data-theme='lapis'] .kp-field__check {
        accent-color: var(--primary);
    }

    [data-theme='lapis'] .kp-fieldset {
        border: 1px solid var(--border-strong);
    }

    [data-theme='lapis'] .kp-form__summary {
        background: var(--card);
        border: 1px solid var(--border-strong);
    }

    /* ── Cards and the dossier: the four-ring frame, the seal ─────────── */

    [data-theme='lapis'] .kp-card {
        background: var(--card);
        border: 1px solid var(--border-strong);
        box-shadow: var(--kp-ring-on-card);
    }

    [data-theme='lapis'] .kp-card__title {
        font-size: 1.3rem;
    }

    /* The stamp: a vermilion plate — the boundary DI1 asks for stays
       intact, and vermilion is never used as text (anatomy.md's own rule),
       only as this filled chip. */
    [data-theme='lapis'] .kp-card[data-kp-label]::before {
        content: attr(data-kp-label);
        position: absolute;
        inset-block-start: 0.9rem;
        inset-inline-end: -0.5rem;
        transform: rotate(-8deg);
        background: var(--accent);
        color: var(--accent-foreground);
        border: 1px solid var(--accent-foreground);
        font-family: var(--theme-font-mono);
        font-size: 0.75rem;
        letter-spacing: 0.12em;
        text-transform: uppercase;
        padding: 0.28em 0.65em;
        border-radius: 3px;
        box-shadow: 0 3px 8px hsl(from var(--sidebar-background) h s l / 0.45);
    }

    [data-theme='lapis'] .kp-card[data-kp-reveal='emphasis'] {
        position: relative;
    }

    /* The seal lifts [§(1)/(5)]: a solid void plate covers the redacted
       phrase; the trigger clears each plate on a stagger, once, never
       autoplaying — the same double-stroke-adjacent idea as the ring
       frame, a plate rather than a fade. */
    [data-theme='lapis'] .kp-card[data-kp-reveal='emphasis'] mark {
        background: var(--sidebar-background);
        color: transparent;
        padding: 0 0.25em;
        border-radius: 3px;
        border-bottom: 0;
    }

    [data-theme='lapis'] .kp-card[data-kp-reveal='emphasis'] mark.is-cleared {
        background: transparent;
        color: inherit;
    }

    [data-theme='lapis'] .kp-dialog,
    [data-theme='lapis'] .kp-popover,
    [data-theme='lapis'] .kp-menu,
    [data-theme='lapis'] .kp-toast,
    [data-theme='lapis'] .kp-tooltip,
    [data-theme='lapis'] .kp-confirm,
    [data-theme='lapis'] .kp-datepicker__panel,
    [data-theme='lapis'] .kp-combobox__list,
    [data-theme='lapis'] .kp-palette,
    [data-theme='lapis'] .kp-theme-menu {
        background: var(--popover);
        color: var(--popover-foreground);
        border: 1px solid var(--border-strong);
        box-shadow: var(--kp-ring-on-popover);
    }

    [data-theme='lapis'] .kp-menu__item:hover {
        background: var(--card);
        color: var(--primary);
    }

    [data-theme='lapis'] .kp-alert {
        background: var(--card);
        border: 1px solid var(--border-strong);
    }

    [data-theme='lapis'] .kp-alert__label {
        font-family: var(--theme-font-display);
        font-weight: 600;
    }

    [data-theme='lapis'] .kp-grid__tile,
    [data-theme='lapis'] .kp-split__pane {
        background: var(--card);
        border: 1px solid var(--border-strong);
    }

    [data-theme='lapis'] .kp-split__separator {
        background: var(--border-strong);
    }

    /* The footer: one step down, the void. */
    [data-theme='lapis'] .kp-footer {
        background: var(--sidebar-background);
        color: var(--muted-foreground);
    }

    [data-theme='lapis'] .kp-footer h4 {
        font-family: var(--theme-font-display);
        font-weight: 600;
        color: var(--primary);
    }

    [data-theme='lapis'] .kp-footer a {
        color: var(--muted-foreground);
    }

    [data-theme='lapis'] .kp-footer a:hover,
    [data-theme='lapis'] .kp-footer a:focus-visible {
        color: var(--primary);
    }

    [data-theme='lapis'] .kp-footer .microlabel {
        color: var(--muted-foreground);
        border-block-start: 1px solid var(--border);
        padding-block-start: 1rem;
    }

    /* ── Badges, tags, status ──────────────────────────────────────────── */

    [data-theme='lapis'] .kp-badge,
    [data-theme='lapis'] .kp-tag {
        border: 1px solid var(--border-strong);
        font-family: var(--theme-font-mono);
        letter-spacing: 0.04em;
    }

    [data-theme='lapis'] .kp-skeleton {
        background: var(--card);
    }

    [data-theme='lapis'] .kp-progress {
        background: var(--background);
        border: 1px solid var(--border-strong);
        padding: 1px;
    }

    [data-theme='lapis'] .kp-progress__value {
        background: var(--primary);
    }

    [data-theme='lapis'] .kp-spinner {
        border-color: var(--border);
        border-top-color: var(--primary);
    }

    [data-theme='lapis'] .kp-empty {
        border: 1px dashed var(--border-strong);
    }

    [data-theme='lapis'] .kp-error {
        color: var(--destructive);
    }

    /* ── Text shapes ──────────────────────────────────────────────────── */

    [data-theme='lapis'] .kp-id,
    [data-theme='lapis'] .kp-url,
    [data-theme='lapis'] .kp-numeric,
    [data-theme='lapis'] .kp-timestamp,
    [data-theme='lapis'] .kp-masked,
    [data-theme='lapis'] .kp-copyable,
    [data-theme='lapis'] .kp-truncate,
    [data-theme='lapis'] .kp-cell-break,
    [data-theme='lapis'] .kp-cell-truncate {
        font-family: var(--theme-font-mono);
        letter-spacing: 0.02em;
    }

    [data-theme='lapis'] .kp-timestamp,
    [data-theme='lapis'] .kp-id {
        color: var(--muted-foreground);
    }

    [data-theme='lapis'] .kp-copyable__button {
        border: 1px solid var(--border-strong);
        background: transparent;
    }

    /* ── Data ─────────────────────────────────────────────────────────── */

    [data-theme='lapis'] .kp-table th {
        font-family: var(--theme-font-mono);
        letter-spacing: 0.06em;
        text-transform: uppercase;
        color: var(--muted-foreground);
        border-bottom: 1px solid var(--border-strong);
    }

    [data-theme='lapis'] .kp-table td {
        border-bottom: 1px solid var(--border);
    }

    [data-theme='lapis'] .kp-table tbody tr:hover {
        background: var(--card);
    }

    [data-theme='lapis'] .kp-datatable {
        border: 1px solid var(--border-strong);
    }

    [data-theme='lapis'] .kp-datatable__bar {
        border-bottom: 1px solid var(--border);
    }

    [data-theme='lapis'] .kp-datatable__sort[aria-sort] {
        color: var(--primary);
    }

    [data-theme='lapis'] .kp-diff {
        background: var(--card);
        border: 1px solid var(--border-strong);
    }

    [data-theme='lapis'] .kp-timeline {
        border-inline-start: 1px dashed var(--border-strong);
    }

    [data-theme='lapis'] .kp-timeline__marker {
        background: var(--primary);
    }

    [data-theme='lapis'] .kp-timeline__when {
        color: var(--muted-foreground);
    }

    [data-theme='lapis'] .kp-tree {
        font-family: var(--theme-font-mono);
    }

    [data-theme='lapis'] .kp-reorder {
        border: 1px solid var(--border-strong);
    }

    /* ── Navigation and steps ─────────────────────────────────────────── */

    [data-theme='lapis'] .kp-tab {
        color: var(--muted-foreground);
    }

    [data-theme='lapis'] .kp-tab[aria-selected='true'] {
        background: var(--primary);
        color: var(--primary-foreground);
    }

    [data-theme='lapis'] .kp-tabs__list {
        border-bottom: 1px solid var(--border-strong);
    }

    [data-theme='lapis'] .kp-pagination a[aria-current],
    [data-theme='lapis'] .kp-pagination [aria-current] {
        background: var(--primary);
        color: var(--primary-foreground);
    }

    [data-theme='lapis'] .kp-wizard {
        border: 1px solid var(--border-strong);
        background: var(--card);
    }

    /* ── Pickers and palettes ─────────────────────────────────────────── */

    [data-theme='lapis'] .kp-datepicker__day[aria-selected='true'] {
        background: var(--primary);
        color: var(--primary-foreground);
    }

    [data-theme='lapis'] .kp-colorpicker__swatch {
        border: 1px solid var(--border-strong);
    }

    [data-theme='lapis'] .kp-shortcuts__row kbd {
        border: 1px solid var(--border-strong);
        background: transparent;
    }

    /* ── The demo's own pieces [S46] ──────────────────────────────────── */

    /* The laurels: three small plates of the workshop's own record. */
    [data-theme='lapis'] .kp-laurels {
        gap: 1rem;
        font-size: 0.85rem;
        color: var(--muted-foreground);
    }

    [data-theme='lapis'] .kp-laurels b {
        color: var(--primary);
        font-family: var(--theme-font-display);
        font-size: 1.05rem;
    }

    [data-theme='lapis'] .kp-platforms {
        font-family: var(--theme-font-mono);
        font-size: 0.78rem;
        letter-spacing: 0.06em;
        text-transform: uppercase;
        color: var(--muted-foreground);
    }

    /* The spec sheet: the four-ring frame, the mono values. */
    [data-theme='lapis'] .kp-spec {
        background: var(--card);
        color: var(--card-foreground);
        border: 1px solid var(--border-strong);
        border-radius: var(--radius);
        box-shadow: var(--kp-ring-on-card);
        padding: 1.1rem 1.2rem 1.3rem;
        font-family: var(--theme-font-mono);
        font-size: 0.8rem;
        line-height: 1.7;
    }

    [data-theme='lapis'] .kp-spec dt {
        color: var(--muted-foreground);
        letter-spacing: 0.1em;
        text-transform: uppercase;
    }

    [data-theme='lapis'] .kp-spec__swatch {
        border: 1px solid var(--border-strong);
        border-radius: 4px;
    }

    [data-theme='lapis'] .kp-spec__font {
        font-family: var(--theme-font-display);
        color: var(--primary);
    }

    /* ── The roots the rules above reach only by their parts ──────────── */

    [data-theme='lapis'] .kp-field {
        gap: 4px;
    }

    [data-theme='lapis'] .kp-form {
        gap: 1rem;
    }

    [data-theme='lapis'] .kp-table {
        border-collapse: separate;
        border-spacing: 0;
    }

    [data-theme='lapis'] .kp-grid {
        gap: 1rem;
    }

    [data-theme='lapis'] .kp-split {
        gap: 0;
    }

    [data-theme='lapis'] .kp-toasts {
        gap: 0.6rem;
    }

    [data-theme='lapis'] .kp-health {
        font-family: var(--theme-font-mono);
        letter-spacing: 0.04em;
    }

    [data-theme='lapis'] .kp-breadcrumb,
    [data-theme='lapis'] .kp-pagination {
        font-family: var(--theme-font-mono);
        letter-spacing: 0.02em;
    }

    [data-theme='lapis'] .kp-combobox,
    [data-theme='lapis'] .kp-datepicker,
    [data-theme='lapis'] .kp-colorpicker,
    [data-theme='lapis'] .kp-shortcuts {
        border-radius: var(--radius);
    }

    /* ── The scrollbar joins the theme ────────────────────────────────── */

    [data-theme='lapis'] {
        scrollbar-color: var(--border-strong) var(--background);
    }

    /* ── Motion, guarded [DI7] ────────────────────────────────────────── */

    /* Every animation and transition of this register lives here, inside
       the no-preference guard, so a reader who asked for reduced motion
       never receives one: the rest states above are what they get. The
       durations are literal because check-motion.mjs computes DI5's rate
       from them; the matching --kp-* knobs are what js/effects.js reads. */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='lapis'] [data-kp-reveal='headline'].is-gilding {
            animation: kp-burnish var(--kp-burnish) var(--fx-ease) 1 both;
        }

        [data-theme='lapis'] [data-kp-reveal='rule'].is-in::after {
            animation: kp-rule-in var(--kp-rule) var(--fx-ease) 1 both;
        }

        [data-theme='lapis'] mark {
            transition:
                color var(--kp-inscribe) var(--fx-ease),
                border-bottom-color var(--kp-inscribe) var(--fx-ease);
        }

        [data-theme='lapis'] mark.is-cleared:nth-of-type(2) {
            transition-delay: var(--kp-inscribe-lead);
        }

        [data-theme='lapis'] .kp-card[data-kp-reveal='emphasis'] mark {
            transition:
                background var(--kp-seal) var(--fx-ease),
                color var(--kp-seal) var(--fx-ease);
        }

        [data-theme='lapis'] .kp-card[data-kp-reveal='emphasis'] mark:nth-of-type(2) {
            transition-delay: var(--kp-redact-stagger);
        }

        [data-theme='lapis'] .kp-card[data-kp-reveal='emphasis'] mark:nth-of-type(3) {
            transition-delay: calc(2 * var(--kp-redact-stagger));
        }
    }

    /* ── Motion [DI5, DI7] ────────────────────────────────────────────── */

    /* This keyframe's row is in TIMINGS (js/effects.js) and its OUT_OF_SCOPE
       entry is in gates/check-motion.mjs: a clip-path wipe carries no
       opacity step, so the automatic DI5 scan cannot rate it and the entry
       says why by hand. kp-rule-in is the base layer's shared keyframe. */
    @keyframes kp-burnish {
        0% {
            clip-path: inset(0 100% 0 0);
            filter: brightness(1.7) saturate(0.7);
        }

        65% {
            clip-path: inset(0 0 0 0);
            filter: brightness(1.7) saturate(0.7);
        }

        100% {
            clip-path: inset(0 0 0 0);
            filter: brightness(1);
        }
    }
    /* The band [M1, M4]: Kenny picked this theme's own version over the
       shared one on 2026-09-08 — gold rules over a lapis wash, set wide. */
    [data-theme='lapis'] .kp-marquee {
        border-block: 1px solid var(--primary);
        color: var(--primary);
        background: color-mix(in srgb, var(--primary) 8%, transparent);
        letter-spacing: 0.14em;
        --kp-marquee: 54000ms;
    }

    /* The menu's caption [M3]: the same choice, for the line a consumer
       may put above a dropdown's items. */
    [data-theme='lapis'] .kp-nav__menu[data-kp-menu-label]::before {
        color: var(--primary);
        letter-spacing: 0.16em;
        border-block-end: 1px solid var(--primary);
    }
}

@layer kp.register {
    /* @kp-soft/themes — css/shade-dark-register.css
   The shade-dark register, 5.0.0 [S48, LIFT_PLAN row 24]: the dark half of
   the shade pair. Scoped to [data-theme='shade-dark'] and inert elsewhere;
   opt-in, imported after themes.css. The approved concept demo ("Undertow
   Editorial", 2026-09-08) is the reference for every value here, sourced
   from <scratchpad>/shade-dark-research.md — obsidianassembly.com's
   per-character blur reveal (shortened to word level here), noth.in's
   blurred seam paired with Dark Editorial's gold-hairline device, and the
   tone ladder alone for depth (no elevation shadow, matching
   --fx-lift: 0px and --fx-shadow-offset: 0px already shipped).

   Shade-dark is a one-ground theme: the hero and the app share
   --background (themes/shade-dark/anatomy.md), so a divider that simply
   fades to transparent would fade to the colour it already sits on and
   vanish. The divider below is a radial swell in the NEXT surface's own
   tone plus a hairline fading at both ends, never a literal blur() filter.

   Colour discipline (DI9): nothing here names a colour. Nothing loops;
   every reveal fires once (S42: reported at "What the demo showed" in the
   anatomy, never silently corrected). No texture: --fx-texture stays
   unset, matching "no starfield, no grain" (the anatomy's own rule). */

    [data-theme='shade-dark'] {
        /* The configuration surface [AR43], the demo's values as defaults. */
        --kp-reveal-threshold: 0.6;
        --kp-word-stagger: 90ms;
        --kp-redact-stagger: 150ms;
        --kp-ease-reveal: cubic-bezier(0.2, 0.75, 0.35, 1);
        /* The reveals this theme performs [S45]: js/effects.js reads these
           and leaves a theme that declares none at rest. No --kp-arrival:
           the demo boots with nothing, the way dark and light already do. */
        --kp-reveal-headline: focus;
        --kp-reveal-emphasis: plate;
        --kp-reveal-rule: draw;
    }

    /* ── Type ──────────────────────────────────────────────────────────── */

    [data-theme='shade-dark'] h1,
    [data-theme='shade-dark'] h2,
    [data-theme='shade-dark'] h3,
    [data-theme='shade-dark'] h4 {
        font-family: var(--theme-font-display);
        font-weight: 600;
    }

    /* The base layer paints a title bar behind every h1 on a surface (the
       3.x theme); the demo's reading is plain type, no plate, no shadow —
       the whole point of a reading theme is that a heading is just text. */
    [data-theme='shade-dark'] [data-kp-surface] h1 {
        display: block;
        padding: 0;
        background: none;
        color: var(--foreground);
        font-size: var(--kp-text-display);
        line-height: 1.12;
        letter-spacing: -0.01em;
        margin-block: 0 1rem;
        text-wrap: balance;
    }

    /* Microlabels: plain mono, accent ink — no glyph, no prompt. */
    [data-theme='shade-dark'] .microlabel {
        font-family: var(--theme-font-mono);
        font-size: 0.75rem;
        letter-spacing: 0.12em;
        text-transform: uppercase;
        color: var(--accent);
    }

    /* ── The focus ring: the demo's own global rule (DI2, AR30). An inner
       outline in the foreground and an outer moat in the ground — on any
       surface at least one of the two clears 3:1, which is what the
       invariant asks for. Measured on a primary button: foreground/primary
       1.11 (fails alone), background/primary 5.46 (clears): one channel
       always wins. ─────────────────────────────────────────────────────── */
    [data-theme='shade-dark'] a:focus-visible,
    [data-theme='shade-dark'] button:focus-visible,
    [data-theme='shade-dark'] input:focus-visible,
    [data-theme='shade-dark'] select:focus-visible,
    [data-theme='shade-dark'] textarea:focus-visible,
    [data-theme='shade-dark'] [tabindex]:focus-visible,
    [data-theme='shade-dark'] dialog:focus-visible {
        outline: 2px solid var(--foreground);
        outline-offset: 2px;
        box-shadow: 0 0 0 4px var(--background);
        border-radius: var(--radius);
    }

    /* ── The hooks [S45]: the headline, the mark, the rule, the divider ── */

    /* The headline reveal: words arrive out of a blur, one after another,
       90ms apart. The module wraps the words in [data-word] and sets
       --kp-i; the register moves them. */
    [data-theme='shade-dark'] [data-kp-reveal='headline'] [data-word] {
        display: inline-block;
    }

    /* The rule: a short accent line that draws itself in when its heading
       enters the viewport, the demo's own scaleX transition. */
    [data-theme='shade-dark'] [data-kp-reveal='rule']::after {
        content: '';
        display: block;
        block-size: 2px;
        inline-size: 3rem;
        margin-block-start: 0.5rem;
        background: var(--accent);
        transform-origin: left;
        transform: scaleX(1);
    }

    [data-theme='shade-dark'][data-kp-effects] [data-kp-reveal='rule']:not(.is-in)::after {
        transform: scaleX(0);
    }

    /* The emphasis containers with nothing to clear — the hero CTA and the
       dossier card — settle out of the same blur the headline's words use,
       once, on load (S49 finding: the demo's own words say "on first
       scroll-into-view"; the shared module has no generic per-element
       scroll trigger outside data-kp-reveal="rule", so this plays once the
       page is ready rather than when the reader scrolls to it — kept as
       close to the demo as the module allows, recorded in anatomy.md). */
    [data-theme='shade-dark'] [data-kp-reveal='emphasis'] {
        opacity: 1;
        filter: blur(0);
    }

    /* The mark, outside a card: a static signal plate, no clearing — the
       demo's lede marks never cover and never reveal, unlike the dossier's. */
    [data-theme='shade-dark'] mark {
        background: var(--fx-signal);
        color: var(--fx-signal-foreground);
        font-weight: 600;
        padding: 0.05em 0.35em;
        border-radius: 0.2em;
        white-space: nowrap;
    }

    /* The dossier's marks: ink plates the reader clears left to right. At
       rest (no script, or reduced motion) the text stands plain — the
       plate is a reveal, not a redaction that could hide content. */
    /* white-space: nowrap keeps a redacted phrase on one line: the plate
       below is a single absolutely-positioned box sized to the mark's own
       bounding rect, and a phrase that wrapped across two lines produced
       one oversized plate spanning both — measured and fixed 2026-09-08. */
    [data-theme='shade-dark'] .kp-card[data-kp-reveal='emphasis'] mark {
        position: relative;
        background: none;
        color: var(--card-foreground);
        font-weight: 400;
        padding: 0;
        white-space: nowrap;
    }

    [data-theme='shade-dark'] .kp-card[data-kp-reveal='emphasis'] mark::after {
        content: '';
        position: absolute;
        inset: -0.05em -0.08em;
        background: var(--border-strong);
        border-radius: 0.15em;
        transform-origin: right;
        transform: scaleX(1);
        pointer-events: none;
    }

    [data-theme='shade-dark'][data-kp-effects] .kp-card[data-kp-reveal='emphasis'] mark:not(.is-cleared) {
        color: transparent;
    }

    [data-theme='shade-dark'] .kp-card[data-kp-reveal='emphasis'] mark.is-cleared::after {
        transform: scaleX(0);
    }

    /* The divider: shade-dark shares one ground between hero and app
       (anatomy.md), so a plain fade to transparent would fade to the
       colour it already sits on. The mechanism is a radial swell in the
       NEXT surface's own tone plus a hairline fading at both ends —
       noth.in's blurred-seam idea paired with Dark Editorial's gold-line
       device, neither literally reproduced (S49: no blur() filter, no
       literal gold — both are token-relative here). */
    [data-theme='shade-dark'] [data-kp-divider] {
        position: relative;
        block-size: 7rem;
        margin-block: -2.5rem;
        pointer-events: none;
        z-index: 1;
    }

    [data-theme='shade-dark'] [data-kp-divider]::before {
        content: '';
        position: absolute;
        inset: 0;
        background: radial-gradient(
            ellipse 62% 100% at 50% 50%,
            hsl(from var(--popover) h s l / 0.55) 0%,
            hsl(from var(--popover) h s l / 0.18) 45%,
            transparent 75%
        );
    }

    [data-theme='shade-dark'] [data-kp-divider]::after {
        content: '';
        position: absolute;
        inset-inline: 12%;
        inset-block-start: 50%;
        block-size: 1px;
        background: linear-gradient(to right, transparent, var(--border-strong) 20%, var(--border-strong) 80%, transparent);
        opacity: 0.55;
    }

    [data-theme='shade-dark'] [data-kp-divider='alt']::before {
        background: radial-gradient(
            ellipse 62% 100% at 50% 50%,
            hsl(from var(--secondary) h s l / 0.55) 0%,
            hsl(from var(--secondary) h s l / 0.18) 45%,
            transparent 75%
        );
    }

    /* ── The hero ──────────────────────────────────────────────────────── */

    [data-theme='shade-dark'] [data-kp-surface='hero'] {
        padding-block: 1.5rem 2.5rem;
    }

    [data-theme='shade-dark'] [data-kp-surface='hero'] [data-kp-hero-grid] {
        grid-template-columns: minmax(0, 1.5fr) minmax(0, 1fr);
        gap: clamp(2rem, 5vw, 3.5rem);
        align-items: start;
    }

    @container (max-width: 55rem) {
        [data-theme='shade-dark'] [data-kp-surface='hero'] [data-kp-hero-grid] {
            grid-template-columns: minmax(0, 1fr);
        }
    }

    /* ── The navbar ────────────────────────────────────────────────────── */

    [data-theme='shade-dark'] .kp-nav-wrap {
        background: var(--popover);
        border-bottom: 1px solid var(--border);
    }

    [data-theme='shade-dark'] .kp-nav {
        background: var(--popover);
    }

    [data-theme='shade-dark'] .kp-nav__brand {
        font-family: var(--theme-font-display);
        font-weight: 700;
        color: var(--foreground);
    }

    [data-theme='shade-dark'] .kp-nav__brand-tag {
        font-family: var(--theme-font-mono);
        font-size: 0.68rem;
        letter-spacing: 0.1em;
        color: var(--muted-foreground);
    }

    [data-theme='shade-dark'] .kp-nav__link {
        color: var(--muted-foreground);
        border-radius: var(--radius);
    }

    [data-theme='shade-dark'] .kp-nav__link:hover,
    [data-theme='shade-dark'] .kp-nav__link:focus-visible,
    [data-theme='shade-dark'] .kp-nav__link[aria-current],
    [data-theme='shade-dark'] .kp-nav__links > li:focus-within > .kp-nav__link {
        color: var(--foreground);
        background: none;
    }

    [data-theme='shade-dark'] .kp-nav__link--cta {
        color: var(--accent-foreground);
        background: var(--accent);
        border-radius: var(--radius);
    }

    [data-theme='shade-dark'] .kp-nav__link--cta:hover,
    [data-theme='shade-dark'] .kp-nav__link--cta:focus-visible {
        color: var(--accent-foreground);
        background: hsl(from var(--accent) h s calc(l + 8%));
    }

    /* The dropdown (KT14): a raised panel on the card ground, one boundary
       in border-strong, no shadow — the tone ladder carries the depth. */
    [data-theme='shade-dark'] .kp-nav__menu {
        background: var(--card);
        border: 1px solid var(--border-strong);
        border-radius: var(--radius);
        box-shadow: none;
    }

    [data-theme='shade-dark'] .kp-nav__menu a {
        color: var(--muted-foreground);
        border-radius: var(--radius);
    }

    [data-theme='shade-dark'] .kp-nav__menu a:hover,
    [data-theme='shade-dark'] .kp-nav__menu a:focus-visible {
        color: var(--foreground);
        background: var(--secondary);
    }

    /* ── Buttons ───────────────────────────────────────────────────────── */

    [data-theme='shade-dark'] .kp-button,
    [data-theme='shade-dark'] .kp-icon-button {
        background: var(--secondary);
        color: var(--secondary-foreground);
        border: 1px solid transparent;
        border-radius: var(--radius);
        font-weight: 600;
    }

    [data-theme='shade-dark'] .kp-button:hover {
        background: hsl(from var(--secondary) h s calc(l + 4%));
    }

    [data-theme='shade-dark'] .kp-button--primary {
        background: var(--primary);
        color: var(--primary-foreground);
    }

    [data-theme='shade-dark'] .kp-button--primary:hover {
        background: hsl(from var(--primary) h s calc(l + 7%));
    }

    [data-theme='shade-dark'] .kp-button--ghost {
        background: transparent;
        color: var(--foreground);
        border-color: var(--border-strong);
    }

    [data-theme='shade-dark'] .kp-button--ghost:hover {
        background: var(--card);
    }

    [data-theme='shade-dark'] .kp-button--destructive {
        background: var(--destructive);
        color: var(--destructive-foreground);
    }

    [data-theme='shade-dark'] .kp-button--destructive:hover {
        background: hsl(from var(--destructive) h s calc(l + 8%));
    }

    [data-theme='shade-dark'] .kp-button:disabled {
        opacity: 0.55;
    }

    /* The demo's call-to-action row: wide buttons, as in the reference. A
       pager's or a menu's button keeps its own width (DI11 at 320 px). */
    [data-theme='shade-dark'] [data-kp-surface='hero'] .kp-row > .kp-button {
        min-width: min(11rem, 100%);
    }

    /* ── Fields ────────────────────────────────────────────────────────── */

    [data-theme='shade-dark'] .kp-field__label {
        font-weight: 600;
    }

    [data-theme='shade-dark'] .kp-field__required {
        font-weight: 400;
        color: var(--muted-foreground);
    }

    [data-theme='shade-dark'] .kp-field__input,
    [data-theme='shade-dark'] .kp-datatable__search,
    [data-theme='shade-dark'] .kp-combobox__input,
    [data-theme='shade-dark'] .kp-palette__input {
        background: var(--card);
        border: 1px solid var(--border-strong);
        border-radius: var(--radius);
    }

    [data-theme='shade-dark'] .kp-field__help {
        color: var(--muted-foreground);
    }

    [data-theme='shade-dark'] .kp-field--invalid .kp-field__input {
        border-color: var(--destructive);
    }

    [data-theme='shade-dark'] .kp-field__error {
        color: var(--destructive);
    }

    [data-theme='shade-dark'] .kp-field__check {
        accent-color: var(--primary);
    }

    [data-theme='shade-dark'] .kp-fieldset {
        border: 1px solid var(--border);
        border-radius: var(--radius);
    }

    [data-theme='shade-dark'] .kp-form__summary {
        background: var(--card);
        border: 1px solid var(--border);
        border-radius: var(--radius);
    }

    /* ── Cards, popovers and surfaces: the tone ladder alone, no shadow ─── */

    [data-theme='shade-dark'] .kp-card,
    [data-theme='shade-dark'] .kp-popover {
        background: var(--card);
        border: 1px solid var(--border);
        border-radius: var(--radius);
        box-shadow: none;
    }

    [data-theme='shade-dark'] .kp-card__stamp {
        font-family: var(--theme-font-mono);
        font-size: 0.68rem;
        text-transform: uppercase;
        letter-spacing: 0.1em;
        color: var(--status-draft-foreground);
        background: var(--status-draft);
        border-radius: 0.2rem;
    }

    [data-theme='shade-dark'] .kp-dialog,
    [data-theme='shade-dark'] .kp-menu,
    [data-theme='shade-dark'] .kp-toast,
    [data-theme='shade-dark'] .kp-tooltip,
    [data-theme='shade-dark'] .kp-confirm,
    [data-theme='shade-dark'] .kp-datepicker__panel,
    [data-theme='shade-dark'] .kp-combobox__list,
    [data-theme='shade-dark'] .kp-palette,
    [data-theme='shade-dark'] .kp-theme-menu {
        background: var(--popover);
        color: var(--foreground);
        border: 1px solid var(--border-strong);
        border-radius: var(--radius);
        box-shadow: none;
    }

    [data-theme='shade-dark'] .kp-menu__item:hover {
        background: var(--secondary);
        color: var(--secondary-foreground);
    }

    [data-theme='shade-dark'] .kp-alert {
        background: var(--card);
        border: 1px solid var(--border);
        border-radius: var(--radius);
    }

    [data-theme='shade-dark'] .kp-grid {
        gap: 0.75rem;
    }

    [data-theme='shade-dark'] .kp-grid__tile,
    [data-theme='shade-dark'] .kp-split__pane {
        background: var(--card);
        border: 1px solid var(--border);
        border-radius: var(--radius);
    }

    [data-theme='shade-dark'] .kp-split__separator {
        background: var(--border);
    }

    [data-theme='shade-dark'] .kp-toasts {
        gap: 0.6rem;
    }

    /* ── Footer ────────────────────────────────────────────────────────── */

    [data-theme='shade-dark'] .kp-footer {
        background: var(--popover);
        border-top: 1px solid var(--border);
    }

    [data-theme='shade-dark'] .kp-footer a {
        color: var(--muted-foreground);
    }

    [data-theme='shade-dark'] .kp-footer a:hover,
    [data-theme='shade-dark'] .kp-footer a:focus-visible {
        color: var(--foreground);
    }

    /* ── Badges, tags, status ──────────────────────────────────────────── */

    [data-theme='shade-dark'] .kp-badge,
    [data-theme='shade-dark'] .kp-tag {
        border-radius: 0.25rem;
    }

    [data-theme='shade-dark'] .kp-health {
        color: var(--muted-foreground);
    }

    [data-theme='shade-dark'] .kp-health__dot {
        border-radius: 50%;
    }

    [data-theme='shade-dark'] .kp-skeleton {
        background: var(--card);
        border-radius: var(--radius);
    }

    [data-theme='shade-dark'] .kp-progress {
        background: var(--card);
        border-radius: var(--radius);
    }

    [data-theme='shade-dark'] .kp-progress__value {
        background: var(--primary);
    }

    [data-theme='shade-dark'] .kp-spinner {
        border-color: var(--border);
        border-top-color: var(--primary);
    }

    [data-theme='shade-dark'] .kp-empty {
        border: 1px dashed var(--border);
        border-radius: var(--radius);
    }

    [data-theme='shade-dark'] .kp-error {
        color: var(--destructive);
    }

    /* ── Text shapes: identifiers in mono ──────────────────────────────── */

    [data-theme='shade-dark'] .kp-id,
    [data-theme='shade-dark'] .kp-url,
    [data-theme='shade-dark'] .kp-numeric,
    [data-theme='shade-dark'] .kp-timestamp,
    [data-theme='shade-dark'] .kp-masked,
    [data-theme='shade-dark'] .kp-copyable,
    [data-theme='shade-dark'] .kp-truncate,
    [data-theme='shade-dark'] .kp-cell-break,
    [data-theme='shade-dark'] .kp-cell-truncate {
        font-family: var(--theme-font-mono);
        letter-spacing: 0.01em;
    }

    [data-theme='shade-dark'] .kp-copyable__button {
        border-radius: var(--radius);
    }

    /* ── Data ──────────────────────────────────────────────────────────── */

    [data-theme='shade-dark'] .kp-table {
        border-collapse: separate;
        border-spacing: 0;
    }

    [data-theme='shade-dark'] .kp-table th {
        color: var(--muted-foreground);
        border-bottom: 1px solid var(--border-strong);
        font-weight: 600;
    }

    [data-theme='shade-dark'] .kp-table td {
        border-bottom: 1px solid var(--border);
    }

    [data-theme='shade-dark'] .kp-table tbody tr:hover {
        background: var(--card);
    }

    [data-theme='shade-dark'] .kp-datatable {
        border: 1px solid var(--border);
        border-radius: var(--radius);
        background: var(--card);
    }

    [data-theme='shade-dark'] .kp-datatable__bar {
        background: var(--popover);
        border-bottom: 1px solid var(--border);
    }

    [data-theme='shade-dark'] .kp-datatable__sort[aria-sort] {
        color: var(--primary);
    }

    [data-theme='shade-dark'] .kp-diff {
        background: var(--card);
        border: 1px solid var(--border);
        border-radius: var(--radius);
    }

    [data-theme='shade-dark'] .kp-timeline {
        border-inline-start: 2px solid var(--border);
    }

    [data-theme='shade-dark'] .kp-timeline__marker {
        background: var(--primary);
    }

    [data-theme='shade-dark'] .kp-tree {
        font-family: var(--theme-font-mono);
    }

    [data-theme='shade-dark'] .kp-reorder {
        background: var(--card);
        border: 1px solid var(--border);
        border-radius: var(--radius);
    }

    /* ── Navigation and steps ──────────────────────────────────────────── */

    [data-theme='shade-dark'] .kp-tab {
        color: var(--muted-foreground);
        border-radius: var(--radius) var(--radius) 0 0;
    }

    [data-theme='shade-dark'] .kp-tab[aria-selected='true'] {
        color: var(--foreground);
        border-bottom: 2px solid var(--accent);
    }

    [data-theme='shade-dark'] .kp-tabs__list {
        border-bottom: 1px solid var(--border);
    }

    [data-theme='shade-dark'] .kp-breadcrumb {
        color: var(--muted-foreground);
    }

    [data-theme='shade-dark'] .kp-pagination {
        color: var(--muted-foreground);
    }

    [data-theme='shade-dark'] .kp-pagination a[aria-current],
    [data-theme='shade-dark'] .kp-pagination [aria-current] {
        background: var(--primary);
        color: var(--primary-foreground);
        border-radius: var(--radius);
    }

    [data-theme='shade-dark'] .kp-wizard {
        background: var(--card);
        border: 1px solid var(--border);
        border-radius: var(--radius);
    }

    /* ── Pickers and palettes ──────────────────────────────────────────── */

    [data-theme='shade-dark'] .kp-datepicker__day[aria-selected='true'] {
        background: var(--primary);
        color: var(--primary-foreground);
        border-radius: var(--radius);
    }

    [data-theme='shade-dark'] .kp-colorpicker__swatch {
        border: 1px solid var(--border-strong);
        border-radius: var(--radius);
    }

    [data-theme='shade-dark'] .kp-shortcuts__row kbd {
        border: 1px solid var(--border-strong);
        border-radius: 0.2rem;
        background: var(--card);
        font-family: var(--theme-font-mono);
    }

    /* ── The roots the rules above reach only by their parts ────────────── */

    [data-theme='shade-dark'] .kp-combobox,
    [data-theme='shade-dark'] .kp-datepicker,
    [data-theme='shade-dark'] .kp-colorpicker,
    [data-theme='shade-dark'] .kp-shortcuts,
    [data-theme='shade-dark'] .kp-tabs {
        border-radius: var(--radius);
    }

    [data-theme='shade-dark'] .kp-field {
        gap: 0.35rem;
    }

    [data-theme='shade-dark'] .kp-form {
        gap: 1.1rem;
    }

    [data-theme='shade-dark'] .kp-split {
        gap: 0;
    }

    /* ── The scrollbar joins the theme ──────────────────────────────────── */

    [data-theme='shade-dark'] {
        scrollbar-color: var(--border-strong) var(--card);
    }

    /* ── The demo's own pieces [S46] ─────────────────────────────────────── */

    [data-theme='shade-dark'] .kp-side-note {
        font-family: var(--theme-font-mono);
        font-size: 0.72rem;
        letter-spacing: 0.14em;
        text-transform: uppercase;
        color: var(--muted-foreground);
    }

    [data-theme='shade-dark'] .kp-laurels {
        color: var(--muted-foreground);
    }

    [data-theme='shade-dark'] .kp-laurels b {
        color: var(--foreground);
    }

    [data-theme='shade-dark'] .kp-lede {
        max-width: 42rem;
    }

    [data-theme='shade-dark'] .kp-platforms {
        font-family: var(--theme-font-mono);
        font-size: 0.78rem;
        color: var(--muted-foreground);
    }

    [data-theme='shade-dark'] .kp-platforms span::before {
        content: '· ';
        color: var(--border-strong);
    }

    [data-theme='shade-dark'] .kp-platforms span:first-child::before {
        content: '';
    }

    [data-theme='shade-dark'] .kp-spec {
        background: var(--card);
        border: 1px solid var(--border);
        border-radius: var(--radius);
    }

    [data-theme='shade-dark'] .kp-spec dt {
        color: var(--muted-foreground);
    }

    [data-theme='shade-dark'] .kp-spec__swatch {
        border: 1px solid var(--border-strong);
        border-radius: 0.25rem;
    }

    [data-theme='shade-dark'] .kp-spec__font {
        font-family: var(--theme-font-display);
    }

    /* ── Motion, guarded [DI7] ─────────────────────────────────────────── */

    /* Every animation and transition of this register lives here, inside
       the no-preference guard, so a reader who asked for reduced motion
       never receives one: the rest states above (rule drawn, mark plain,
       card and button in full focus) are what they get. */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='shade-dark'] [data-kp-reveal='headline'].is-words [data-word] {
            animation: kp-focus 600ms var(--kp-ease-reveal) both;
            animation-delay: calc(var(--kp-i, 0) * var(--kp-word-stagger));
        }

        [data-theme='shade-dark'] [data-kp-reveal='rule']::after {
            transition: transform 500ms var(--kp-ease-reveal);
        }

        /* The emphasis containers with nothing to clear settle out of the
           blur once, on load (see the finding above the rest-state rule). */
        [data-theme='shade-dark'][data-kp-effects] [data-kp-reveal='emphasis'] {
            animation: kp-focus-in 500ms var(--kp-ease-reveal) both;
        }

        [data-theme='shade-dark'] .kp-card[data-kp-reveal='emphasis'] mark::after {
            transition: transform 300ms var(--kp-ease-reveal);
        }

        [data-theme='shade-dark'] .kp-card[data-kp-reveal='emphasis'] mark:nth-of-type(2)::after {
            transition-delay: var(--kp-redact-stagger);
        }

        [data-theme='shade-dark'] .kp-card[data-kp-reveal='emphasis'] mark:nth-of-type(3)::after {
            transition-delay: calc(2 * var(--kp-redact-stagger));
        }

        /* The colour switches the instant the plate starts to recede: the
           text sits behind the plate at that moment, so nothing is ever
           read mid-transition (KT8). */
        [data-theme='shade-dark'] .kp-card[data-kp-reveal='emphasis'] mark {
            transition: color 0s linear 0s;
        }

        /* The dialog: opacity and a small settle, 180ms — the same
           --fx-duration this theme already ships (demo comment 2). */
        [data-theme='shade-dark'] .kp-dialog {
            animation: kp-dialog-in 180ms var(--fx-ease) both;
        }

        [data-theme='shade-dark'] .kp-dialog::backdrop {
            animation: kp-backdrop-in 180ms var(--fx-ease) both;
        }

        [data-theme='shade-dark'] .kp-button,
        [data-theme='shade-dark'] .kp-nav__link,
        [data-theme='shade-dark'] .kp-nav__link--cta,
        [data-theme='shade-dark'] .kp-nav__menu,
        [data-theme='shade-dark'] .kp-nav__menu a,
        [data-theme='shade-dark'] .kp-footer a,
        [data-theme='shade-dark'] .skip-link {
            transition:
                background var(--fx-duration) var(--fx-ease),
                color var(--fx-duration) var(--fx-ease),
                opacity var(--fx-duration) var(--fx-ease),
                transform var(--fx-duration) var(--fx-ease),
                visibility var(--fx-duration) var(--fx-ease);
        }
    }

    /* ── Motion [DI5, DI7] ────────────────────────────────────────────── */

    /* Every keyframe here has its row in TIMINGS (js/effects.js). The
       headline's words and the emphasis containers' entrance are the same
       blur-and-focus device at two grains; the dialog's pair is opacity
       with a small settle, once, on open. */
    @keyframes kp-focus {
        0% {
            opacity: 0;
            filter: blur(6px);
        }

        100% {
            opacity: 1;
            filter: blur(0);
        }
    }

    @keyframes kp-focus-in {
        0% {
            opacity: 0;
            filter: blur(6px);
        }

        100% {
            opacity: 1;
            filter: blur(0);
        }
    }

    @keyframes kp-dialog-in {
        0% {
            opacity: 0;
            transform: translateY(6px) scale(0.98);
        }

        100% {
            opacity: 1;
            transform: none;
        }
    }

    @keyframes kp-backdrop-in {
        0% {
            opacity: 0;
        }

        100% {
            opacity: 1;
        }
    }
    /* The band [M1, M4]: Kenny picked this theme's own version over the
       shared one on 2026-09-08 — the same fade in the dark. */
    [data-theme='shade-dark'] .kp-marquee {
        mask-image: linear-gradient(90deg, transparent, black 12%, black 88%, transparent);
        color: var(--muted-foreground);
        font-family: var(--theme-font-mono);
        --kp-marquee: 46000ms;
    }

    /* The menu's caption [M3]: the same choice, for the line a consumer
       may put above a dropdown's items. */
    [data-theme='shade-dark'] .kp-nav__menu[data-kp-menu-label]::before {
        font-family: var(--theme-font-mono);
        text-transform: none;
        letter-spacing: 0;
        color: var(--muted-foreground);
        border-block-end: 0;
    }
}

@layer kp.layout {
    /* @kp-soft/themes — css/layout.css
       The layout layer [TH90, TH91, S22].

       Sixteen classes, and the reason they exist is measured rather than
       assumed: the chassis kit wrote 71 lines of its own layout glue plus
       28 inline style attributes, and its stylesheet header said in so many
       words that this is "layout glue and the few utilities @kp-soft/themes
       deliberately does not ship". These are those.

       Every class reads a knob with the scale as its default, so a page or
       a theme retunes it without rewriting the rule (KT6). Nothing here
       paints a colour that is not a token (DI9).

       The layer matters: kp.layout sits after kp.components, so adding
       .kp-stack to a component that sets its own gap wins — which is what
       someone reaching for a layout class means (AR17). */

    /* ── Containers ─────────────────────────────────────────────────── */

    /* The page itself: a measure to read within, centred, with margins that
       shrink on a phone instead of stepping at a breakpoint. */
    .kp-page {
        max-inline-size: var(--kp-page-max, 64rem);
        margin-inline: auto;
        padding-inline: var(--kp-page-pad, clamp(var(--kp-space-md), 3vw, var(--kp-space-xl)));
        padding-block: var(--kp-page-pad-block, var(--kp-space-xl));
    }

    /* Vertical rhythm. This is the fault the round started from: two fields
       and a button touched because a field has no vertical margin and
       nothing above it supplied one. */
    .kp-stack {
        display: flex;
        flex-direction: column;
        gap: var(--kp-stack-gap, var(--kp-space-md));
    }

    /* A row that wraps rather than overflowing, aligned on the centre by
       default because that is what a row of controls wants. --end aligns on
       the baseline of the tallest control, which is what a field beside a
       button wants. */
    .kp-row {
        display: flex;
        flex-wrap: wrap;
        gap: var(--kp-row-gap, var(--kp-space-sm));
        align-items: var(--kp-row-align, center);
    }

    .kp-row--end {
        --kp-row-align: flex-end;
    }

    .kp-row--start {
        --kp-row-align: flex-start;
    }

    .kp-row--between {
        justify-content: space-between;
    }

    .kp-row--nowrap {
        flex-wrap: nowrap;
    }

    /* A grid that picks its own column count from the space it has. The
       minimum track is the knob: a card wants 16rem, a tile less. */
    .kp-autogrid {
        display: grid;
        grid-template-columns: repeat(auto-fit, minmax(var(--kp-autogrid-min, 16rem), 1fr));
        gap: var(--kp-autogrid-gap, var(--kp-space-lg));
        /* A little air on all four sides, so the first column's text never
           sits against whatever edge the grid happens to land on (Kenny,
           2026-09-08). The gap keeps the columns apart; this keeps the
           grid off its own container's edge, and it is a knob like every
           other length here [KT6]. */
        padding: var(--kp-autogrid-pad, var(--kp-space-sm));
    }
    /* A tighter minimum, for a grid that must keep its columns on a phone
       (three footer columns at 320px; the concept demo, round six). */
    .kp-autogrid--tight {
        --kp-autogrid-min: 10rem;
    }
    /* A page that uses the whole viewport: two frames side by side need
       the width more than the measure (the compare page, round six). */
    .kp-page--full {
        max-inline-size: none;
    }

    /* Content with a side column that drops below when there is no room for
       both — no media query, so it behaves the same inside a narrow
       container as it does in a narrow window. */
    .kp-sidebar {
        display: flex;
        flex-wrap: wrap;
        gap: var(--kp-sidebar-gap, var(--kp-space-lg));
    }

    .kp-sidebar > .kp-sidebar__aside {
        flex-basis: var(--kp-sidebar-width, 16rem);
        flex-grow: 1;
    }

    .kp-sidebar > .kp-sidebar__main {
        flex-basis: 0;
        flex-grow: 999;
        min-inline-size: var(--kp-sidebar-break, 50%);
    }

    /* A section of a page: space above it, and nothing else. The heading
       inside keeps whatever the theme gives it. */
    .kp-section {
        margin-block-start: var(--kp-section-gap, var(--kp-space-2xl));
    }

    .kp-section:first-child {
        margin-block-start: 0;
    }

    /* A box with a ceiling, centred — the login card, the empty state, the
       one-column form. */
    .kp-center {
        margin-inline: auto;
        max-inline-size: var(--kp-center-max, 28rem);
    }

    /* ── Text and content ───────────────────────────────────────────── */

    /* Running text stops at a readable measure. ch rather than rem, because
       the measure is about characters per line and the themes ship faces of
       very different widths. */
    .kp-prose {
        max-inline-size: var(--kp-prose-max, 65ch);
    }

    .kp-text-muted {
        color: var(--muted-foreground);
    }

    .kp-text-end {
        text-align: end;
    }

    .kp-text-center {
        text-align: center;
    }

    .kp-mono {
        font-family: var(--kp-mono-face, var(--font-mono, ui-monospace, SFMono-Regular, Menlo, monospace));
        font-size: var(--kp-mono-size, 0.9em);
    }

    /* A block of code that breaks rather than widening the page. A key or a
       token has no spaces to break at, which is why anywhere and not
       break-word. */
    .kp-code-block {
        background: var(--card);
        color: var(--card-foreground);
        border: 1px solid var(--border);
        border-radius: var(--radius, 0.5rem);
        padding: var(--kp-space-md) var(--kp-space-lg);
        font-family: var(--kp-mono-face, var(--font-mono, ui-monospace, SFMono-Regular, Menlo, monospace));
        overflow-wrap: anywhere;
        white-space: pre-wrap;
    }

    /* ── State ──────────────────────────────────────────────────────── */

    /* Standing rule 31 says a button that starts something slow shows it.
       The behaviour was already in the package and the styling was not, so
       the chassis kit wrote this rule itself. It belongs here. */
    [aria-busy='true'] {
        opacity: var(--kp-busy-opacity, 0.7);
        cursor: progress;
    }
}

